/* ÇEVİRİ pl · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("pl","olay",{
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Traktat w Brześciu Litewskim: odzyskanie Karsu, Ardahanu i Batumu", "da82636f"], "d": ["Traktat podpisany między Rosją, która wycofała się z wojny po rewolucji bolszewickiej, a państwami centralnymi zamknął front wschodni i zwrócił państwu osmańskiemu Kars, Ardahan i Batum (Elviye-i Selâse), utracone na mocy traktatu berlińskiego z 1878. Była to jedyna zdobycz terytorialna w dziejach osmańskich uzyskana po czterdziestu latach przerwy. Po rozejmie w Mudros region miał jednak ponownie zostać utracony, a ostateczne rozwiązanie przyniósł traktat w Karsie z 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Oddziały osmańskie weszły do Artvinu", "ca7d1778"], "d": ["Oddziały osmańskie, które 25 marca przekroczyły granicę z 1914, ruszyły na Elviye-i Selâse, której Brześć Litewski zwrócił granicę sprzed 1878, i weszły do Artvinu 28 marca 1918. Artvin został oddany Rosji w 1878 jako część sandżaku Batum; hasło TDV o Artvinie podaje powrót jedynie jako „marzec 1918”, dzień podaje Mustafa Sarı.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahan w ręku armii tureckiej", "7fd9e3db"], "d": ["W akcji Elviye-i Selâse armia osmańska po Artvinie zajęła Ardahan 3 kwietnia 1918; Ardahan padł w wojnie 93 w 1877 i został oddany Rosji w 1878. Kars miał zostać zajęty miesiąc później, 25 kwietnia.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Odzyskanie Batumu", "d37a1a0d"], "d": ["Armia osmańska, która po wycofaniu się Rosji z wojny na mocy traktatu w Brześciu Litewskim ruszyła na wschód, odzyskała po czterdziestu latach port Batum, utracony w 1878. Port na wschodnim krańcu Morza Czarnego był morskim wylotem ropy z Baku. Zdobycz trwała tylko siedem miesięcy; po rozejmie w Mudros region miał zostać opuszczony.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selâse: Kars wszedł pod zarząd osmański", "02cbf0b3"], "d": ["W Brześciu Litewskim postanowiono zwrot trzech sandżaków utraconych na mocy traktatu berlińskiego z 1878 — Karsu, Ardahanu i Batumu; armia osmańska weszła do Ardahanu 3 kwietnia, do Batumu 14 kwietnia, a do Karsu 25 kwietnia 1918 i zarząd został faktycznie ustanowiony. Te ziemie, zwane „Elviye-i Selâse”, uznano za rekompensatę strat trwających od wojny 93. Po rozejmie miały zostać ponownie utracone i ostatecznie przyłączone do Turcji dopiero traktatem w Karsie z 1921.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Zajęcie Iğdır — natarcie w dolinie Arasu", "87ebf4d3"], "d": ["W ramach natarcia rozpoczętego w lutym 1918 oddziały tureckie pokonały oddziały ormiańskie pod Serdarabad na północ od Arasu i zajęły Iğdır 20 maja 1918. Iğdır nie wchodził do Elviye-i Selâse, lecz był kazą Sürmeli guberni erywańskiej; po około 180 latach w regionie ustanowiono pierwszy zarząd osmański.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Śmierć Mehmeda V Reşada i wstąpienie na tron Mehmeda VI Vahdeddina", "d302ba07"], "d": ["Mehmed V Reşad, którego dziewięcioletnie panowanie upłynęło w wojnach o Trypolitanię, bałkańskich i światowej, zmarł w najkrytyczniejszym okresie wojny, a na jego miejsce wstąpił na tron brat Vahdeddin pod imieniem Mehmeda VI. Nowy sułtan próbował wyzwolić się spod opieki kadry unionistycznej; gdy po czterech miesiącach podpisano rozejm, musiał kierować likwidacją imperium. Był trzydziestym szóstym i ostatnim sułtanem dynastii osmańskiej.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Przybycie floty Ententy pod Stambuł i faktyczna okupacja miasta", "d10cb14d"], "d": ["Po rozejmie w Mudros flota sprzymierzonych licząca ponad sześćdziesiąt jednostek, złożona z okrętów angielskich, francuskich, włoskich i greckich, zakotwiczyła przed Dolmabahçe, a Stambuł znalazł się faktycznie pod okupacją. Po czterystu sześćdziesięciu pięciu latach stolica po raz pierwszy znalazła się pod kontrolą obcych żołnierzy. Słowa „Jak przyszli, tak odejdą”, które według przekazu wypowiedział w tym samym dniu Mustafa Kemal Pasza, gdy zszedł do Haydarpaşa i zobaczył widok, miały stać się jednym z symbolicznych zdań Walki Narodowej.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Odwrót w regionie Arasu: Iğdır opuszczony", "57572ab4"], "d": ["Zgodnie z postanowieniem rozejmu w Mudros o wycofaniu się za granicę 1914 Yakup Şevki Pasza rozkazem z 21 listopada polecił wycofać oddziały poza granicą brzeską do 4 grudnia; Iğdır i okolice zostały w tym czasie całkowicie opuszczone. Następnie Rząd Aras-Turecki został pod koniec grudnia 1918 obalony przez Ormian.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Anglicy osiedlili się w Artvinie", "e2cb3153"], "d": ["Ponieważ rozejm w Mudros z 30 października 1918 postawił warunek wycofania armii osmańskiej za granicę z 1914, Artvin został opuszczony i 17 grudnia 1918 zajęty przez Anglików. Według hasła TDV o Artvinie okupacja angielska trwała do kwietnia 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Zarząd brytyjski w Batumie po Mudros", "9dd768fc"], "d": ["Zgodnie z rozejmem w Mudros z 30 października 1918 państwo osmańskie musiało wycofać się z Batumu; miasto zostało 24 grudnia 1918 zajęte przez oddziały brytyjskie. Batum, uczyniony w kwietniu 1918 odrębnym ośrodkiem sandżaku, pozostawał od tej daty do lipca 1920 pod kontrolą angielską.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ardahan przeszedł pod panowanie gruzińskie", "97cf47f6"], "d": ["Ardahan, opuszczony po Mudros, został zajęty przez siły gruzińskie 20 kwietnia 1919, w dniach gdy rząd południowo-zachodniego Kaukazu był rozwiązywany przez Anglików. Panowanie gruzińskie miało trwać do 23 lutego 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Preston przekazał zarząd Karsu namiestnikowi ormiańskiemu", "efa81cb0"], "d": ["Angielski dowódca Preston, który 12–13 kwietnia 1919 rozwiązał Rząd Południowo-Zachodniego Kaukazu, 30 kwietnia 1919 zlikwidował tymczasowy rząd rad i przekazał zarząd miasta Ormianinowi Karganofowi, mianowanemu namiestnikiem Karsu; w Karsie rozpoczął się okres zarządu ormiańskiego, który trwał do zwycięstwa Kâzıma Karabekira 30 października 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Kongres w Erzurum: decyzja o oporze narodowym prowincji wschodnich", "41ef0457"], "d": ["Kongres zwołany przez Towarzystwo Obrony Praw Anatolii Wschodniej, odroczony wskutek nacisku angielskiego, otwarto z pięćdziesięcioma sześcioma delegatami i na jego przewodniczącego wybrano Mustafę Kemala Paszę, który zrezygnował ze służby wojskowej. Kongres ogłosił, że ojczyzna w granicach narodowych jest całością, że mandat i protektorat są nie do przyjęcia, a w razie rozpadu rządu naród weźmie swój los we własne ręce. Te uchwały miały po sześciu miesiącach stać się jądrem tekstu Paktu Narodowego (Misâk-ı Millî).", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Kongres w Sivas: zjednoczenie oporu narodowego pod jednym dachem", "0e9ad36b"], "d": ["Kongres, który rozpoczął obrady 4 września 1919 w Sivas Sultânîsi, zjednoczył towarzystwa obrony praw z całego kraju pod nazwą Towarzystwo Obrony Praw Anatolii i Rumelii i wybrał Komitet Reprezentacyjny (Heyet-i Temsîliyye). Propozycję mandatu amerykańskiego po długich dyskusjach odrzucono. Deklaracją opublikowaną 11 września Walka Narodowa stała się jednoośrodkowym, uprawnionym ruchem politycznym i rozpoczęła się otwarta walka o siłę z rządem stambulskim.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Protokół z Amasyi: rozmowy rządu stambulskiego z Komitetem Reprezentacyjnym", "40e6a6ab"], "d": ["Po upadku Damat Ferida i utworzeniu rządu Alego Rızâ Paszy minister marynarki Salih Pasza został wysłany do Amasyi na rozmowy z Komitetem Reprezentacyjnym. Na mocy uzgodnionych protokołów rząd stambulski faktycznie uznał istnienie ruchu anatolijskiego; zgodzono się na zwołanie Meclis-i Meb'ûsan, swobodne przeprowadzenie wyborów i ochronę granic narodowych. Było to pierwsze oficjalne zwycięstwo polityczne Walki Narodowej wobec Stambułu.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Przyjęcie Paktu Narodowego (Misâk-ı Millî) w ostatnim Zgromadzeniu Osmańskim", "6322865e"], "d": ["Tekst Ahd-i Millî, podpisany przez 121 posłów w ostatnim osmańskim Meclis-i Meb'ûsan, przewidywał niepodzielną całość ziem leżących w obrębie linii z Mudros i zamieszkanych przez muzułmańsko-turecką większość, plebiscyt w prowincjach arabskich i Tracji Zachodniej, zniesienie kapitulacji oraz pełną niepodległość polityczną i finansową. Tekst przyjęto jednogłośnie 17 lutego 1920 i ogłoszono światu. Ta deklaracja była zarówno programem politycznym Walki Narodowej, jak i mapą granic, których miano bronić w Lozannie; stała się bezpośrednią przyczyną oficjalnej okupacji Stambułu przez państwa Ententy 16 marca.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Gdy Anglicy się wycofali, Artvin pozostał w Gruzji", "6d086b06"], "d": ["Według hasła TDV o Artvinie okupacja angielska trwała do kwietnia 1920; Anglicy, wycofując się, zostawili miasto Gruzji. Artvin pozostał w rękach Gruzji aż do ultimatum Wielkiego Zgromadzenia Narodowego z 23 lutego 1921.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Batum przekazany zarządowi gruzińskiemu", "6523d095"], "d": ["Oficjalne przekazanie Batumu Gruzinom przez Anglików nastąpiło 7 lipca 1920 (hasło TDV o Batumie podaje tylko „lipiec 1920”). Rząd Ankary 25 lipca zaprotestował przeciw przekazaniu jako „okupacji”.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Traktat w Gümrü: pierwszy traktat międzynarodowy rządu Wielkiego Zgromadzenia Narodowego", "9232c690"], "d": ["Gdy armia frontu wschodniego pod dowództwem Kâzıma Karabekira odzyskała Sarıkamış i Kars, Armenia poprosiła o pokój i na mocy traktatu podpisanego w Gümrü uznała, że nie uznaje Sèvres i rezygnuje z żądań terytorialnych na wschodzie. Ten pierwszy traktat podpisany przez rząd Ankary stał się pierwszym dokumentem międzynarodowym faktycznie odrzucającym Sèvres i otworzył Wielkiemu Zgromadzeniu drogę do prawnego uznania. Granica wschodnia została w ten sposób zabezpieczona i możliwe stało się przesunięcie sił na front zachodni.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["I bitwa pod İnönü: pierwsze zwycięstwo armii regularnej", "4add3719"], "d": ["Nowo utworzona armia regularna zatrzymała siły greckie postępujące w kierunku Bursy na pozycjach İnönü i zmusiła je do odwrotu. Ten sukces o ograniczonej skali wojskowej miał bardzo wielkie skutki polityczne: rząd Ankary został zaproszony na Konferencję Londyńską, otwarto drogę do traktatu moskiewskiego z Rosją Sowiecką i przyjęto Ustawę Teşkilât-ı Esâsiyye. Wewnątrz kraju zaufanie do armii regularnej także się dzięki temu zwycięstwu umocniło.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["II bitwa pod İnönü: ponowne złamanie natarcia greckiego", "a974521c"], "d": ["Armia grecka, która nie osiągnęła wyniku na Konferencji Londyńskiej, przeszła do nowego natarcia z kierunków Bursy i Uşak, lecz ponownie została zatrzymana na wzgórzach İnönü i musiała się wycofać. Telegram Mustafy Kemala Paszy do İsmeta Paszy: „Tam pokonaliście nie tylko wroga, lecz także nieszczęsny los narodu”, został napisany po tym zwycięstwie. Bitwa podniosła międzynarodowy prestiż Walki Narodowej i przyspieszyła proces wycofywania się Włoch z Anatolii.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Porozumienie z Ankary: pokój z Francją i zamknięcie frontu południowego", "35fc32db"], "d": ["Porozumieniem podpisanym w Ankarze z Francją po zwycięstwie nad Sakarią wojna na froncie południowym się zakończyła; siły francuskie, opuściwszy Çukurovę i Południowy Wschód łącznie z Adaną, Antepem, Maraşem i Urfą, wycofały się na granicę syryjską. Jedno z państw Ententy faktycznie uznało w ten sposób rząd Ankary i na froncie Sèvres otworzyła się pierwsza rysa. Broń przejęta z opuszczonych regionów i uwolnione oddziały odegrały kluczową rolę w przygotowaniach do Wielkiej Ofensywy.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Rozejm w Mudanyi: bezwojenne przekazanie Stambułu i cieśnin", "ac0d9baf"], "d": ["Konferencja zebrana w Mudanyi, gdy po Wielkiej Ofensywie armia turecka stanęła naprzeciw sił angielskich pod Çanakkale i İzmitem, po jedenastodniowych trudnych targach zakończyła się rozejmem. Zgodzono się, że Tracja Wschodnia aż po Marycę zostanie w ciągu piętnastu dni opuszczona przez Grecję i przekazana pod zarząd turecki oraz że Stambuł i cieśniny zostaną oddane traktatem pokojowym. W ten sposób zbrojna faza Walki Narodowej zamknęła się dyplomatycznym zwycięstwem wywalczonym bez jednego wystrzału i otwarto bramę Lozanny.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Wyjazd Mehmeda VI Vahdeddina ze Stambułu i wybór Abdülmecida Efendiego na kalifa", "8ab0e847"], "d": ["Ostatni sułtan Mehmed VI Vahdeddin, którego pozycja stała się sporna po zniesieniu sułtanatu, opuścił Stambuł w piątek rano 17 listopada 1922 na angielskim pancerniku Malaya i udał się na Maltę. Wielkie Zgromadzenie Narodowe dwa dni później, 19 listopada, wybrało Abdülmecida Efendiego na kalifa pozbawionego władzy politycznej. Sześćset dwadzieścia trzy lata panowania dynastii osmańskiej w ten sposób faktycznie się skończyły; kalifat miał trwać symbolicznie jeszcze piętnaście miesięcy. Vahdeddin, który przeniósł się na Maltę, a następnie do Włoch, zamieszkał w Villa Nobel w San Remo; jego starania o przyjęcie do kraju muzułmańskiego nie przyniosły skutku i zmarł tam 16 maja 1926, powtórzywszy, że nigdy nie zrzekł się praw do sułtanatu i kalifatu.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Śmierć ostatniego sułtana Mehmeda VI Vahdeddina w San Remo", "7149ed0e"], "d": ["Ostatni sułtan osmański Mehmed Vahdeddin, który po opuszczeniu Stambułu osiadł w mieście San Remo we Włoszech, zmarł 16 maja 1926, nie otrzymawszy wieści o zebraniu kongresu kalifatu (13 maja 1926), w którym oznajmił, że nigdy nie zrzekł się praw do sułtanatu i kalifatu. Był w ciężkiej biedzie; miał 60 000 lirów długu wobec kupców San Remo, a wierzyciele, usłyszawszy o jego śmierci, kazali zająć sprzęty w jego domu.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Zdobycie przez Konuralpa regionu Bolu — Mudurnu, Konurapa i Bolu", "e245cd27"], "d": ["Konuralp, jeden z dowódców Orhana Gazi, zwracając się ku górzystemu regionowi na wschód od Sakaryi, objął zarządem osmańskim region Mudurnu, Konurapa i Bolu; miasteczko na równinie Düzce nazwano jego imieniem. Dokładna data zdobycia jest nieznana; relacja opiera się na przekazie Âşıkpaşazâde. Region był wówczas obszarem pogranicznym zmieniającym właściciela między Candaroğulları a Bizancjum; zdobycie po raz pierwszy zbliżyło Osmanów do zachodniego wybrzeża Morza Czarnego. Po bitwie pod Ankarą region miał ponownie przejść do Candaroğulları, lecz w epoce Zdobywcy miał zostać ostatecznie odzyskany.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Zajęcie bizantyjskich miasteczek na południe od Marmary — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["Po zajęciu Nikei i İzmitu miasteczka, które pozostały w rękach Bizancjum na zachód od równiny Bursy, jedno po drugim weszły pod zarząd osmański. Gölyazı wokół jeziora Uluabat, Kirmasti nad rzeką Susurluk i Mihaliç dopełniły korytarz łączący południowe wybrzeże Marmary z ziemiami Karesi. Te miasteczka poddały się, nie doznawszy długo oblężenia, wskutek odcięcia ich okolic; obecność bizantyjska w regionie została w ten sposób zepchnięta do Zatoki Gemlik.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Korynt (Gördüs) przeszedł do Despotatu Morei", "392495eb"], "d": ["Korynt, od 1358 lenno rodu Acciajuoli z Florencji podległe Księstwu Achai, w 1395 przeszedł w ręce despoty Morei bizantyjskiego Teodora. Miasto pozostawało odtąd pod zarządem despotatu aż do zdobycia osmańskiego.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Aneksja Bejliku Hacıemîroğulları — Ordu i Ünye", "c064f07f"], "d": ["Bejlik turkmeński założony przez Bayrama Beja wokół Ordu i rozszerzony w latach 50. XIV wieku przez jego syna Hacı Emîra był małym, lecz strategicznym państwem przybrzeżnym z ośrodkiem w dzisiejszym Eskipazar: był jedynym obszarem niezależnego panowania między Samsunem a Trapezuntem. Emîr Süleyman w 1398, w akcji Bayezida Błyskawicy w Canik, oznajmił wierność, a po bitwie pod Ankarą bejlik odzyskał wolność. Za Murada II, w tych samych latach co likwidacja Tâceddinoğulları, ziemie bejliku zostały związane bezpośrednio z zarządem osmańskim, a wybrzeże Morza Czarnego od Samsunu po Giresun zjednoczyło się w jednym ręku.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Zdobycie Koryntu (Gördüs)", "87a2bc59"], "d": ["W wyprawie morejskiej Zdobywcy twierdzę Akrokorynt oblegano trzy miesiące i w końcu przyjęto jej poddanie drogą pokojową. Przesmyk koryncki, uchodzący za bramę Morei, przeszedł w ten sposób do Osmanów.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Przyłączenie Czarnogóry do zarządu osmańskiego — Cetinje", "7fdb7cc8"], "d": ["Gdy dynastia Crnojeviciów rządząca Zetą zrzekła się władzy w 1496, górzysty region Czarnogóry, będący zapleczem Szkodry, został objęty bezpośrednim zarządem osmańskim i zorganizowany najpierw jako odrębny sandżak, a następnie jako część sandżaku Szkodry. Klasztor w Cetinje pozostawiono na miejscu jako ośrodek religijny regionu. Wskutek surowości geografii zarząd tu nigdy nie działał tak ściśle jak na nizinach; po dwóch stuleciach władza władyków, która narodziła się z tego samego klasztoru, miała stać się jądrem faktycznej niepodległości.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["Przyjęcie przez twierdzę Bayezid panowania osmańskiego w wyprawie Irakejn", "f29e2e17"], "d": ["Gdy wielki wezyr İbrahim Pasza podczas wyprawy Irakejn przybył w okolice Bingöl, Wan, Toprakkale, Avnik i twierdze Bayezid, wraz z wieloma plemionami kurdyjskimi regionu, zgodziły się wejść pod panowanie osmańskie. Bayezid przyłączył się do Osmanów w wyprawie Selima w 1514, lecz gdy armia zawróciła, Safawidzi odzyskali region.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Ponowne przejście Tabrizu do Safawidów — powrót z Irakejn", "80b8b761"], "d": ["W wyprawie Irakejn armia weszła do Tabrizu, lecz ponieważ głównym celem był Bagdad, w mieście nie zostawiono trwałego garnizonu. Gdy armia, która spędziła zimę w Bagdadzie, wracała na zachód, szach Tahmasp wszedł ponownie do opuszczonego Azerbejdżanu i odzyskał Tabriz. Był to powtarzający się schemat wojen osmańsko-safawidzkich: Tabriz zdobyto pięć razy, a za każdym razem nie utrzymano; miasto miało zyskać długotrwały garnizon osmański dopiero w 1585.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Wpadnięcie Wanu i Erciş w ręce Tahmaspa (stanowisko osmańskie skończyło się w 1534–35)", "cb93d561"], "d": ["W regionie, który w 1534 oddał Wan pod panowanie osmańskie, Ulama Pasza opierał się w twierdzy Wan oblężeniu safawidzkiemu; twierdza przeszła w ręce Safawidów, a siły safawidzkie oblegające Erciş wycofały się dzięki pomocy osmańskiej. Gdy Sulejman dotarł do Ahlat (23 września 1535), Wan był już w rękach Tahmaspa. Wan pozostawał safawidzki do 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["Przejście sandżaku Bayezid pod panowanie safawidzkie (Wan i Erciş już w 1535 były safawidzkie)", "806a2cf1"], "d": ["Sandżak Bayezid, leżący pośrodku granicy osmańsko-safawidzkiej, ponownie wpadł w ręce Iranu (Kaya 2017 wspomina o tym „wraz z Wanem i Erciş”; jednak według Karataşa 2025 i TDV Wan i Erciş wróciły do Safawidów 22 września 1535 — zob. poprzedni wpis); w tej zmianie właściciela niektóre miejsca sandżaku zostały zniszczone. Sandżak wielokrotnie zmieniał właściciela między oboma państwami do ostatniej ćwierci XVI wieku.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["Ponowne przejście sandżaku Bayezid do Osmanów w czasie wyprawy nachiczewańskiej", "cf0171fa"], "d": ["W trzeciej wyprawie irańskiej (nachiczewańskiej) Sulejmana sandżak Bayezid został ponownie objęty zarządem osmańskim. W wyprawie 1554 Bayazıt stał się ważną bazą dla armii; sandżak wszedł ostatecznie pod panowanie osmańskie w 1578.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Utrata Erywania na rzecz szacha Abbasa", "34413cf2"], "d": ["Gdy w latach, w których powstania celâlich zablokowały Anatolię, front wschodni pozostał bez obrony, szach Abbas, który przeorganizował swoją armię na modłę europejską, przeszedł do natarcia. Twierdza Erywań, którą w 1583 kazał zbudować Ferhad Pasza, po siedmiomiesięcznym oblężeniu się poddała. Pierwsze ogniwo linii kaukaskiej zdobytej na mocy traktatu Ferhada Paszy zostało zerwane, a w ciągu następnych trzech lat cały Południowy Kaukaz miał zostać utracony.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Utrata Tbilisi i Gandży", "3fb51753"], "d": ["Po upadku Erywania armia safawidzka postępowała wzdłuż doliny Kury; Gandża, ośrodek Karabachu, i Tbilisi, stolica Gruzji, zostały utracone jedna po drugiej. Państwo osmańskie prowadziło równocześnie na froncie austriackim trwającą trzynaście lat Długą Wojnę i zmagało się w Anatolii z celâlimi; nie było sił, które można by wysłać na wschód. W ten sposób ład szerokich ejaletów kaukaskich ustanowiony traktatem Ferhada Paszy z 1590 faktycznie się skończył.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Utrata Szyrwanu — Szamacha, Baku i Derbent", "81beab11"], "d": ["Prowincja Szyrwan nad Morzem Kaspijskim, zdobyta w wyprawach Özdemiroğlu Osmana Paszy z lat 1578–1585, jako główne źródło handlu jedwabiem przynosiła osmańskim finansom znaczne dochody. Akcja szacha Abbasa skierowana na północ zlikwidowała ten ejalet, zajmując kolejno Szamachę, Baku i Derbent. Strata nie dotyczyła tylko ziemi: droga, którą jedwab irański płynął do Europy przez Osmanów, wyszła spod kontroli, a państwo Safawidów zaczęło sprzedawać jedwab przez Ocean Indyjski.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Utrata Ta'izz", "65f20d53"], "d": ["Osmanowie w 1038 (1629), wraz z panowaniem w Jemenie pozostawionym zarządowi Kâsimîdów w Sanie, opuścili także Ta'izz — pierwszy wielki krok procesu, w którym imamowie zajdyccy odzyskali wnętrze Jemenu.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Utrata Jemenu — panowanie imamów Kâsimîdów", "49e83e3c"], "d": ["Jemen od 1538 był ejaletem osmańskim; opór imamów zajdyckich nigdy jednak nie ustał. Powstanie rozpoczęte przez imama Kâsima rozprzestrzeniło się na cały kraj za czasów jego syna al-Mu'ayyada Muhammada, a garnizony osmańskie były kolejno oblegane. W latach, gdy Murad IV skupił się na Bagdadzie i Erywaniu, nie można było wysłać posiłków; Ta'izz utracono w 1629, a Mokha została w ostatniej fazie tego samego załamania opuszczona 22 października 1635. W 1635 ostatnie oddziały w Sanie i Zabîd również opuściły Jemen. W ten sposób wschodnie wybrzeże Morza Czerwonego pozostawało przez dwieście trzydzieści siedem lat poza imperium i dało się je odzyskać dopiero w 1872. Lahidż (al-Hawta) według TDV İslâm Ansiklopedisi było w rękach Osmanów do 1635; od tej daty wpływy miały imamy zajdyckie.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Opuszczenie Mokha", "c6b3061a"], "d": ["Mustafa Bej opuścił Mokha 10 cemâziyelevvel 1045 (22 października 1635) z pozostałymi siłami i bronią; następnie syn imama Kâsima, Hasan b. Kâsim, mianował do Zabîd i Mokha swoich ludzi i ustanowił kontrolę Kâsimîdów także na wybrzeżu Tihamy.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Utrata Al-Hasa na rzecz Emiratu Banu Chalid", "a9b6131a"], "d": ["Al-Hasa było ejaletem utworzonym w 1550, by zamknąć Portugalii zachodni brzeg Zatoki Perskiej; leżało jednak bardzo daleko od Stambułu, na końcu jednej drogi pustynnej. W latach, gdy oblężenie Krety pochłaniało zasoby, plemię Banu Chalid w regionie pod przywództwem Barraka b. Ghurajra wyparło garnizon osmański i założyło własny emirat. Zachodni brzeg Zatoki pozostawał przez półtora wieku w emiratach plemiennych; w 1795 miał przejść do Saudów, a w 1871 ponownie do Osmanów.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Utrata Prewezy i Vonitsy na rzecz Wenecji — otwarcie wybrzeża Epiru", "1201204c"], "d": ["Wenecja, która przystąpiła do Świętej Ligi, przed rozpoczęciem wyprawy morejskiej zajęła dwie twierdze trzymające wejście do Zatoki Ambrakijskiej: Prewezę i Vonitsę na przeciwległym brzegu. W tym samym lecie padła także Aya Mavra (Lefkada). Te trzy pozycje zapewniły bezpieczne wprowadzenie floty z Morza Jońskiego w głąb Grecji i stały się bazą akcji morejskiej rozpoczynającej się w następnym roku. Preweza i Vonitsa zostały pozostawione Wenecji także w Passarowitz; pod zarząd osmański miały wrócić dopiero w 1798.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Utrata Szolnoku — rozpad linii Cisy", "51c2c8ef"], "d": ["Po upadku Uyvaru w sierpniu armia habsburska zwróciła się na południe i zajęła przyczółek na Cisie, Szolnok. Miasto było jedynym bezpiecznym przejściem między Budą a Siedmiogrodem; jego utrata oznaczała odcięcie od siebie twierdz osmańskich we wschodniej połowie Węgier. Rozstrzygające okazało się to, że w oblężeniu Budy w następnym roku przecięto drogę zaopatrzenia.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Utrata Modonu na rzecz Wenecji", "114c9cc0"], "d": ["Modon na południowo-zachodnim krańcu półwyspu Morea był portem, który Wenecja utraciła trzy stulecia wcześniej i nazywała „jednym z dwojga oczu państwa”. Twierdza oblężona po upadku Koronu została przyjęta w poddanie po ostrzale jednocześnie z lądu i morza. Akcja morejska Morosiniego zajęła w ten sposób całe zachodnie wybrzeże półwyspu i otworzyła drogę w głąb.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Utrata Pécsu", "99d54cf4"], "d": ["Po upadku Budy we wrześniu siły habsburskie zeszły na południe na zachód od Dunaju i zajęły Pécs, pozostający osmański od czasów Sulejmana. Miasto, znane z meczetu Gazi Kâsıma Paszy, było jednym z najrozwiniętszych ośrodków sandżaków ejaletu Budy. Jego utrata oznaczała otwarcie drogi schodzącej na równinę Mohacza; w następnym roku miała tu przeżyć dokładnie klęskę II Mohacza.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Utrata Segedynu", "9fbee1b2"], "d": ["Segedyn u zbiegu Cisy i Maroszu był południową bramą równiny węgierskiej i trzymał drogę do ejaletu Timișoary. Twierdza oblężona po upadku Budy i Pécsu tej samej jesieni szybko się poddała. Utrata trzech twierdz w jednym sezonie była znakiem, że ustanowiona od 1541 osmańska struktura administracyjna na Węgrzech zaczyna się załamywać. Atlas uznaje, że tego samego dnia także Zenta nad Cisą przeszła od Osmanów na stronę habsburską (dzień poddania właściwy dla Zenty nie został odczytany w źródle, dzień wzięto z Segedynu; TDV zenta: od października 1686 rozpoczęły się starcia między Osmanami a sprzymierzonymi pod przewodnictwem Habsburgów — przybliżenie z deklaracją).", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Utrata Patras (Balyabadra) — północna brama Morei", "b9cff63c"], "d": ["Patras u wejścia do Zatoki Korynckiej było portem kontrolującym przejście między Moreą a Rumelią. Po zajęciu miasta przez armię wenecką twierdze po obu brzegach zatoki padły jedna po drugiej, a półwysep został całkowicie odizolowany od lądu. Na końcu tej akcji cała Morea przeszła do Wenecji; region miał być zarządzany do 1715 pod nazwą „Regno di Morea”.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Oddanie Koryntu (Gördüs) Wenecji", "9a25b6b9"], "d": ["Po upadku Patras Korynt został pokojowo pozostawiony Wenecjanom, a ludność muzułmańska opuściła miasto. W sierpniu 1687 armia Morosiniego zbierała się w Koryncie na wyprawę ateńską.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Utrata Egeru", "983391aa"], "d": ["Eger został zdobyty w 1596 w wyprawie, w której osobiście wziął udział Mehmed III, i stał się ośrodkiem ejaletu noszącego jego nazwę. Ta ostatnia wielka twierdza osmańska w Węgrzech Północnych, po klęsce pod II Mohaczem całkowicie otoczona, trwała jeszcze rok i poddała się z głodu. Wraz z jej utratą północne skrzydło państwa osmańskiego na Węgrzech zostało całkowicie zlikwidowane.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Utrata Székesfehérvár — miasta koronacji królów węgierskich", "c6147255"], "d": ["Miasto, w którym przez stulecia koronowano i grzebano królów węgierskich, zostało zajęte w 1543 przez Sulejmana i stało się jednym z najważniejszych ośrodków sandżaków ejaletu Budy. Około dwa lata po upadku Budy twierdza całkowicie odcięta od otoczenia się poddała. Wraz z tą stratą obecność osmańska na zachód od Dunaju została zepchnięta w okolice Sirmium i Osijeku.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Utrata Szigetvár", "834910a7"], "d": ["Szigetvár było twierdzą, w której Sulejman Prawodawca zmarł w 1566 podczas oblężenia, w trzynastej, ostatniej wyprawie; dlatego miało w pamięci osmańskiej miejsce symboliczne. Po stu dwudziestu trzech latach, gdy padły wszystkie otaczające twierdze, poddała się także twierdza chroniona przez bagna. Mauzoleum, w którym pochowano wnętrzności Sulejmana, i otaczające je miasteczko zostały po przejściu pod zarząd habsburski zburzone. W tym samym dniu atlas zapisuje przejście od Osmanów do Habsburgów innej miejscowości: Barcs — podąża za łańcuchem ośrodka-brata Szigetváru (Bánlaky 0017/1449; przybliżenie z deklaracją).", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Utrata Váradu", "6cce360d"], "d": ["Várad był kluczową twierdzą otwierającą się na Siedmiogród, zdobytą w 1660 przez Köprülü Mehmeda Paszę i uczynioną ośrodkiem ejaletu noszącego jego nazwę. Twierdza, która po klęsce pod Slankamenem pozostała całkowicie sama, po blokadzie trwającej blisko dwa lata poddała się z głodu. Wraz z jej utratą wpływy osmańskie w Siedmiogrodzie faktycznie się skończyły, a panowanie habsburskie ustaliło się na wschód od Cisy.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Utrata Yanova — zamknięcie drogi do Siedmiogrodu", "4b5e30d8"], "d": ["Yanova była twierdzą zdobytą w 1658, trzymającą połączenie między Váradem a Timișoarą. Gdy bezpośrednio po upadku Váradu została odcięta od otoczenia, i ona została utracona. W ten sposób ejalet Timișoary został całkowicie odizolowany od północy i do Karłowic trwał jako jedyna ziemia na Węgrzech pozostająca w rękach osmańskich.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Ustanowienie rządów władyków w Czarnogórze — faktyczne oderwanie Cetinje", "a924b778"], "d": ["W latach, gdy wojna Świętej Ligi osłabiła kontrolę osmańską na Bałkanach, metropolia na czele klasztoru w Cetinje stała się urzędem przechodzącym z ojca na syna w rodzie Petrovićów, a region zyskał faktycznie odrębny zarząd. Dzięki niedostępności gór ta władyka przetrwała dwa stulecia w położeniu ani w pełni niezależnym, ani w pełni zależnym; jej niezależność miała zostać uznana prawnie dopiero traktatem berlińskim z 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Odzyskanie Koryntu (Gördüs)", "26f53e3a"], "d": ["Pierwszym wielkim przystankiem wyprawy morejskiej Damada Alego Paszy był Korynt; Osmanowie odzyskali miasto od Wenecjan w czerwcu 1715 i stąd ruszyli dalej na resztę półwyspu.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Natarcie Nâdira: utrata Tabrizu, Nachiczewanu, Hamadanu, Kermanszahu, Maragha i Kasr-ı Şîrîn", "d95efd59"], "d": ["Miasta Zachodniego Iranu zajęte w latach 1723–1727 dzięki załamaniu się państwa Safawidów zostały jedno po drugim utracone wskutek natarcia Nâdira Chana, który przejął faktyczną władzę w Iranie. W Azerbejdżanie także Ardabil i Chalchal wpadły w ręce Nâdira. Utrata Hamadanu, Kermanszahu i Kasr-ı Şîrîn wywołała w Stambule ciężki oddźwięk; to, że armia nie wyruszyła na wyprawę, lecz czekała w Üsküdar, i próby ukrycia straty były jedną z bezpośrednich przyczyn powstania Patrony Halila wybuchłego po sześciu tygodniach. Atlas uznaje też, że Kotur, podążający za łańcuchem Hoy, przeszedł tego dnia od Osmanów do Safawidów (Uluerler 2015, Turkish Studies 10/5, s. 6; dzień właściwy dla Koturu nie występuje w źródle — przybliżenie z deklaracją).", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Klęska pod Baghavard (Arpaçay) — utrata Kaukazu na rzecz Nâdira Chana", "4262f54c"], "d": ["Ejalety kaukaskie zdobyte w latach 1723–1725, dzięki załamaniu się państwa Safawidów, udało się utrzymać dziesięć lat. Nâdir Chan, który przejął faktyczną władzę w Iranie, zadał armii osmańskiej ciężką klęskę pod Baghavard w pobliżu Erywania; serdar Abdullah Köprülü Pasza poległ na polu bitwy. Po klęsce Erywań, Tbilisi, Gandża i Szyrwan zostały opuszczone w ciągu miesięcy. Granica wschodnia wróciła do linii z Kasr-ı Şîrîn z 1639, co miało zostać potwierdzone w 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Utrata Benderu na rzecz Rosjan", "0daca453"], "d": ["Po klęsce na równinie Kagul armia osmańska wycofała się na południe od Dunaju, a twierdze między Mołdawią a Oczakowem pozostały same. Bender, trzymający punkt przeprawy przez rzekę Turla, został po dwumiesięcznym oblężeniu zdobyty szturmem; miasto złupiono. Utrata twierdzy zerwała środkowe ogniwo linii obrony północnego Morza Czarnego, a po niej padły także Akerman i Kilia. W Küczük Kajnardży Bender miał zostać zwrócony, lecz w 1806 miał zostać utracony ponownie.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["Objęcie emiratu Sabahów w Kuwejcie protekcją osmańską", "3584dba0"], "d": ["Według hasła TDV o Kuwejcie przystań założyło na początku XVIII wieku plemię Utub przybyłe z Nadżdu, a ród Sabahów przejął zarząd ku końcowi stulecia. W tych samych latach, gdy Al-Hasa wpadło w ręce Saudów, emirat, któremu wobec nacisku wahhabitów nie pozostał żaden wybór poza oparciem się o Basrę, wszedł pod protekcję osmańską. Więź ta miała zostać sformalizowana w 1871 uregulowaniem Basry przez Midhata Paszę, a Kuwejt miał być uznawany za jedną z trzech kaz sandżaku Basra; późniejsze pretensje terytorialne Iraku także opierają się na tym zapisie.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Utrata Mekki na rzecz wahhabitów", "2da23acd"], "d": ["Ruch wahhabicki, który narodził się w Nadżdzie, zwrócił się za Suda b. Abd al-Aziza ku Hidżazowi; po Ta'if i Medynie także Mekka została po raz drugi przyjęta w poddanie — emir Mekki szarif Gālib oddał miasto wahhabitom pod warunkiem pozostania na emiracie. Grobowce zburzono, a drogę karawan pielgrzymów z Damaszku i Kairu odcięto; przerwane zostało też w tych latach surre, które sułtan co roku posyłał do Haremejn — jedynym wyjątkiem w przydziale trwającym nieprzerwanie do 1915 jest okres panowania wahhabitów. Ponieważ tytuł protektora Haremejn był jedną z podstaw legitymacji sułtana, ta strata była poza stratą ziemi ciężkim ciosem politycznym; jej odzyskanie miało zająć siedem lat i stać się możliwe dzięki armii Mehmeda Alego Paszy z Kawali.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Koniec Republiki Dubrownickiej — okupacja francuska", "f8e27bf1"], "d": ["Francuzi, którzy na mocy traktatu z Campo Formio (1797) osiedlili się na wybrzeżu Dalmacji, zajęli 27 maja 1806 Dubrownik i położyli kres małej republice kupieckiej. W ten sposób trzy i pół stulecia zależnego statusu Dubrownika, który od 1458 płacąc Osmanom daninę zachowywał autonomię i przywileje handlowe, dobiegło końca; miasto i wyspa Mljet należąca do republiki przechodzą na mapie pod bezpośredni zarząd francuski.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Utrata Suchumi na rzecz Rosjan — otwarcie wybrzeża wschodniego Morza Czarnego", "adc96bd4"], "d": ["W wojnie osmańsko-rosyjskiej 1806–1812 flota rosyjska zwróciła się ku wschodniemu wybrzeżu Morza Czarnego i zajęła w Abchazji Sohumkale, na której opierało się panowanie osmańskie. Twierdza była ośrodkiem łączności z plemionami kaukaskimi i handlu przybrzeżnego. Wraz z jej utratą Rosja po raz pierwszy osiadła trwale na wschodnim wybrzeżu Morza Czarnego; wpływy osmańskie na Kaukazie zostały zepchnięte w okolice Anapy i Poti.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Pozostawienie Pargi pod zarządem osmańskim", "66e0cc5d"], "d": ["Parga od 1401 pozostawała w rękach Wenecji i nigdy nie weszła pod zarząd osmański; po upadku Wenecji przeszła kolejno do Francji i Anglii. Hasło TDV o Alim Paszy z Tepedelen streszcza sytuację tak: miasto poddało się Anglikom i zostało pozostawione zarządowi Alego Paszy dopiero w 1819. Przekazanie zakończyło się emigracją większości mieszkańców na Wyspy Jońskie. W ten sposób ostatnia z trójki Preweza–Parga–Vonitsa, pozostawionej Wenecji w Passarowitz, została przyłączona do imperium; Parga miała pozostać osmańska przez dziewięćdziesiąt cztery lata.", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Przejście Koryntu (Gördüs) w ręce powstańców greckich", "892dcdc6"], "d": ["W czasie greckiej wojny o niepodległość Akrokorynt wpadł w ręce powstańców, a komendant twierdzy Kâmil Bej został wzięty do niewoli.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Utrata Nauplionu (Anabolu) na rzecz powstańców", "1a67fa50"], "d": ["Nauplion, najlepiej umocniony port Morei, po blokadzie trwającej ponad rok poddał się z głodu. Twierdza była od początku powstania ostatnią wielką ostoją kontroli osmańskiej na półwyspie; wraz z jej utratą cała Morea przeszła w ręce powstańców. Miasto miało wkrótce stać się pierwszą stolicą nowego państwa greckiego.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["Przejście Lepanto (İnebahtı) pod zarząd grecki", "c9d19d4b"], "d": ["Lepanto na północnym brzegu Zatoki Korynckiej, pozostające w rękach osmańskich do powstania greckiego, zostało utracone w kwietniu 1829 i weszło pod zarząd grecki; nazwę miasteczka zmieniono na antyczną Naupaktos. Ludność muzułmańska i żydowska miasta całkowicie zniknęła, a miejsce stało się małym miasteczkiem.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Francuska okupacja Algieru — koniec trzystuletniego odżaku", "0be8f568"], "d": ["Pod pretekstem incydentu z wachlarzem, który zrodził się ze sporu o należność, Francja trzymała wybrzeże algierskie w blokadzie przez trzy lata, a następnie wysadziła żołnierzy w Sidi Ferruch. Po trzytygodniowej akcji Hüseyin Dej się poddał, a osmański Odżak Algierski trwający od 1516 dobiegł końca. Okupacja nie ograniczyła się do stolicy; także Tlemcen, Szerszel i Médéa we wnętrzu kraju zostały w to samo lato utracone. Objęcie całego wybrzeża francuską kontrolą miało zająć jeszcze dwadzieścia cztery lata.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Oddanie Negroponte (Eğriboz) Grecji — wraz z wyspą (Karystos, Oreoi)", "7b524aa4"], "d": ["Negroponte, które w czasie greckiej wojny o niepodległość było sceną ciężkich walk, lecz pozostało w rękach osmańskich, zostało po wejściu w życie traktatu pokojowego oddane Grekom w 1831. Muzułmańscy mieszkańcy miasta, będącego od 1470 ważną bazą morską, sprzedali cały majątek za bardzo niskie ceny i masowo wyemigrowali na ziemie osmańskie; miasto długo stało puste, a niemiecki podróżnik Fallmerayer w 1842 nazwał je miastem widmem.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Zajęcie Oranu (Vehrân) przez Francuzów", "a8415d66"], "d": ["Oran, który Hiszpania oddała bez wojny w 1792, był największym portem na zachodzie Algierii. Sześć miesięcy po upadku stolicy oddziały francuskie wkroczyły do miasta. Akcja zachodnia rozpoczęta stąd miała wkrótce spotkać się z piętnastoletnim oporem emira Abd al-Kadira.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Zajęcie Annaby (Bône)", "21f37fb1"], "d": ["Annaba, port wschodniej Algierii blisko granicy z Tunezją, została zajęta przez siły francuskie i uczyniona bazą marszu na Konstantynę. Miasto było też najbliższym portem afrykańskim naprzeciw wyspy Sardynii.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Oddanie Aten nowemu państwu greckiemu (dzień, w którym oddziały bawarskie przejęły Akropol)", "deee4d37"], "d": ["Ateny, osmańskie od 1456, w czasie greckiej wojny o niepodległość kilkakrotnie zmieniały właściciela, a garnizon na Akropolu w 1827 ponownie wszedł pod kontrolę osmańską. Ponieważ miasto pozostało na północ od granicy wytyczonej protokołem londyńskim, zostało przekazane nowemu królestwu, a garnizon opuścił Akropol. Dzień atlasu jest dniem, w którym oddziały bawarskie przejęły Akropol; faktyczne wyjście garnizonu osmańskiego nastąpiło kilka dni później (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, rozdz. 13; Finlay, Journals and Letters, t. I, s. 67). W następnym roku Ateny zostały ogłoszone stolicą Grecji w miejsce Nauplionu.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Zajęcie Bidżaji (Bougie)", "a8927e00"], "d": ["Port Bidżaja, w którym góry Kabylii otwierają się na morze, był ostatnim niezależnym ogniwem linii wybrzeża między Algierem a Annabą. Zajęto go przy wsparciu artylerii okrętowej; leżące za nim górzyste wnętrze miało jednak nie wejść pod kontrolę francuską jeszcze przez trzydzieści lat. Te zajęcia na wybrzeżu tworzą rok po roku topnienie osmańskiego Algieru na mapie.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Zajęcie Sétif", "2073731a"], "d": ["Po upadku Konstantyny rok wcześniej siły francuskie weszły na wyżynę i zajęły dawne rzymskie miasto Sétif, tworząc tu trwały garnizon. Sétif było punktem, w którym krzyżowały się drogi karawan między wybrzeżem a Saharą; jego zajęcie pokazało, że Francja zaczęła kontrolować już nie tylko porty, lecz także wewnętrzną sieć handlową.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Zajęcie Biskry — utrata bramy Sahary", "d895cad0"], "d": ["Biskra była bramą otwierającą się na Saharę u południowego podnóża gór Atlas i ośrodkiem oaz daktylowych. Dzięki jej zajęciu w latach, gdy opór emira Abd al-Kadira zaczął się załamywać, kontrola francuska po raz pierwszy sięgnęła północnego brzegu pustyni. Dalsze działania miały już być akcją pustynną postępującą od oazy do oazy.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Zajęcie Touggourt — utrata całej Algierii", "33c056e2"], "d": ["Wraz z zajęciem oazowego miasta Touggourt na północy Sahary okupacja rozpoczęta w 1830 została dopełniona w północnej połowie dzisiejszej Algierii. Państwo osmańskie walczyło w tych latach w wojnie krymskiej w jednym obozie z Francją; choć nigdy oficjalnie nie zrzekło się prawnych pretensji do Algierii, faktycznie nie mogło zrobić ani kroku. Jedyną ziemią pozostającą w Afryce Północnej była Trypolitania.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Upadek El Obeid — przejście Kordofanu w ręce sił Mahdiego", "58299f62"], "d": ["Ruch rozpoczęty przez Muhammada Ahmada, który ogłosił się mahdim, szybko rozprzestrzenił się przeciw zarządowi egipskiemu w Sudanie. El Obeid, ośrodek Kordofanu, padło po czteromiesięcznym oblężeniu i stało się stolicą powstania; skarbiec i składy broni w mieście pozwoliły ruchowi przekształcić się w armię. Sudan był prawnie nadal ziemią chediwatu Egiptu zależnego od Osmanów, a więc strata wypada na mapie z ciała imperium.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Upadek Chartumu — utrata całego Sudanu", "d4b98464"], "d": ["Po dziesięciomiesięcznym oblężeniu siły Mahdiego weszły do Chartumu u zbiegu Nilu Błękitnego i Białego; namiestnik miasta Gordon został zabity, a wysłana na pomoc kolumna brytyjska spóźniła się o dwa dni. Od tej daty cały Sudan, w tym Sennar, Dongola i Kordofan, pozostawał przez czternaście lat pod zarządem Państwa Mahdiego. Region miał wejść pod wspólny zarząd angielsko-egipski dopiero w 1899, z całkowicie zerwaną więzią osmańską.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Włoska okupacja Massawy — utrata zachodniego wybrzeża Morza Czerwonego", "c333b95b"], "d": ["Port Massawa, ośrodek ejaletu Habesz, został zajęty przez Włochy korzystające z zamętu, w który pogrążyło Sudan powstanie mahdystów; stał się jądrem włoskiej Erytrei. Suakin na północy i archipelag Dahlak na morzu zostały utracone w tym samym procesie. W ten sposób panowanie osmańskie nad zachodnim wybrzeżem Morza Czerwonego trwające od czasów Selima Strasznego się skończyło, a morze stało się wodą obcą z obu brzegów.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Włoska okupacja Rodos", "e08662c5"], "d": ["Włochy, chcące w wojnie o Trypolitanię posadzić państwo osmańskie przy stole, przeniosły wojnę na Morze Śródziemne i wysadziły żołnierzy na Rodos. Wyspa została przejęta w ciągu kilku dni. Rodos, zdobyte w 1522 przez Sulejmana po długim oblężeniu i trzymane przez trzysta dziewięćdziesiąt lat, przestało w ten sposób być największą wyspową bazą imperium na wschodzie Morza Śródziemnego; choć w traktacie z Ouchy uznano to za okupację tymczasową, nie dało się go już odzyskać.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Włoska okupacja Dodekanezu", "200aacf2"], "d": ["W ciągu tygodnia po zajęciu Rodos flota włoska zajęła także okoliczne wyspy; archipelag ten miał później otrzymać nazwę „Dodekanez”. Większość wysp leżała kilka mil od wybrzeża Anatolii i kontrolowała południowo-wschodnie przejście Morza Egejskiego. Okupację w traktacie z Ouchy uznano za tymczasową w zamian za zrzeczenie się Trypolitanii, lecz Włochy nigdy nie opuściły wysp; miały zostać przekazane Grecji w 1947.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Okupacja Kos", "ab246c62"], "d": ["Kos, ostatnie ogniwo akcji dodekanezyjskiej, było urodzajną i zaludnioną wyspą tuż naprzeciw półwyspu Bodrum. Wraz z okupacją wszystkie wyspy w południowo-wschodnim narożniku Morza Egejskiego znalazły się pod kontrolą włoską, a południowo-zachodnie wybrzeże Anatolii zostało na całej długości otoczone obcym łańcuchem wysp.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Ogłoszenie niepodległości Ikarii", "c4452033"], "d": ["Na małej wyspie Ikaria między Samos a Chios ludność w atmosferze niepewności wywołanej włoskimi okupacjami zbuntowała się, wyparła z wyspy żandarmerię osmańską i ogłosiła „wolne państwo” trwające pięć miesięcy, z własną flagą, znaczkiem i zgromadzeniem. W listopadzie 1912 wyspa została przyłączona do Grecji. Mimo swej małości to wydarzenie jest jawnym wskaźnikiem tego, jak rozpadał się zarząd centralny na Morzu Egejskim.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Wyjście Samos spod zarządu osmańskiego", "3a862f2b"], "d": ["Samos było od 1832 autonomicznym emiratem płacącym Osmanom podatek i zarządzanym przez beja mianowanego przez Stambuł. W próżni stworzonej przez wojnę o Trypolitanię ruch unionistyczny na wyspie przejął zarząd i autonomiczny ład emiratu faktycznie się skończył; wyspa ogłosiła w tym samym roku przyłączenie do Grecji. Ta wyspa, oddalona o dwa kilometry od wybrzeża Anatolii, była jedną z pierwszych ziem utraconych na Morzu Egejskim.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Upadek Janiny — utrata Epiru i Pargi", "d42fce18"], "d": ["Janina, oblegana przez pięć miesięcy w wojnie bałkańskiej, poddała się po upadku pozycji Bizani; wraz z miastem cały Epir przeszedł do Grecji. Parga, podległa sandżakowi Janiny, została utracona w tym samym czasie i dziewięćdziesięcioczteroletni zarząd osmański się skończył. Utrata Janiny oznaczała zamknięcie ostatniego okna imperium otwierającego się na Adriatyk.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Upadek Edirne w ręce Bułgarów", "459d2e56"], "d": ["Po pięcioipółmiesięcznym oblężeniu Edirne, któremu skończyła się amunicja i żywność, się poddało; Şükrü Pasza został wzięty do niewoli. Upadek miasta osmańskiego od 1361 i będącego przez dziewięćdziesiąt dwa lata stolicą uznano za najcięższy cios wojny bałkańskiej. Edirne miało zostać odzyskane po czterech miesiącach, w II wojnie bałkańskiej, dzięki załamaniu się Bułgarii na innych frontach.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Utrata Yanbu na rzecz sił szarifa Husajna", "e291c816"], "d": ["Powstanie rozpoczęte przez szarifa Husajna w czerwcu rozszerzyło się na wybrzeże Morza Czerwonego; Yanbu, port Medyny, przeszło w ręce powstańców dzięki wsparciu floty angielskiej. Port stał się główną bramą napływu broni i pieniędzy z zewnątrz do powstania. W ten sposób siły Fahreddina Paszy w Medynie zostały odcięte od morza, a miasto pozostało samotnie na końcu kolei hidżaskiej.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["III bitwa pod Gazą — utrata Gazy i Han Yûnus", "c142a069"], "d": ["Po dwóch nieudanych próbach Allenby w trzecim natarciu przełamał front, obchodząc Beerszebę, a linia Gazy utrzymywana przez sześć miesięcy się załamała. Gaza i leżący na południe od niej Han Yûnus zostały opuszczone tego samego dnia. To przełamanie było początkiem rozpadu frontu palestyńskiego; Jerozolima miała paść po pięciu tygodniach.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Okupacja Gümülcine — utrata Tracji Zachodniej", "904d813c"], "d": ["Tracja Zachodnia, która po Mudros weszła najpierw pod kontrolę oddziałów Ententy, została postanowieniem konferencji w San Remo pozostawiona Grecji, a armia grecka wkroczyła do Gümülcine. Region odzyskany od Bułgarii w 1913 był ostatnią ziemią, jaką imperium utraciło w Rumelii. Status ludności tureckiej w regionie miał zostać uregulowany po trzech latach w Lozannie reżimem mniejszościowym. Wraz z tą okupacją kazy Gümülcine, İskeçe, Dedeağaç i Sofulu w Tracji Zachodniej przeszły do Grecji.", "ef0aeba3"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["Rozpad państwa Ilchanów: śmierć Abû Sa'îda Bahadura Chana", "0f187469"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Ilchanach śmierć Abû Sa'îda bez pozostawienia następcy doprowadziła do rozpadu państwa Ilchanów, panującego w Iranie od stulecia; emirowie, wykorzystując walki o tron, utworzyli lokalne dynastie, takie jak Dżalajirydzi, Karakoyunlu, Muzaffarydzi, Sarbadarzy Chorasanu i Eretnaoğulları. Ten rozpad podzielił region na mozaikę bejlików trwającą stulecie; w końcu miał zostać na nowo zjednoczony wyprawami Timura.", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["Opanowanie przez Timura większej części Iranu", "1cee2b82"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Timurze, od początku lat 80. XIV wieku likwidując jedna po drugiej lokalne dynastie po Ilchanach, takie jak Sarbadarzy, Kertowie i Muzaffarydzi, Timur w „trzyletniej wyprawie” z lat 1386–1388 faktycznie opanował większą część Iranu; ostateczny koniec dynastii Muzaffarydów miał nastąpić w 1393. Region został w ten sposób po stuletnim rozdrobnieniu ponownie związany jednym centralnym autorytetem.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["Zwycięstwo nad Arasem: Kara Yûsuf pokonał timurydzkiego Abû Bakra Mirzę", "4b61a75a"], "d": ["Bej Karakoyunlu Kara Yûsuf, który po śmierci Timura w 1405 wrócił z wygnania, po zajęciu Avnik i odzyskaniu swoich ziem we Wschodniej Anatolii ruszył na Abû Bakra Mirzę, wnuka Timura, uchodzącego za pana Azerbejdżanu i dwóch Iraków, i pokonał go nad Arasem. To zwycięstwo nie dało Karakoyunlu Tabrizu: TDV `tebriz` pisze, że miasto w 1408 było w rękach Abû Bakra Mirzy; bitwą, która dała Azerbejdżan, jest Sardrud z 13 kwietnia 1408.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Zwycięstwo pod Sardrud: Tabriz i Azerbejdżan przeszły do Karakoyunlu", "1f0a429d"], "d": ["Kara Yûsuf pokonał timurydzkiego Abû Bakra Mirzę po raz drugi po Arasie, pod Sardrud w pobliżu Tabrizu; to zwycięstwo dało Karakoyunlu Azerbejdżan. Następnie Kara Yûsuf powierzył Bistamowi Bejowi zdobycie Irâk-ı Acem;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Epidemia dżumy w Stambule i przeniesienie pałacu do Edirne", "70c7a163"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Stambule szybkie i intensywne osiedlanie się w mieście okresowo przygotowywało grunt do rozprzestrzeniania się epidemii; podczas epidemii dżumy w 1466 pałac i dostojnicy państwa tymczasowo wycofali się do Edirne. Ludność miasta ponosiła w takich epidemiach poważne straty.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["Zakończenie przez Uzuna Hasana państwa Karakoyunlu", "ef68399e"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Uzunie Hasanie władca Akkoyunlu Uzun Hasan pokonał i zabił władcę Karakoyunlu Cihana Szacha w okolicach Bingöl–Sancak 12 rebîülâhir 872 / 10 listopada 1467; syn Cihana Szacha, Hasan Ali, został pokonany pod Merend we wrześniu 1468 i zabity pod Hamadanem w kwietniu–maju 1469, a państwo Karakoyunlu zostało ostatecznie zlikwidowane. Ziemie przeszły pod panowanie Akkoyunlu; państwo miało w ciągu następnej dekady rozszerzyć się aż do wnętrza Iranu.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Otwarcie medres Sahn-ı Semân do nauczania", "021f2a83"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Sahn-ı Semân te osiem medres założonych w ramach kompleksu Fatiha zostało pomyślanych jako najwyższa instytucja nauczania epoki i tworzyło szczyt osmańskiej hierarchii ilmiye. Urząd profesora i ukończenie tych medres uchodziły w następnych stuleciach za najbardziej prestiżowy szczebel w karierze kadiego i profesora.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Ukończenie Pałacu Topkapı (Saray-ı Cedîd)", "d2db6323"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Pałacu Topkapı źródła epoki rozchodzą się co do dat rozpoczęcia i ukończenia budowy; według daty 883 (1478) na inskrypcji Bâb-ı Hümâyun budowa, rozpoczęta z rozkazu Zdobywcy prawdopodobnie w 1465, była do tego roku w znacznej mierze ukończona, a pałac zajął miejsce ośrodka państwa w dawnym pałacu. W ten sposób sułtan przeniósł się do nowej rezydencji, która miała przez trzy stulecia być administracyjnym i ceremonialnym sercem państwa.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Wstąpienie Bayezida II na tron w Stambule", "9b686d04"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Bayezidzie II książę Bayezid, sandżakbej Amasyi, po otrzymaniu wieści o śmierci ojca szybko przybył do Stambułu i wstąpił na tron; wyprzedził ruszającego z Konyi brata Cema dzięki poparciu janczarów. Przy wstąpieniu na tron janczarom rozdano zwyczajowy podarek wstąpieniowy. Ta zmiana tronu zapaliła też lont walki między dwoma braćmi.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Ogłoszenie się sułtanem przez Cema w Bursie", "b355168a"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Cemie Sułtanie Cem, który przez Karaman dotarł do Bursy, zajął miasto, ogłosił się sułtanem i kazał odczytać chutbę. To krótkotrwałe panowanie zakończyło się, gdy siły wysłane przez starszego brata Bayezida II pokonały Cema pod Yenişehir. Wskutek klęski Cem musiał uciekać w stronę Egiptu.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Stracenie Gediga Ahmeda Paszy", "6d75a58c"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Gediku Ahmedzie Paszy, znany z wyprawy do Otranto i wielkiego wezyratu, został stracony w Edirne z rozkazu Bayezida II z powodu postawy w sprawie księcia Cema i obaw wywołanych jego wpływami. Śmierć jednego z najbardziej doświadczonych dowódców epoki Zdobywcy wywołała w pałacu szeroki oddźwięk.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Założenie pierwszej drukarni w Stambule", "04475930"], "d": ["Według hasła TDV İslâm Ansiklopedisi o drukarni żydowscy emigranci z Hiszpanii, bracia David i Samuel ibn Nahmias, założyli w Stambule pierwszą drukarnię drukującą czcionkami hebrajskimi. Odnotowano ją jako pierwszą próbę drukarską działającą w ziemiach osmańskich; druk tureckimi czcionkami arabskimi miał stać się możliwy znacznie później, w XVIII wieku.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["Zajęcie Tabrizu przez szacha İsmaila: założenie państwa Safawidów", "014d81e6"], "d": ["Według haseł TDV İslâm Ansiklopedisi o Safawidach i Akkoyunlu młody szejch tekke w Ardabilu İsmail, z armią zebraną z kızılbaszów-murydów w Anatolii, zadał w okolicach Nachiczewanu ciężką klęskę sułtanowi Akkoyunlu Elvendowi; Elvend uciekł do Diyarbekir, a İsmail wkroczył do Tabrizu, zasiadł na tronie i ogłosił szyizm dwunastu imamów oficjalnym wyznaniem. W ten sposób zamknęły się zarówno panowanie Akkoyunlu, jak i okres bejlików po Ilchanach w regionie; powstało państwo Safawidów, które miało trwać trzy stulecia.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Trzęsienie ziemi „Małe Końca Świata” w Stambule", "53e3b1d6"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Stambule silne trzęsienie ziemi, które dotknęło miasto, wspominano wśród ludu jako „Małe Końca Świata”; w murach, meczetach i wielu budynkach powstały ciężkie szkody, doszło do licznych strat w ludziach. Z rozkazu Bayezida II w mieście rozpoczęto szeroką mobilizację naprawczą i budowlaną.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Początek powstania Şahkuluego", "3d9a4a90"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Şahkulu Babie Tekeli, Şahkulu, żywiony propagandą safawidzką, zebrał wokół siebie szeroką masę turkmeńską w regionie Teke i rozpoczął wielkie powstanie o charakterze religijno-społecznym. Powstanie, jako jeden z najpoważniejszych kryzysów bezpieczeństwa wewnętrznego epoki, głęboko wstrząsnęło centralnym autorytetem państwa.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Śmierć Bayezida II w drodze do Dimetoki", "c46e98c9"], "d": ["Dawny sułtan, który po abdykacji opuścił Stambuł, by udać się do rodzinnego miasta Dimetoka, posuwając się w lektyce pokonującej zaledwie 5–6 km dziennie, zasłabł we wsi Abalar koło Çorlu i zmarł 25 rebîülevvel 918 (10 czerwca 1512). Hasło TDV İslâm Ansiklopedisi uznaje przyczynę śmierci za bardzo wątpliwą; według niektórych źródeł miejscowych i zagranicznych rozważa się możliwość otrucia. Po trzydziestojednoletnim panowaniu zmarł w ten sposób ósmy sułtan z rodu Osmana Gazi.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Stracenie księcia Ahmeda z rozkazu Selima Strasznego", "65abb2f2"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Selimie I książę Ahmed, ulubieniec ojca Bayezida II i główny rywal do tronu, w walce podjętej po wstąpieniu brata Selima na tron został rozbity na równinie Yenişehir i schwytany podczas ucieczki z pola bitwy, po czym zabity. Tym wydarzeniem Selim w znacznej mierze zakończył rywalizację o tron między braćmi i bratankami.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["Mianowanie İbrahima Paszy wielkim wezyrem", "9c94c1e3"], "d": ["Według hasła TDV İslâm Ansiklopedisi o İbrâhîmie Paszy Makbulu İbrahim Pasza, awansowany z odabaszy do beylerbeja Rumelii i tego samego dnia do wielkiego wezyratu, został wielkim wezyrem 13 şaʿbana 929 (27 czerwca 1523). Było to mianowanie nie mające precedensu, polegające na przejściu ze służby pałacowej bezpośrednio do wielkiego wezyratu, i wskazywało na niezwykłą bliskość İbrahima Paszy wobec Sulejmana.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Mianowanie Barbarossy Hayreddina Paszy kapudanem paszą", "a0ff6bab"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Barbarossie Hayreddinie Paszy Hayreddin Pasza, znany z sukcesów w Algierze, został 6 kwietnia 1534 wezwany do Stambułu i mianowany kapudanem paszą oraz beylerbejem Cezâyir-i Bahr-i Sefîd. To mianowanie uchodzi za początek przebudowy floty osmańskiej i instytucjonalizacji potęgi morskiej na Morzu Śródziemnym.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rüstem Pasza po raz pierwszy wielkim wezyrem", "ddfcc014"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Rüstemie Paszy, po odwołaniu Hadıma Süleymana Paszy wskutek sporu z jednym z wezyrów, Rüstem Pasza został mianowany wielkim wezyrem 17 ramadanu 951 (2 grudnia 1544). Rüstem Pasza, którego bliskość pałacu wzrosła dzięki małżeństwu z Mihrimah Sułtan, stał się dzięki temu urzędowi jednym z najbardziej wpływowych mężów stanu epoki Sulejmana.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebüssuûd Efendi szejhülislamem", "11ed04f8"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Ebüssuûdzie Efendim Ebüssuûd Efendi, który przez osiem lat był kazaskerem Rumelii, został mianowany szejhülislamem w şaʿbanie 952 (październik 1545) i pozostał na tym urzędzie dwadzieścia osiem lat i jedenaście miesięcy. Ebüssuûd Efendi, znany z fatw dostosowujących kanunname Sulejmana do prawa szariatu, odegrał rozstrzygającą rolę w kształtowaniu instytucji prawnych i edukacyjnych swej epoki.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Śmierć Barbarossy Hayreddina Paszy", "3378a0bf"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Barbarossie Hayreddinie Paszy zmarł w Stambule 6 cemâziyelevvel 953 (5 lipca 1546) po krótkiej chorobie. Śmierć Barbarossy, pochowanego w mauzoleum przylegającym do medresy, którą kazał zbudować w Beşiktaş, została uznana za zamknięcie okresu przewagi na Morzu Śródziemnym, którą zbudowała flota osmańska.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Rozpoczęcie budowy meczetu i kompleksu Süleymaniye", "101ec36f"], "d": ["Według hasła TDV İslâm Ansiklopedisi o meczecie i kompleksie Süleymaniye kompleks, którego fundamenty położono w 1550 pod kierunkiem naczelnego architekta Sinana, został zaprojektowany jako wielki kompleks społeczny złożony z meczetu oraz medres, szpitala, imaretu i biblioteki. Budowa była jednym z największych programów budowlanych symbolizujących potęgę panowania Sulejmana i rozwój Stambułu.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["Początek nowej fali dżumy w Stambule i okolicach", "547d6bf6"], "d": ["Według hasła TDV İslâm Ansiklopedisi o dżumie (tâun) jedna z epidemii XVI wieku dotykających świat islamu miała miejsce w latach 1552–1566 i była szczególnie dotkliwa w Stambule, Anatolii, Rumelii, Egipcie i Afryce Północnej. Rozszerzające się szlaki handlowe i rosnąca ruchliwość ludności zaliczane są do czynników ułatwiających rozprzestrzenianie się epidemii w najpotężniejszym okresie imperium.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Mianowanie Kary Ahmeda Paszy wielkim wezyrem", "a7d7748e"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Karze Ahmedzie Paszy Kara Ahmed Pasza, pełniący obowiązki drugiego wezyra, został awansowany do wielkiego wezyratu 27 şewwala 960 (5 października 1553) po nagłym odwołaniu urzędującego wielkiego wezyra. Ta zmiana wskazuje na okres zbiegający się w czasie ze straceniem księcia Mustafy, w którym równowagi sił wewnątrz pałacu szybko zmieniały właściciela.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Stracenie kapudana paszy Pîrî Reisa", "3b2ad7a0"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Pîrî Reisie, gdy do Egiptu dotarły oskarżenia, że przy zniesieniu oblężenia Ormuzu złupił za łapówkę mienie muzułmanów i opuścił armię na polu bitwy, słynny żeglarz i kartograf został stracony w Kairze pod koniec roku 960 (koniec 1553). Śmierć Pîrî Reisa, którego majątek skonfiskowano, uznawana jest za skutek rywalizacji między paszami w polityce morskiej w Basrze i na Oceanie Indyjskim.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Stracenie Kary Ahmeda Paszy, Rüstem Pasza ponownie wielkim wezyrem", "9a85076a"], "d": ["Według haseł TDV İslâm Ansiklopedisi o Rüstemie Paszy i Karze Ahmedzie Paszy, na miejsce Kary Ahmeda Paszy, nagle straconego 13 zilkade 962 (29 września 1555) w czasie zebrania diwanu, Rüstem Pasza został tego samego dnia po raz drugi mianowany wielkim wezyrem przy poparciu sułtanek Hürrem i Mihrimah. Kulisy wydarzenia pozostawiono w źródłach niejasne; oceniono je jako skutek intryg wewnątrz pałacu.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Śmierć Hürrem Sułtan", "1ae998b5"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Hürrem Sułtan Hürrem Sułtan, haseki sułtanka Sulejmana, mająca przez lata wielki wpływ wewnątrz pałacu, zmarła w Stambule 26 cemâziyelâhir 965 (15 kwietnia 1558) i została pochowana w mauzoleum w kompleksie meczetu Süleymaniye. Śmierć Hürrem Sułtan, która po śmierci wielkiej matki sułtańskiej Hafsy w 1534 umocniła swój autorytet nad haremem, usunęła też równoważący wpływ stojący na przeszkodzie rywalizacji o tron między jej synami Bayezidem i Selimem.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Awans Sokollu Mehmeda Paszy na wielkiego wezyra", "896391a2"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Sokollu Mehmedzie Paszy Sokollu Mehmed Pasza, który po śmierci Semiza Alego Paszy 30 zilkade 972 (29 czerwca 1565) awansował na wielkiego wezyra, został ostatnim wielkim wezyrem Sulejmana i pozostał na tym urzędzie także za Selima II i Murada III, stając się jednym z najdłużej urzędujących wielkich wezyrów w dziejach osmańskich.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Selim II dotarł do Stambułu i wstąpił na tron", "0289ef97"], "d": ["Po śmierci Sulejmana Prawodawcy pod Szigetvárem wieść o niej była przez tygodnie utrzymywana w tajemnicy przez Sokollu Mehmeda Paszę, by nie zakłócić porządku. Według TDV İslâm Ansiklopedisi Selânikî podaje dzień przybycia Selima do Stambułu jako 15 rebîülevvel 974 (30 września 1566), podczas gdy większość współczesnych historyków uznaje za prawidłowy 9 rebîülevvel (24 września). Śmierć Sulejmana została oficjalnie ogłoszona dopiero 24–25 października 1566 w Belgradzie.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["Flota odbudowana przez Kılıça Alego Paszę zwodowana", "d0fc9f48"], "d": ["Po ciężkiej klęsce pod Lepanto (7 października 1571) przez całą zimę budowano okręty w stoczniach. Według TDV İslâm Ansiklopedisi 1 safera 980 (13 czerwca 1572) nowa flota złożona z 250 galer i około 300 galer ochotniczych reisów została zwodowana w pokazie siły.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Zamach na Sokollu Mehmeda Paszę i jego zabicie", "6ffa8dec"], "d": ["Sokollu Mehmed Pasza, który przez czternaście lat był wielkim wezyrem za trzech sułtanów, został zasztyletowany 20 şaʿbana 987 (12 października 1579) przez derwisza, który zbliżył się do niego na popołudniowym diwanie w jego rezydencji, jakby chciał złożyć petycję. Według TDV İslâm Ansiklopedisi dyskutuje się, czy zamach mógł mieć związek z zemstą za straconego szejcha Hamzawijja Hamzę Bâlîego.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["Pierwsze ahidname handlowe z Anglią — nadanie Anglikom kapitulacji", "59c8e3ee"], "d": ["William Harborne, angielski przedstawiciel wysłany do Stambułu w październiku 1578, uzyskał od Murada III przy poparciu Sokollu Mehmeda Paszy i Hoca Sâdeddina Efendiego ahidname z 1580. Na mocy tego ahidname kupcy angielscy zyskali prawo korzystania w tym samym stopniu z przywilejów handlowych (kapitulacji) przyznanych wcześniej Francuzom i Wenecjanom. Między królową Elżbietą I a Muradem III wymieniono listy i nawiązano też oficjalne stosunki między obu państwami. Bezpośrednio po tych przywilejach w 1581 w Londynie założono Levant Company; Anglicy prowadzili swój handel w regionie za pośrednictwem tej spółki do 1825.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["Zburzenie Obserwatorium Stambulskiego na mocy hatt-ı hümâyun", "3bc0c78c"], "d": ["Pod wpływem fatwy, że obserwatoria przynoszą krajom nieszczęście, i opozycji w pałacu Obserwatorium Stambulskie zostało zburzone wraz ze wszystkimi przyrządami na mocy hatt-ı hümâyun z 4 zilhidżdże 987 (22 stycznia 1580). Według TDV İslâm Ansiklopedisi był to krótkotrwały koniec instytucji założonej przez Takıyyüddina ar-Râsıda.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Początek obrzezania księcia Mehmeda na Atmeydanı", "c2926d5d"], "d": ["Książę Mehmed, syn Murada III, został obrzezany w okazałych uroczystościach, które rozpoczęły się 6 cemâziyelevvel 990 (29 maja 1582) i trwały pięćdziesiąt sześć–pięćdziesiąt siedem dni. Według TDV İslâm Ansiklopedisi uroczystości zorganizowane na Atmeydanı były jednym z najwspanialszych pałacowych obchodów swojej epoki.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Śmierć wielkiej matki sułtańskiej Nurbânû", "77d0a577"], "d": ["Matka Murada III, Nurbânû Sułtan, zmarła 22 zilkade 991 (7 grudnia 1583). Według TDV İslâm Ansiklopedisi jako wielka matka sułtańska prowadziła korespondencję z pałacami Wenecji i Francji, a senat wenecki zgodził się w tym samym roku przesłać jej w uznaniu zasług dar o wartości 2000 złotych weneckich.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Wydarzenie Beylerbeyi wybuchło z powodu zdewaluowanego akçe", "db2f2e61"], "d": ["Gdy państwo dokonywało płatności, obniżając zawartość srebra w akçe, sipahi i janczarzy otoczyli pałac i wzniecili krwawe powstanie, które weszło do historii pod nazwą Wydarzenia Beylerbeyi. Według hasła TDV İslâm Ansiklopedisi o Abdülkadirze Şeyhî Efendim szejhülislam został po tym wydarzeniu odwołany.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Mehmed III wstąpił na tron, uduszono dziewiętnastu książąt", "2cd9a8c5"], "d": ["Mehmed III po śmierci ojca Murada III dotarł do Stambułu w piątek 16 cemâziyelevvel 1003 (27 stycznia 1595) i wstąpił na tron. Według TDV İslâm Ansiklopedisi tej samej nocy uduszono dziewiętnastu książąt, w tym czterech dorosłych (Mustafę, Bayezida, Osmana i Abdullaha); było to największe bratobójstwo w dziejach osmańskich.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Safiye Sułtan zyskała wpływy jako wielka matka sułtańska", "000bec21"], "d": ["Safiye Sułtan, żona Murada III i matka Mehmeda III, wraz z wstąpieniem syna na tron awansowała jako wielka matka sułtańska na pozycję decydującą w polityce pałacowej. Według TDV İslâm Ansiklopedisi w tym okresie wpływy haremu sięgnęły wymiaru bezpośredniej ingerencji w sprawy państwa.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Mehmed III wyruszył osobiście na wyprawę pod naciskiem janczarów", "d3c50656"], "d": ["Mimo sprzeciwu wielkiego wezyra Damada İbrahima Paszy, pod naciskiem janczarów Mehmed III wyruszył 20 czerwca 1596 ze Stambułu na wyprawę jako pierwszy po Sulejmanie sułtan, który stanął osobiście na czele armii. Według TDV İslâm Ansiklopedisi oznaczało to ożywienie dawnej tradycji gaza.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["Epidemia dżumy rozpoczęta w latach 70. XVI wieku nadal dotykała Stambuł", "eb4ca37a"], "d": ["Według hasła TDV İslâm Ansiklopedisi o dżumie epidemia rozpoczęta w latach 70. XVI wieku utrzymywała swój wpływ do początków XVII wieku i dotknęła przede wszystkim Stambuł, a także Anatolię, Bałkany, Egipt i Afrykę Północną. Okresy epidemii stanowiły chroniczne zagrożenie często przerywające życie pałacu i miasta.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Śmierć Karayazıcı Abdülhalima, osłabienie ruchu powstańczego", "876ca7a6"], "d": ["Karayazıcı Abdülhalim, który po ciężkiej klęsce poniesionej 12 sierpnia 1601 w Sepetli koło Elbistan wycofał się ranny, zmarł w roku 1010 (1602). Według TDV İslâm Ansiklopedisi wieść o jego śmierci dotarła do Stambułu w ramadanie 1010 (luty–marzec 1602); źródła odnotowują, że jest sporne, czy jego śmierć nastąpiła wskutek rany, czy z rąk jego własnych ludzi.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Faktyczny koniec tradycji bratobójstwa", "9046c607"], "d": ["Ahmed I przy wstąpieniu na tron, w odróżnieniu od poprzednich sułtanów, nie kazał zabić brata księcia Mustafy i darował mu życie; ta decyzja uchodzi za początek faktycznego przyjęcia w osmańskim systemie sukcesji zasady ekberiyet-erşediyet. Hasło TDV İslâm Ansiklopedisi o „Mustafie I” przekazuje, że po tej dacie Mustafa wiódł w pałacu życie w odosobnieniu. Praktyka ta faktycznie położyła kres morderstwom przy wstąpieniu na tron trwającym od wieków.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Położenie fundamentów meczetu Sułtanahmet", "1683262f"], "d": ["Z rozkazu Ahmeda I na Atmeydanı w uroczystości położono fundamenty meczetu, który miał zbudować architekt Sedefkâr Mehmed Aga. Według hasła TDV İslâm Ansiklopedisi o „Meczecie i kompleksie Sułtana Ahmeda” budowla stała się też przedmiotem krytyki epoki jako pierwszy wielki meczet sułtański zbudowany bezpośrednio ze skarbu, bez zwycięstwa zdobywczego. Kompleks zaprojektowano tak, by obejmował wraz z meczetem także medresę, imaret i mauzoleum.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Zabicie Młodego Osmana przez janczarów (Hâile-i Osmâniye)", "324f6582"], "d": ["Janczarzy i sipahi, którzy zbuntowali się po pogłoskach, że pod pretekstem pielgrzymki opuści Stambuł i zamierza rozwiązać korpus janczarów, zdetronizowali Osmana II i kazali go udusić w lochach Yedikule. Według hasła TDV İslâm Ansiklopedisi o „Osmanie II” było to w dziejach osmańskich pierwsze wydarzenie, w którym sułtan został jawnie zabity wskutek buntu wojskowego, i wywołało głębokie załamanie w stosunkach dynastii z wojskiem. Jego ostatnie godziny upłynęły następująco: gdy próba schronienia się w rezydencji agi janczarów Alego Agi nie dała skutku, sułtan został, według słów TDV, „w straszliwy sposób, z odkrytą głową i w rozstroju”, posadzony na koniu i wśród ciężkich zniewag zaprowadzony najpierw do Orta Cami, gdzie był Mustafa I, a po południu tego samego dnia do Yedikule; według niektórych historyków, by udowodnić jego śmierć, odcięto mu ucho i nos i pokazano je matce Mustafy I. Po tym wydarzeniu Mustafa I został po raz drugi wprowadzony na tron. Wydarzenie zwane „Hâile-i Osmâniye” (tragedia Osmana) trwale zburzyło równowagę pałac–odżak i zapoczątkowało spory o legitymację trwające przez stulecie.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Ponowne wprowadzenie Mustafy I na tron", "34a0b29a"], "d": ["Po zabiciu Młodego Osmana przez janczarów, ponieważ w dynastii nie było innego dorosłego mężczyzny, Mustafa I został po raz drugi wprowadzony na tron. Według hasła TDV İslâm Ansiklopedisi o „Mustafie I” także to drugie panowanie, podobnie jak poprzednie, upłynęło bez faktycznego prowadzenia spraw państwa, a zarząd państwa pozostał w rękach wezyrów i wielkiej matki sułtańskiej. Ten trwający czternaście miesięcy okres zakończył się w 1623 wstąpieniem na tron Murada IV.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["Pożar Cibali", "3e42fb08"], "d": ["Pożar, który wybuchł w Cibali i szybko rozprzestrzenił się pod wpływem wiatru, obrócił w popiół dużą część Stambułu; według hasła TDV İslâm Ansiklopedisi o „Stambule” źródła epoki przekazują, że spłonęły tysiące domów. Powiązanie pożaru z drewnianą zabudową i paleniem tytoniu stało się bezpośrednim powodem surowego zakazu tytoniu i kawiarni, który Murad IV ogłosił wkrótce potem. Katastrofa była tylko jednym z powtarzających się wielkich pożarów ówczesnego Stambułu.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Zakaz tytoniu i kawiarni Murada IV", "5dd71297"], "d": ["Po pożarze Cibali, z obawy przed pożarami i dla zapewnienia porządku, Murad IV zakazał palenia tytoniu i kawiarni; wobec nieprzestrzegających zakazu stosowano ciężkie kary, w tym karę śmierci. Według hasła TDV İslâm Ansiklopedisi o „Muradzie IV” sułtan prowadził tak surową politykę wewnętrznej dyscypliny, że osobiście, w przebraniu, chodził ulicami miasta, by kontrolować zakaz. Te surowe środki uważane są za część wysiłków Murada IV mających na celu odbudowę władzy centralnej.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Epidemia dżumy w Stambule", "f33f58c5"], "d": ["Za Murada IV Stambuł został wstrząśnięty ciężką epidemią dżumy, która dotknęła znaczną część ludności; handel w mieście i codzienne życie zostały przez miesiące zakłócone. Hasło TDV İslâm Ansiklopedisi o „Stambule” odnotowuje, że powtarzające się w XVII wieku epidemie poważnie wpłynęły na równowagę ludnościową miasta. W okresie epidemii pałac i elita na pewien czas przenosiły się do ogrodów i pawilonów poza miastem.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Lot na skrzydłach Hezarfena Ahmeda Çelebiego (przekaz)", "df474c04"], "d": ["Według przekazu podanego przez Evliyę Çelebiego Hezarfen Ahmed Çelebi, skoczywszy z Wieży Galata na skrzydłach, które sam zbudował, zdołał szybować aż do Üsküdar; choć jego historyczna pewność jest sporna, stał się symbolem technicznej wyobraźni. Sułtan, który początkowo go nagrodził, zesłał potem Hezarfena do Algieru wobec oddźwięku, jaki wywołało wydarzenie.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Zdobycie wpływów w pałacu przez Cinci Hocę Hüseyina Efendiego", "41d21572"], "d": ["Znachor Hüseyin Efendi, wezwany do pałacu, by leczyć dolegliwości psychiczne sułtana Ibrahima, szybko zyskał zaufanie sułtana i awansował aż do kazaskeratu Anatolii. Według hasła TDV İslâm Ansiklopedisi o „Hüseynie Efendim, Cinci Hoca” wykorzystywał te wpływy do gromadzenia majątku i ingerowania w wydarzenia polityczne epoki. Po śmierci Ibrahima został odsunięty od wszystkich urzędów i stracony w 1648.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Stracenie Kemankeşa Mustafy Paszy", "0ecc8030"], "d": ["Kemankeş Mustafa Pasza, który od czasów Murada IV był wielkim wezyrem i dzięki reformom finansowym uzyskał dla skarbu znaczną nadwyżkę, został uduszony i stracony po tym, jak rywale wewnątrz pałacu wpłynęli na Ibrahima i oskarżyli go o wzniecenie buntu janczarów. Według hasła TDV İslâm Ansiklopedisi o „Kemankeşu Mustafie Paszy” stracenie nastąpiło 21 zilkade 1053 / 31 stycznia 1644: Kemankeş Kara Mustafa Pasza został uduszony na Hocapaşa Çarşısı przez kata Karę Alego i pochowany w swym mauzoleum w Çarşıkapı. Jego śmierć jest wspominana jako uderzający przykład niestabilności urzędu wielkiego wezyra w epoce i zakończyła krótki okres surowych reform.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["Decyzja diwanu o wyprawie kreteńskiej i wyjście floty", "9076827e"], "d": ["W Divan-ı Hümayun postanowiono o rozpoczęciu wielkiej wyprawy przeciw należącej do Wenecji wyspie Krecie, a flota osmańska pod dowództwem kapudana paszy wyruszyła ze Stambułu w kierunku Krety. Według hasła TDV İslâm Ansiklopedisi o „Krecie” ta decyzja stanowiła polityczny początek długiego okresu oblężenia i wojny, który miał trwać około dwudziestu pięciu lat. Rozpoczęcie wyprawy, jako największe przedsięwzięcie polityki zagranicznej epoki Ibrahima, wywołało szerokie dyskusje wśród dostojników państwa.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Wstąpienie na tron Mehmeda IV w wieku siedmiu lat", "a197a3bc"], "d": ["Bezpośrednio po detronizacji Ibrahima na tron wprowadzono jego siedmioletniego syna Mehmeda, który został sułtanem pod imieniem Mehmeda IV. Według hasła TDV İslâm Ansiklopedisi o „Mehmedzie IV” wstąpienie na tron w tak młodym wieku zaostrzyło walkę o wpływy wewnątrz pałacu między jego babką Kösem Sułtan a matką Turhan Sułtan. Ta walka o władzę miała zakończyć się w 1651 zabiciem Kösem Sułtan.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Reforma zrównoważonego budżetu Tarhuncu Ahmeda Paszy", "376fc7f2"], "d": ["Wielki wezyr Tarhuncu Ahmed Pasza, by przezwyciężyć kryzys finansowy wywołany długimi latami wojny, zastosował surowy program oszczędnościowy obejmujący także wydatki pałacowe i przygotował pierwszy znany w dziejach osmańskich zrównoważony budżet (lâyiha Tarhuncu). Według hasła TDV İslâm Ansiklopedisi o „Tarhuncu Ahmedzie Paszy” ta reforma przyniosła skarbowi znaczną nadwyżkę, lecz wywołała szerokie niezadowolenie w otoczeniu pałacowym i wyższej biurokracji. To niezadowolenie miało po roku zakończyć się jego straceniem.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["Wydarzenie pod platanem (Çınar Vak'ası; Vak'a-i Vakvakiye)", "4c6ed90f"], "d": ["Według hasła TDV İslâm Ansiklopedisi o wydarzeniu pod platanem janczarzy i sipahi, którzy wrócili z wyprawy kreteńskiej bez wypłaty żołdu, zbuntowali się w Stambule i zażądali stracenia dostojników oskarżanych o korupcję. Propozycja wielkiego wezyra Zurnazena Mustafy Paszy dotycząca konfiskaty i zesłania nie została przyjęta; najpierw stracono trzech urzędników, a następnie blisko trzydziestu dostojników państwa, których ciała powieszono na platanach na placu Sułtanahmet. Dlatego wydarzenie zwane jest Çınar Vak'ası.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Mianowanie Köprülü Mehmeda Paszy wielkim wezyrem na warunkach", "3a6b7f8f"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Köprülü Mehmedzie Paszy Köprülü Mehmed Pasza, bliski osiemdziesiątki, przyjął pieczęć dopiero po tym, jak wymusił na wielkiej matce sułtańskiej Turhan Sułtan i Mehmedzie IV przyjęcie ciężkich warunków — niemieszania się do jego mianowań i niewiary w to, co mówi się przeciw niemu. Objął urząd 26 zilkade 1066 na miejsce Boynueğri Mehmeda Paszy i przystąpił do surowego przywracania dyscypliny państwa.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["Stłumienie ruchu Kadızâdelich przez Köprülü Mehmeda Paszę", "5ec3ce84"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Kadızâdelich, Köprülü Mehmed Pasza, zaraz po objęciu urzędu zajął się konfliktem religijnym między otoczeniem Kadızâde Mehmeda Efendiego a ludźmi tarikatów. Po zasięgnięciu opinii ulemów wydał ferman o straceniu przywódców ruchu Üstüvânîego Mehmeda Efendiego, Türka Ahmeda i Divâne Mustafy, lecz karę zamieniono na zesłanie i trzech wysłano na Cypr; w ten sposób druga faza ruchu się skończyła.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Wielki pożar w Stambule: spalenie Ağakapısı", "b9253b66"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Ağakapısı w wielkim pożarze, który wybuchł w lipcu 1660 za Mehmeda IV, całkowicie spłonęła oficjalna kwatera agi janczarów, Ağakapısı, a następnie została odbudowana. Ten pożar był jednym z wielkich pożarów miejskich, które wielokrotnie nawiedzały ówczesny Stambuł.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Mianowanie Köprülüzâde Fâzıla Ahmeda Paszy wielkim wezyrem", "c1999b5c"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Köprülüzâde Fâzılu Ahmedzie Paszy po śmierci ojca Köprülü Mehmeda Paszy został 8 rebîülevvel 1072 (1 listopada 1661) mianowany wielkim wezyrem. Fâzıl Ahmed Pasza, w odróżnieniu od ojca znany jako łagodny, pobożny i opiekun uczonych i artystów, w czasie ponad piętnastoletniego wezyratu kazał założyć biblioteki i instytucje dobroczynne w Stambule i na zdobytych ziemiach.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Mianowanie Vânîego Mehmeda Efendiego kaznodzieją Yeni Cami i nauczycielem sułtana", "7ea6aaae"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Mehmedzie Efendim, Vânî, Vânî Mehmed Efendi, wezwany do Stambułu po objęciu wezyratu przez Köprülüzâde Fâzıla Ahmeda Paszę i przedstawiony Mehmedowi IV, szybko zyskał żywe zainteresowanie sułtana. W 1665 został mianowany kaznodzieją Yeni Cami i nauczycielem sułtana i stał się jednym z najbardziej wpływowych duchownych pałacu.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Mianowanie Merzifonlu Kary Mustafy Paszy wielkim wezyrem", "3d1e836c"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Merzifonlu Karze Mustafie Paszy po śmierci Fâzıla Ahmeda Paszy został 28 şaʿbana 1087 (5 listopada 1676) mianowany wielkim wezyrem. Merzifonlu, zięć i wychowanek rodu Köprülü, o długim doświadczeniu w zarządzaniu państwem, stał się jednym z najpotężniejszych i najbardziej wpływowych wielkich wezyrów Mehmeda IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Śmierć Vânîego Mehmeda Efendiego na zesłaniu", "cda714aa"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Mehmedzie Efendim, Vânî, Vânî Mehmed Efendi, uchodzący za jednego z głównych, którzy przekonali sułtana do wyprawy wiedeńskiej, po klęsce tej wyprawy został pod naciskiem opinii publicznej wypchnięty z łask i zesłany do miasteczka Kestel koło Bursy. Zmarł tu 14 zilkade 1096 (12 października 1685) i został pochowany przy wejściu do meczetu, który sam zbudował.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Mianowanie Köprülüzâde Fâzıla Mustafy Paszy wielkim wezyrem i jego reformy finansowe", "b048570e"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Köprülüzâde Fâzılu Mustafie Paszy Fâzıl Mustafa Pasza, mianowany wielkim wezyrem 11 muharrema 1101 (25 października 1689), uregulował na nowo sposób ściągania dżizji według zasad szariatu, zwalczał inflację mangırów i wzmocnił skarb, przekierowując środki z instytucji pałacowych. Ponadto wzmocnił zarząd prowincjonalny wiarygodnymi urzędnikami i kazał utworzyć lokalne rady podobne do diwanu centralnego.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["Wejście w życie systemu mâlikâne", "316b8426"], "d": ["Według hasła TDV İslâm Ansiklopedisi o mâlikâne w ostatniej ćwierci XVII wieku wzrost kosztów wojny i spadek dochodów wskutek utraty ziem wprowadziły skarb w ciężki kryzys finansowy. W systemie mâlikâne, który wszedł w życie w 1106 (1695), mültezimom przyznano dożywotnie prawo do stałego podatku, wprowadzając zachętę do ochrony produkcji zamiast krótkoterminowego wyzysku.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["Wstąpienie na tron Mustafy II", "b53656c7"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Mustafie II, Mustafa II, który wstąpił na tron w wieku trzydziestu jeden lat, ogłosił swój sułtanat bez czekania na zgodę wielkiego wezyra i szejhülislama; ceremonia przepasania mieczem odbyła się kilka dni później w Eski Cami. Sułtan, który wstąpił na tron w okresie trwających wojen wielofrontowych po klęsce pod Wiedniem, został ostatnim sułtanem osmańskim, który osobiście wyruszał na wyprawy.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Drugie mianowanie Feyzullaha Efendiego szejhülislamem", "1cf14cff"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Feyzullahu Efendim, Seyyid, Feyzullah Efendi został po wstąpieniu Mustafy II na tron po raz drugi mianowany szejhülislamem 11 şewwala 1106 (25 maja 1695). Jego wpływy na sułtana stopniowo rosły w trwającym ponad osiem lat okresie na tym urzędzie.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Obsadzenie przez Feyzullaha Efendiego synów na wyższych urzędach i narastająca reakcja", "a6398280"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Feyzullahu Efendim, Seyyid, szejhülislam otrzymał od Mustafy II niemający precedensu ferman o tym, że jego syn Fethullah Efendi zostanie po nim szejhülislamem, i umieścił swoich krewnych w młodym wieku na wysokich urzędach. Te praktyki wywołały szerokie niezadowolenie wśród klasy ilmiye, wojska i ludności Stambułu; połączone z pogłoskami o przeniesieniu stolicy do Edirne przygotowały grunt pod Wydarzenie Edyrneńskie 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["Początek Wydarzenia Edyrneńskiego", "5a106458"], "d": ["Według hasła TDV o „Wydarzeniu Edyrneńskim” ruch rozpoczęty buntem żołnierzy, którzy nie dostali żołdu, w krótkim czasie przekształcił się w szerokie powstanie, w którym wzięli udział janczarzy, uczniowie medres, rzemieślnicy i lud. Głównym celem powstania był szejhülislam Feyzullah Efendi, o którym twierdzono, że nadmiernie ingeruje w sprawy państwa. Tłum liczący około 60 000 osób pomaszerował ze Stambułu do Edirne.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Wezyrat Nevşehirli Damada İbrahima Paszy", "8d627a6f"], "d": ["Według hasła TDV o „Damadzie İbrâhimie Paszy, Nevşehirli” został on mianowany na urząd wielkiego wezyra 8 cemâziyelâhir 1130 (9 maja 1718) w czasie trwających rokowań pokojowych z Austrią i zaraz po mianowaniu zwrócił się ku rokowaniom, które miały zakończyć wojnę; po dwóch miesiącach podpisano traktat z Passarowitz (21 lipca 1718). W ujęciu TDV „chciał zajmować się sprawami społecznymi i finansowymi, tęsknił za okresem pokoju, który pozwoliłby zapomnieć o wojnach kończących się od lat porażką”. Przeprowadził reformy w finansach, obniżył żołd żołnierzy i uzyskał w skarbie państwa znaczną nadwyżkę. Jego trwający dwanaście lat wezyrat stworzył polityczne ramy epoki noszącej jego imię (Epoki Tulipanów).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Założenie Odżaku Tulumbacı", "f58b0d97"], "d": ["Według hasła TDV o „Tulumbacı”, po sukcesie Gerçeka Dâvuda, który wrócił z wyprawy morejskiej 1715, w pożarach Stambułu przy użyciu sikawek (tulumba), wielki wezyr Nevşehirli Damad İbrahim Pasza polecił mu utworzenie oficjalnego odżaku straży pożarnej. Odżak założony w Koszarach Acemi Oğlanları z sześcioma oficerami i pięćdziesięcioma żołnierzami liczył w 1724 150, a w 1755 461 osób. Dâvud pozostał na czele odżaku do śmierci w 1733.", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["Przyjęcie Mehmeda Efendiego przez Ludwika XV", "0ff5b174"], "d": ["Według hasła TDV o „Yirmisekiz Çelebi Mehmedzie Efendim” poseł został oficjalnie przyjęty w Pałacu Tuileries przez króla Francji Ludwika XV i złożył dary i list Ahmeda III. Podczas wizyty zwiedził pałace w Wersalu, Trianon i Marly, szpitale, obserwatoria i wytwórnie; to, co zobaczył, zapisał w rysunkach.", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["Powrót Mehmeda Efendiego do Stambułu", "a09a8bba"], "d": ["Według hasła TDV o „Yirmisekiz Çelebi Mehmedzie Efendim” obserwacje posła, który wrócił z rocznego poselstwa w Paryżu, wpłynęły na architektoniczny gust Epoki Tulipanów. Późniejsza współpraca jego syna z İbrahimem Müteferrika przygotowała grunt pod założenie pierwszej tureckiej drukarni, najtrwalszego dziedzictwa poselstwa.", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Budowa pałacu Sâdâbâd", "aec9c65e"], "d": ["Według hasła TDV o „Sâdâbâd” nad brzegiem potoku Kağıthane zbudowano rozległy kompleks rozrywkowo-wypoczynkowy złożony z pałacu inspirowanego francuską architekturą pałacową, kanałów, fontann i pawilonów. Sâdâbâd, który stał się ulubionym miejscem rozrywki epoki, został uwieczniony w wierszach poety Nedîma. Kompleks został w znacznej mierze zniszczony podczas powstania Patrony Halila w 1730.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["Zajęcie Derbentu przez siły rosyjskie: wyprawa kaspijska Piotra I", "c2b269f9"], "d": ["Gdy państwo Safawidów wskutek inwazji afgańskiej pogrążyło się w wewnętrznym zamęcie, car Rosji Piotr I wyruszył na wyprawę w celu zajęcia ziem irańskich nad Morzem Kaspijskim; nadmorskie miasto Derbent poddało się siłom rosyjskim bez godnego uwagi oporu. Według hasła TDV İslâm Ansiklopedisi o Derbencie to zajęcie było początkiem trwającego trzynaście lat tymczasowego panowania rosyjskiego; państwo osmańskie, wykorzystując ten sam zamęt, zwróciło się ku zachodniej części Kaukazu. Armia z Astrachania przeprawiła się morzem do zatoki Agrachań, stamtąd lądem wzdłuż wybrzeża przez Tarku; szamchał Tarku, ugościwszy Piotra, wszedł w zależność od Rosji.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["Zniesienie szamchalatu Tarku: zarząd bezpośrednio rosyjski", "b0f029c6"], "d": ["Szamchał Tarku Adil-Girej, który w 1722 ugościł Piotra i wszedł w zależność od Rosji, zbuntował się w 1725; Jeropkin zburzył Tarku jesienią 1725, szamchał został aresztowany i zesłany w połowie maja 1726, a szamchalat zniesiono. Tarku i okolice pozostawały pod bezpośrednim zarządem rosyjskim do traktatu w Gandży z 1735.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["Zezwolenie İbrahimowi Müteferrika na założenie drukarni", "0659dd0a"], "d": ["Według hasła TDV o „İbrâhimie Müteferrika” na mocy fermanu Ahmeda III i fatwy szejhülislama Yenişehirli Abdullaha Efendiego zezwolono na założenie pierwszej tureckiej drukarni. Drukarnia rozpoczęła działalność w stambulskiej dzielnicy Yavuzselim. Müteferrika wydrukował do śmierci w 1747 siedemnaście dzieł w dwudziestu trzech tomach.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Ukończenie pierwszej drukowanej książki — Słownika Vankulu", "684700e8"], "d": ["Według hasła TDV o „İbrâhimie Müteferrika” pierwsze dzieło drukarni, turecki przekład Siḥâh al-Dżawharî (Słownik Vankulu), zostało ukończone na początku 1729. Była to pierwsza książka drukowana pismem arabskim w ziemiach osmańskich i uchodzi za początek tureckiej historii drukarstwa.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Stracenie Nevşehirli Damada İbrahima Paszy", "50c64341"], "d": ["Według hasła TDV o „Damadzie İbrâhimie Paszy, Nevşehirli” ciało wielkiego wezyra, zabitego w pałacu w czasie powstania Patrony Halila, wleczone po ulicach Stambułu, zostało porzucone w pobliżu Fontanny Ahmeda III na placu Sułtanahmet. Jego dwunastoletni wezyrat i Epoka Tulipanów zakończyły się w ten sposób krwawo.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["Abdykacja Ahmeda III, wstąpienie na tron Mahmuda I", "a43f5d40"], "d": ["Według hasła TDV o „Mahmudzie I” wobec nacisku powstańców Ahmed III zrezygnował z tronu, uzyskawszy gwarancje dla siebie i dzieci, i sam wprowadził na tron bratanka, księcia Mahmuda. Mahmud I, który zasiadł na tronie z radą stryja „weź sprawy państwa we własne ręce, nikomu nie ufaj”, przystąpił w pierwszej kolejności do złamania wpływów grupy powstańców, która wprowadziła go na tron.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Reforma odżaku artylerii przez Humbaracı Ahmeda Paszę", "ea3a7c64"], "d": ["Według hasła TDV o „Humbaracı” oficer pochodzenia francuskiego Ahmed Pasza, który przeszedł na islam, przystąpił za wielkiego wezyra Hekimoğlu Alego Paszy do reformy organizacji płatnych humbaracich na modłę europejską. Utworzył nową strukturę podległą bezpośrednio wielkiemu wezyrowi, liczącą 601 osób — 300 na żołdzie i 301 timarowych. Kazał wyprodukować według ówczesnej technologii 100 moździerzy i 50 000 kul.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Założenie Hendesehâne (pierwszego wzoru szkoły inżynierskiej)", "a77ed1f3"], "d": ["Według hasła TDV o „Mahmudzie I” Humbaracı Ahmed Pasza, zakładając w Üsküdar Hendesehâne zwane też Humbarahâne, dał uczniom wybranym spośród służby pałacowej i bostanci wojskowe wykształcenie oparte na matematyce i geometrii. Ta instytucja uchodzi za pierwszy wzór szkół inżynierskich, które miały rozwinąć się w późniejszym okresie.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["Traktat w Gandży: zwrot Derbentu i Baku Iranowi", "ff19d531"], "d": ["Rosja, szukająca sojuszu z Iranem przeciw zagrożeniu osmańskiemu, zwróciła na mocy traktatu w Gandży miasta nad Morzem Kaspijskim, trzymane od trzynastu lat, Iranowi pod dowództwem Nadir Chana (który nie przyjął jeszcze tytułu szacha). Według hasła TDV İslâm Ansiklopedisi o Derbencie to wycofanie było skutkiem niechęci Rosji do walki na południu jednocześnie na dwóch frontach (osmańskim i irańskim) i umocniło wojskowy prestiż Nadira, który otworzył mu drogę do wstąpienia na tron kilka lat później. Tarki (Tarku) pod zarządem rosyjskim również wróciło tym wycofaniem na stronę irańską (na mapie używa się dnia traktatu w Gandży). Salyan i Szabran pod zarządem rosyjskim wracają także tym wycofaniem na stronę irańską (dzień właściwy dla miejscowości nie występuje w źródle, na mapie używa się dnia traktatu w Gandży — przybliżenie z deklaracją).", "711f14d9"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["Wstąpienie Nadir Szacha na tron na stepie Mugan: faktyczny koniec dynastii Safawidów", "4f640979"], "d": ["Według hasła TDV İslâm Ansiklopedisi o Nadir Szachu kurułtaj liczący około dwudziestu tysięcy osób, zebrany na stepie Mugan, uporczywie domagał się, by stanął na czele Iranu; Nadir przyjął tę propozycję pod warunkiem porzucenia nadmiernie szyickiego rozumienia, które było przyczyną wojen między Safawidami a Osmanami, i przyjęcia umiarkowanego mazhabu dżafarytów, i 24 şewwala 1148 (8 marca 1736) wstąpił na tron z tytułem Nâdir Szach. Oznaczało to faktyczny koniec dwustuletniej dynastii Safawidów i założenie dynastii Afszarydów.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["Początek epidemii dżumy w Stambule", "9fa82b56"], "d": ["Według hasła TDV o „Tâun” epidemia dżumy, która w latach 1739–1743 działała w świecie islamu, dotknęła w tym czasie także Stambuł. Hasło odnotowuje, że epidemie w XVIII wieku przebiegały względnie łagodniej niż w poprzednich stuleciach. Wśród okresów epidemii wymienia się także lata 1713, 1719, 1728–1729 i 1759–1765.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["Pożar Hocapaşa", "321c7d0d"], "d": ["Według hasła TDV o „Meczecie Fatmy Sułtan” pożar Hocapaşa, który wybuchł w nocy, zniszczył Bâbıâli i okolice; przypuszcza się, że meczet Fatmy Sułtan w tej okolicy również ucierpiał w tym pożarze. Ta katastrofa, jeden z wielkich pożarów nawiedzających Stambuł za Osmana III, przyniosła ciężkie zniszczenia w centrum handlu i administracji miasta.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["Wezyrat Koca Ragıpa Mehmeda Paszy", "a1846910"], "d": ["Ragıp Pasza, znany jako poeta i dyplomata, został przez Osmana III mianowany na urząd wielkiego wezyra (po śmierci Osmana III w październiku 1757 pozostał na urzędzie, otrzymawszy od Mustafy III nową pieczęć). W czasie trwania wojen siedmioletnich prowadził zrównoważoną politykę zagraniczną, utrzymując państwo osmańskie poza konfliktami w Europie. W trwającym sześć lat wezyracie przywiązywał wagę także do działalności kulturalnej, jak zakładanie bibliotek.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["Śmierć Ragıpa Paszy", "6bc19323"], "d": ["Ragıp Pasza zmarł po sześcioletnim wezyracie. Wraz z jego śmiercią skończył się najdłużej trwający i zrównoważony wezyrat epoki Mustafy III.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["Wielkie trzęsienie ziemi w Stambule i zawalenie się meczetu Fatiha", "2475b4dc"], "d": ["Według hasła TDV o „Meczecie i kompleksie Fatiha” w wielkim trzęsieniu ziemi z 1766 główna kopuła meczetu całkowicie się zawaliła, a ściany uległy uszkodzeniom nienadającym się do naprawy. Odbudowa rozpoczęta w 1767 z rozkazu Mustafy III pod kierunkiem architektów Sarıma İbrahima Efendiego i İzzeta Mehmeda Beja została ukończona w 1771 według nowego projektu różniącego się od dawnego planu.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["Krótkotrwała próba szkoły artylerii pod kierunkiem barona de Tott", "4192260c"], "d": ["Według hasła TDV o „Mühendishâne-i Bahrî-i Hümâyun” niepowodzenia w wojnie osmańsko-rosyjskiej 1768 ukazały potrzebę technicznego kształcenia wojskowego; krótkotrwała szkoła artylerii otwarta przy udziale francuskiego oficera barona de Tott rozpoczęła działalność w październiku 1772, lecz okazała się nieskuteczna. Ta próba uchodzi za prekursora Mühendishâne-i Bahrî-i Hümâyun, które miało zostać założone w 1775.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Wstąpienie na tron Selima III", "00d046d9"], "d": ["Po śmierci Abdülhamida I na tron wstąpił jego bratanek Selim III. Według hasła TDV İslâm Ansiklopedisi o Selimie III nowy sułtan, który od czasów książęcych interesował się reformą armii europejskich, wkrótce po wstąpieniu na tron zaczął przygotowywać program gruntownej odnowy. Ten program miał w ciągu kilku lat zostać nazwany Nizâm-ı Cedîd.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Początek przygotowywania programu reform Nizâm-ı Cedîd", "eff78a68"], "d": ["Selim III kazał przygotować kompleksowy program odnowy na podstawie projektów żądanych od dostojników państwa i zagranicznych ekspertów. Według hasła TDV İslâm Ansiklopedisi o Nizâm-ı Cedîd program ten nie ograniczył się do utworzenia nowej armii; przekształcił się w szeroki ruch reformatorski obejmujący także finanse, zarząd prowincjonalny i dyplomację. Program miał w ciągu następnych piętnastu lat znaleźć zarówno zwolenników, jak i przeciwników.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["Założenie stałych poselstw w stolicach europejskich", "2e9dc8a1"], "d": ["Selim III po raz pierwszy w dziejach państwa osmańskiego wysłał do wielkich ośrodków europejskich stałych posłów mających pełnić służbę nieprzerwanie. Według hasła TDV İslâm Ansiklopedisi o posle (Elçi) ten krok nadał trwałą organizację osmańskiej dyplomacji, prowadzonej do tej pory jedynie tymczasowymi, jednorazowymi delegacjami. Głównym zadaniem nowych poselstw było regularne informowanie Stambułu o wydarzeniach politycznych i wojskowych w Europie.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["Utworzenie skarbu İrad-ı Cedîd", "ae5c8ce2"], "d": ["Dla pokrycia wydatków armii Nizâm-ı Cedîd i programu reform utworzono odrębny skarb. Według hasła TDV İslâm Ansiklopedisi o esham wśród dochodów nowego skarbu znajdowały się bezpośrednie prowadzenie niektórych mukataa przez państwo i objęcie kontrolą sprzedaży esham. To uregulowanie było próbą stworzenia nowego źródła poza tradycyjnym systemem finansowym.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Początek powstania Kabakçı Mustafy", "b98eee17"], "d": ["Niezadowolenie narastające wobec Nizâm-ı Cedîd wybuchło buntem żołnierzy yamak pod wodzą Kabakçı Mustafy. Według hasła TDV İslâm Ansiklopedisi o powstaniu Kabakçı powstańcy w krótkim czasie przejęli kontrolę w Stambule i zażądali głów dostojników państwa sprzyjających Nizâm-ı Cedîd. Powstanie zakończyło się w ciągu kilku dni detronizacją Selima III.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Detronizacja Selima III", "ff2c30ec"], "d": ["Pod naciskiem powstania Kabakçı Mustafy Selim III został zdetronizowany na mocy fatwy uzyskanej od szejhülislama. Według hasła TDV İslâm Ansiklopedisi o Selimie III ta decyzja była chwilą, w której trwający osiemnaście lat okres reform faktycznie się skończył; armię Nizâm-ı Cedîd również wkrótce rozwiązano. Selima zaczęto trzymać pod strażą w Pałacu Topkapı.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Wstąpienie na tron Mustafy IV", "8f1ac86c"], "d": ["Bezpośrednio po detronizacji Selima III sułtanem ogłoszono jego bratanka Mustafę IV. Według hasła TDV İslâm Ansiklopedisi o Mustafie IV nowy sułtan rozpoczął panowanie pod wpływem kręgów przeciwnych Nizâm-ı Cedîd, które poparły powstanie. Ten krótki okres był fazą niestabilności, w której władza centralna bardzo osłabła.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Wkroczenie Alemdara Mustafy Paszy z armią do Stambułu", "0cad3dea"], "d": ["Alemdar Mustafa Pasza, ajan Ruse, przybył z armią pod Stambuł w celu ponownego wprowadzenia na tron Selima III. Według hasła TDV İslâm Ansiklopedisi o Alemdarze Mustafie Paszy jego wejście do miasta powitał osobiście Mustafa IV; jednak w ciągu kilku dni równowaga sił wewnątrz pałacu miała całkowicie się zmienić. To wejście rozpoczęło łańcuch wydarzeń zakończonych zarówno śmiercią Selima, jak i nowym wstąpieniem na tron.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["Zabicie Selima III", "e452f5f6"], "d": ["W dniu, gdy Alemdar Mustafa Pasza zajął Bâbıâli, Selim III został zabity w pałacu z rozkazu Mustafy IV. Według hasła TDV İslâm Ansiklopedisi o Selimie III była to decyzja podjęta w celu zapobieżenia próbie ponownego wprowadzenia na tron zdetronizowanego sułtana. Śmierć Selima zakończyła się tego samego dnia wstąpieniem na tron Mahmuda.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["Wstąpienie na tron Mahmuda II", "661c1974"], "d": ["Po zabiciu Selima III Mahmud, który pozostał jedynym mężczyzną dynastii, wstąpił na tron przy poparciu Alemdara Mustafy Paszy. Według hasła TDV İslâm Ansiklopedisi o Mahmudzie II nowy sułtan spędził pierwsze miesiące panowania pod opieką Alemdara, który wprowadził go na tron, i w wysiłkach ponownego ustanowienia równowagi między ajanami a centrum. Ten okres był początkiem trwającego dwadzieścia lat procesu gruntownych reform.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["Utworzenie armii Sekbân-ı Cedîd", "6f9eb5e4"], "d": ["Alemdar Mustafa Pasza kazał utworzyć, na miejsce rozwiązanego Nizâm-ı Cedîd, nową armię wyposażoną na modłę europejską. Według hasła TDV İslâm Ansiklopedisi o Sekbân-ı Cedîd ta siła złożona z trzech pułków była w oczach janczarów postrzegana jako bezpośrednie zagrożenie i została zlikwidowana w buncie janczarów zaledwie po kilku miesiącach od utworzenia.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["Upadek Braiły — pierwszy wielki wyłom w linii Dunaju", "ee519321"], "d": ["W wojnie rosyjskiej rozpoczętej w 1806 twierdza Braiła na północnym brzegu Dunaju została oblężona i ostrzelana przez siły rosyjskie pod dowództwem hrabiego Kamieńskiego. W środku znajdowało się 4100 piechurów, 1100 jeźdźców i 260 dział; twierdza poddała się generałowi Essenowi z powodu braku żywności. Północny kraniec linii obrony Dunaju został w ten sposób otwarty.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["Poddanie Ruse — południowy brzeg Dunaju również utracony", "084062e8"], "d": ["Ruse opierało się długiemu i krwawemu oblężeniu armii rosyjskiej pod dowództwem hrabiego Kamieńskiego; poddało się pod warunkiem, że garnizon i ludność cywilna opuszczą miasto bezpiecznie. Upadek najpotężniejszego miasta-twierdzy na południowym brzegu Dunaju obrócił przebieg wojny na korzyść Rosji.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["Utworzenie Odżaku Eşkinci", "67c56759"], "d": ["Mahmud II kazał utworzyć nowy oddział, który miał być szkolony na modłę europejską, z żołnierzy wybranych z korpusu janczarów. Według hasła TDV İslâm Ansiklopedisi o Odżaku Eşkinci oddział rozpoczął szkolenie 12 czerwca 1826, lecz janczarzy uznali to za koniec swego odżaku. Powstanie, które wybuchło po trzech dniach, zakończyło też krótkie życie Odżaku Eşkinci.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["Utworzenie Asâkir-i Mansûre-i Muhammediyye", "14b84a7e"], "d": ["Bezpośrednio po zniesieniu korpusu janczarów Mahmud II kazał utworzyć na jego miejsce regularną armię wyszkoloną na modłę europejską. Według hasła TDV İslâm Ansiklopedisi o Asâkir-i Mansûre-i Muhammediyye ta armia, w odróżnieniu od wcześniejszych prób, stała się trwałą instytucją dzięki porządkowi stopni, programowi szkolenia i systemowi żołdu. Armia miała w następnych latach przekształcić się w armię Nizâmiye epoki Tanzimatu.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["Zamknięcie tarikatu bektaszytów", "f7d9a367"], "d": ["Równocześnie ze zniesieniem korpusu janczarów zakazano także tarikatu bektaszytów, znanego z więzi religijnych z odżakiem. Według hasła TDV İslâm Ansiklopedisi o bektaszyzmie podczas gdy niektórzy szejchowie małych tekke zostali straceni, szejch dergâh Hacı Bektaş został zesłany do Amasyi, a tekke przekazano zarządowi nakszbandyjskiemu. Tarikat mimo tego ciężkiego ciosu kontynuował swoją organizację w ukryciu.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["Wydarzenie z wachlarzem — pretekst okupacji", "e949001e"], "d": ["W rokowaniach zaostrzonych z powodu niezapłaconego dawnego długu zbożowego Francji wobec Algieru Dej Hüseyin uderzył francuskiego konsula Devala trzymanym w ręku wachlarzem. Ten incydent, zrodzony ze sporu o należność, został po trzech latach oficjalnym pretekstem rozpoczętej okupacji.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["Francuska blokada wybrzeża Algieru — oblężenie trwające trzy lata", "d0ba97a5"], "d": ["Po wydarzeniu z wachlarzem Francja objęła wybrzeże algierskie blokadą. Blokada trwała trzy lata; morski handel i źródła dochodów odżaku wyschły, a jego zdolność oporu została nadwątlona, zanim jeszcze rozpoczęła się okupacja.", "79d27be2"]},
"OLAYLAR_EK7:1828-02-22:0":{"b": ["Traktat w Turkmenczaj: przejście Erywania i Talyszu do Rosji", "abffcfdb"], "d": ["Gdy wojna rosyjsko-irańska 1826–1828 zakończyła się ciężką klęską Iranu, na mocy traktatu podpisanego w Turkmenczaj chanaty Erywania i Nachiczewanu oraz region Talysz nad Morzem Kaspijskim (Lenkoran, Astara) oddano Rosji; nałożono też ciężkie odszkodowanie wojenne. Według hasła TDV İslâm Ansiklopedisi o Erywaniu ta strata jest chwilą, w której wytyczono granicę rosyjsko-irańską na Kaukazie w kształcie, który w znacznej mierze zachował się do dziś, i wywołała też migrację ludności ormiańskiej do Erywania. Na mocy tego traktatu chanat Erywania (Eczmiadzin, Iğdır, Norapat, Beri) i chanat Nachiczewanu (Culfa, Şerur) przeszły do Rosji.", "847d76d5"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["Drugi upadek Braiły — car Mikołaj pod twierdzą", "eb6a8741"], "d": ["Braiła, zwrócona Osmanom w 1812 i ponownie umocniona w latach 1817–1818, została oblężona w kwietniu, gdy w środku było 4000 obrońców i 278 dział. Komendant Ebûbekir Pasza stworzył nową linię obrony; car Mikołaj I przybył osobiście pod twierdzę pod koniec maja. Miasto zostało zajęte przez Rosjan, lecz miało zostać zwrócone na mocy traktatu adrianopolskiego i pozostawione księstwu Wołoszczyzny.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["Ogłoszenie fezu oficjalnym nakryciem głowy", "f55be4eb"], "d": ["Mahmud II, dokonując gruntownej zmiany w ubiorze urzędników i żołnierzy, ogłosił fez oficjalnym nakryciem głowy w miejsce turbanu. Według hasła TDV İslâm Ansiklopedisi o fezie ta decyzja została ogłoszona hatt-ı hümâyunem i wprowadzona w życie razem z reformami Asâkir-i Mansûre-i Muhammediyye w stylu zachodnim. Zmiana oznaczała też zakończenie tradycyjnej hierarchii ubioru.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["Oddanie Achalciche Rosji — utrata ośrodka ejaletu Çıldır", "e2e00b2a"], "d": ["Achalciche, pozostające od wojny çıldırskiej z 1578 pod zarządem osmańskim i będące ośrodkiem ejaletu Çıldır, zostało oddane Rosji na mocy traktatu adrianopolskiego podpisanego pod koniec wojny 1828–1829. Utrata miasta wywołała głęboki smutek wśród ludu i stała się tematem wielu elegii. Wraz z tym wydarzeniem Achałkałaki, Zazalo i Ts'q'altbila (region Achalciche–Achałkałaki) przeszły do Rosji.", "bab87a04"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["Lądowanie w Sîdî Ferruc — armia francuska na ziemi algierskiej", "33327553"], "d": ["Po trzyletniej blokadzie francuska armia desantowa pod dowództwem hrabiego de Bourmont wysadziła żołnierzy w zatoce Sîdî Ferruc na zachód od Algieru. Siły posuwające się w stronę miasta przełamały w ciągu trzech tygodni linię obrony; 4 lipca padła Twierdza Cesarska panująca nad miastem, a następnego dnia poddał się Dej Hüseyin.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["Zesłanie Deja Hüseyina — faktyczny koniec odżaku algierskiego", "e122403b"], "d": ["Zgodnie z warunkami poddania ostatni dej Algieru Hüseyin został wraz z rodziną i skarbem wysłany z miasta do Neapolu. Zarząd odżaku, który w 1519 związał się z Selimem Strasznym i przez trzysta lat był najpotężniejszą osmańską bazą morską na Morzu Śródziemnym, w ten sposób się skończył.", "bf7169cf"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["Wycofanie armii rosyjskiej z Wołoszczyzny i Mołdawii — koniec sześcioletniej okupacji", "efdb0275"], "d": ["W wojnie osmańsko-rosyjskiej 1828–1829 Rosjanie zajęli Wołoszczyznę i Mołdawię i po traktacie adrianopolskim nie wycofali się, aż do spłaty odszkodowania wojennego. Gdy w styczniu 1834 odszkodowanie obniżono do pięciu milionów, siły rosyjskie opuściły Memleketejn, a w obu księstwach mianowano nowych wojewodów. Zwierzchnictwo osmańskie wróciło na papierze, lecz Rosja zachowała wpływy zdobyte przez Reglement Organique.", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["Utworzenie organizacji Redif-i Asâkir-i Mansûre", "15947493"], "d": ["Organizacja Redif jako siła rezerwowa wspierająca Asâkir-i Mansûre-i Muhammediyye została utworzona regulaminem z 8 lipca 1834. Według hasła TDV İslâm Ansiklopedisi o Redif pod kierownictwem serasktera Koca Hüsreva Paszy w kazach prowincjonalnych tworzono bataliony po około tysiąc czterysta osób. Organizację zaprojektowano tak, by wspierała także lokalne bezpieczeństwo bez powoływania do stałej służby.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["Utworzenie Ministerstwa Spraw Zagranicznych", "750c6c7d"], "d": ["Mahmud II, znosząc urząd reisülküttâba prowadzący sprawy zagraniczne, utworzył w jego miejsce Ministerstwo Spraw Zagranicznych (Hariciye Nezareti). Według hasła TDV İslâm Ansiklopedisi o Hariciye Nezâreti pierwszym ministrem nowego ministerstwa został Mehmed Âkif Pasza, a organizacja rozpoczęła działalność w rezydencji posła w Wiedniu Rıfata Beja. To uregulowanie było początkiem prowadzenia osmańskiej polityki zagranicznej według zasady nowoczesnego ministerstwa.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["Utworzenie Meclis-i Vâlâ-yı Ahkâm-ı Adliyye", "69db056e"], "d": ["Mahmud II kazał utworzyć Meclis-i Vâlâ-yı Ahkâm-ı Adliyye jako wysoką radę, w której miały być omawiane przygotowywane ustawy i regulaminy. Według hasła TDV İslâm Ansiklopedisi o Meclis-i Vâlâ-yı Ahkâm-ı Adliyye rada faktycznie rozpoczęła pracę 31 marca 1838, a niemal wszystkie późniejsze reformy Tanzimatu były przygotowywane i kontrolowane przez ten organ. Instytucja ta stała się jednym z najważniejszych ośrodków nowoczesnej osmańskiej biurokracji.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["Napad na Synopę", "5947e93f"], "d": ["Rosyjska flota czarnomorska pod dowództwem admirała Nachimowa napadła bez wypowiedzenia wojny na flotę osmańską zakotwiczoną w porcie Synopa; zatopiono dwanaście okrętów, ponad dwa tysiące żołnierzy poległo jako męczennicy, a dowódca floty Osman Pasza został wzięty do niewoli. Według hasła TDV İslâm Ansiklopedisi o Synopie w napadzie spłonęło w mieście także siedem mescidów, dwie szkoły, 247 domów i 170 sklepów, zginęło pięciu muzułmańskich i szesnastu chrześcijańskich cywilów. Wydarzenie, które odbiło się w opinii europejskiej echem jako „tragedia Synopy”, stało się bezpośrednim zapalnikiem przystąpienia Anglii i Francji do wojny po stronie osmańskiej w ciągu kilku miesięcy.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["Początek wydawania Tasvir-i Efkâr", "506c98e2"], "d": ["Tasvir-i Efkâr wydawana przez Şinasiego rozpoczęła działalność jako czwarta gazeta turecka po Takvîm-i Vekāyi', Cerîde-i Havâdis i Tercüman-ı Ahvâl. Według hasła TDV o „Tasvîr-i Efkâr” gazeta stała się za czasów Nâmıka Kemala, który później objął funkcję redaktora naczelnego, rzecznikiem ruchu Nowych Osmanów.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["Założenie Towarzystwa Nowych Osmanów", "335fb02d"], "d": ["Osmańscy intelektualiści, którzy pod przewodnictwem Mustafy Fâzıla Paszy uciekli do Europy, zorganizowali się pod nazwą Młoda Turcja na mocy regulaminu o trzynastu artykułach. Według hasła TDV o „Towarzystwie Nowych Osmanów” grupa, wydając w Paryżu, Londynie i Genewie gazety takie jak Muhbir i Hürriyet, rozpowszechniała żądanie rządów konstytucyjnych.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["Utworzenie Şûrâ-yı Devlet", "b863b306"], "d": ["Meclis-i Ahkâm-ı Adliyye został podzielony na dwie części: utworzono Şûrâ-yı Devlet zajmującą się sprawami administracyjnymi i Dîvân-ı Ahkâm-ı Adliyye zajmujący się sprawami sądowymi. Według hasła TDV o „Şûrâ-yı Devlet” na pierwszego przewodniczącego instytucji, wzorowanej na francuskiej Conseil d'État, wyznaczono Midhata Paszę; celem było rozdzielenie władzy ustawodawczej, wykonawczej i sądowniczej.", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["Wydanie irade o założeniu Dârülfünun", "513704bf"], "d": ["Na mocy irade przygotowanego przez wielkiego wezyra Âlego Paszę i ministra oświaty Saffeta Paszę Dârülfünun zostało oficjalnie założone; pierwsze wykłady rozpoczęły się już wcześniej, w 1863. Według hasła TDV o „Dârülfünun” instytucja faktycznie rozpoczęła nauczanie w lutym 1870 pod kierownictwem Hoca Tahsina Efendiego z wydziałami filozoficzno-literackim, przyrodniczym i prawa.", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["Początek prac nad Mecelle-i Ahkâm-ı Adliyye", "8abdcbee"], "d": ["Towarzystwo Mecelle, utworzone pod przewodnictwem przewodniczącego Dîvân-ı Ahkâm-ı Adliyye Ahmeda Cevdeta Paszy, przystąpiło do przygotowania kodeksu cywilnego opartego na prawie hanafickim. Według hasła TDV o „Mecelle-i Ahkâm-ı Adliyye” ostatni zeszyt dzieła złożonego z szesnastu ksiąg i 1851 artykułów został ukończony 15 września 1876 i wszedł w życie; uchodzi za pierwszą skodyfikowaną postać prawa islamskiego.", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["Wystawiono „Vatan yahut Silistre”, Nâmık Kemal zesłany", "3861284c"], "d": ["Gdy patriotyczna sztuka Nâmıka Kemala została wystawiona w Teatrze Gedikpaşa, widzowie wylali się na ulice z okrzykiem „Niech żyje ojczyzna, niech żyje Kemal”. Według hasła TDV o „Nâmıku Kemalu” rząd, przestraszony tą manifestacją, zamknął gazetę İbret i 6 kwietnia 1873 zesłał Nâmıka Kemala bez procesu na Cypr (Famagusta).", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["Podejrzana śmierć Abdülaziza", "85816692"], "d": ["Abdülaziz, który po detronizacji z własnej woli został przeniesiony do Pałacu Fer‘iye (1 czerwca 1876), został 4 czerwca znaleziony w swoim pokoju z przeciętymi żyłami nadgarstków. Dziewiętnastoosobowa komisja lekarzy, w której byli także lekarze poselstw, sporządziła raport o niejasnym sformułowaniu; śmierć ogłoszono 6 czerwca w gazetach jako samobójstwo. Śledztwo otwarte przez Abdülhamida II doszło natomiast do przekonania, że śmierć była nie samobójstwem, lecz zabójstwem, a oskarżonych sądzono w 1881 w Sądzie Yıldız; sprawa pozostaje w historiografii sporna do dziś.", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["Odwołanie i zesłanie Midhata Paszy z wezyratu", "b5247b06"], "d": ["Wielki wezyr Midhat Pasza, architekt Kanûn-ı Esâsî, został sześć tygodni po jego ogłoszeniu odwołany przez Abdülhamida II i w ciągu jednej nocy zesłany za granicę. Według hasła TDV İslâm Ansiklopedisi o Midhacie Paszy odwołanie wiąże się z niezadowoleniem sułtana z postanowień konstytucji ograniczających jego uprawnienia. Pasza udał się najpierw do Neapolu, a następnie do różnych miast Europy.", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["Odzyskanie Rijadu przez Abd al-Aziza b. Sauda od Raszydów", "75eb8830"], "d": ["Młody Abd al-Aziz z dynastii Saudów, który dziesięć lat wcześniej udał się na wygnanie do Kuwejtu, napadł z małym oddziałem na Rijad i, zabiwszy zastępcę namiestnika Âl-i Reşîd (Szammar), zajął miasto. Według hasła TDV İslâm Ansiklopedisi o Rijadzie stopniowe osłabianie się Raszydów i to, że nie mogli przysłać do miasta posiłków, ułatwiły sukces napadu; wydarzenie uchodzi za moment założenia Drugiego Państwa Saudyjskiego, które w następnych trzydziestu latach miało stać się jądrem dzisiejszej Arabii Saudyjskiej.", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["Wkroczenie Armii Akcji do Stambułu", "41c8304c"], "d": ["Armia Akcji, która wyruszyła z Salonik i składała się w większości z oddziałów związanych z Komitetem Jedności i Postępu, weszła do Stambułu, by stłumić powstanie 31 marca. Według hasła TDV İslâm Ansiklopedisi o Armii Akcji dowództwo objął Mahmud Şevket Pasza, a funkcję szefa sztabu pełnił kapitan Mustafa Kemal. Po krótkich starciach w mieście przywrócono porządek.", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["Rozwiązanie ostatniego Meclis-i Mebusan osmańskiego", "2b709269"], "d": ["Po oficjalnej okupacji Stambułu przez siły Ententy i aresztowaniu wielu posłów Meclis-i Mebusan stał się niezdolny do pracy i został oficjalnie rozwiązany z woli Mehmeda VI. Według hasła TDV İslâm Ansiklopedisi o Meclis-i Mebusan to rozwiązanie symbolizowało faktyczny koniec osmańskiej tradycji parlamentu konstytucyjnego. Zamknięcie wzmocniło potrzebę zebrania się w Ankarze nowego zgromadzenia narodowego.", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["Otwarcie Wielkiego Zgromadzenia Narodowego Turcji", "6eab539d"], "d": ["Po rozwiązaniu Meclis-i Mebusan w Stambule posłowie zebrali się w Ankarze, otworzyli Wielkie Zgromadzenie Narodowe Turcji, a Mustafa Kemal Pasza został wybrany jego przewodniczącym. Według hasła TDV İslâm Ansiklopedisi o Wielkim Zgromadzeniu Narodowym Turcji zgromadzenie miało charakter nadzwyczajny, skupiając w sobie zarówno władzę ustawodawczą, jak i wykonawczą. To otwarcie było punktem zwrotnym, w którym polityczny i instytucjonalny ośrodek Walki Narodowej przeniósł się do Ankary. Wraz z tym wydarzeniem 124 miejscowości, w tym Konya, Sivas, Kayseri, Eskişehir, Erzurum, Trabzon, Samsun, Diyarbakır, Wan, Malatya, Denizli i Isparta (regiony Turcji niepozostające pod okupacją), weszły pod zarząd rządu Wielkiego Zgromadzenia Narodowego.", "47a80fa7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["Zdobycie twierdzy Zvornik (İzvornik)", "657c465a"], "d": ["Twierdza Zvornik nad Driną została zdobyta przez Osmanów w 1460. Według TDV İslâm Ansiklopedisi z powodu korzystnego położenia administracyjnego i wojskowego została najpierw uczyniona ośrodkiem kazy, w 1480 przekształcona w ośrodek sandżaku o tej samej nazwie, a w 1491 umocniona kamiennymi murami i wraz z sześcioma meczetami, ośmioma tekke i łaźniami stała się ważnym ośrodkiem administracyjno-handlowym.", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["Śmierć Kasima Chana, wstąpienie na tron Danyala Chana (Chanat Kasimowski)", "522fd0fd"], "d": ["Wraz ze śmiercią założyciela chanatu Kasima Chana w 873/1468 jego miejsce zajął syn Danyal; Danyal panował do 1486.", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["Bitwa morska pod Diu — przewaga Portugalii na Oceanie Indyjskim", "1778d347"], "d": ["Flota Maliku Ayaza, rządzącego regionem w imieniu Sułtanatu Gudżaratu, wsparta przez Mameluków, poniosła pod Diu ciężką klęskę wobec floty portugalskiego wicekróla Francisca de Almeidy, który próbował założyć bazę zaopatrzeniową na tych wybrzeżach. Ta klęska dała Portugalii trwałą przewagę morską na Oceanie Indyjskim i złamała potęgę morską Mameluków i Gudżaratu; uchodzi za początek nierównowagi sił stanowiącej tło walki o Morze Czerwone i Ocean Indyjski, którą Osmanowie przejęli po 1517 (obrona Dżuddy, oblężenie Diu 1538).", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["Powstanie Kalender Szacha", "f60f6ca4"], "d": ["Wskutek kłopotów finansowych w Anatolii, niezadowolenia z nowych uregulowań administracyjnych i wpływu propagandy safawidzkiej wielkie plemiona turkmeńskie, takie jak Çiçekli, Akça Koyunlu, Masadlı i Bozoklu, oraz grupy pozostałe po wcześniejszym powstaniu Baby Zünnûna zebrały się wokół Kalender Szacha i osiągnęły siłę około trzydziestu tysięcy ludzi. Powstańcy pokonali najpierw beylerbeja Rumu; gdy wielki wezyr Makbul İbrâhim Pasza zebrał wojsko i obiecał im prawa, poparcie dla Kalendera stopniało, powstanie zostało stłumione w okolicach Elbistan, a Kalender Szach i Veli Dündar zostali zabici w czerwcu 1527.", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["Zdobycie Şehrizoru — zajęcie twierdzy Zalm", "4320d9b8"], "d": ["W czasie wyprawy nachiczewańskiej Sulejmana beylerbej Bagdadu Osman Pasza miał zadanie zająć region Şehrizoru; po jego śmierci beylerbej Bagdadu Baltacı Mehmed Pasza, oblegając główną twierdzę regionu Zalm, zajął ją 22 sierpnia 1554 (23 ramadanu 961). W ten sposób basen Şehrizoru na zachodnim stoku Zagrosu wszedł pod zarząd osmański, a łączność między Bagdadem a Kurdystanem została zapewniona; region został najpierw przekształcony w sandżak i oddany Muradowi Bejowi. W 1563 beylerbej Muzaffer Pasza zbudował twierdzę Gülanber jako nowy ośrodek ejaletu; twierdza miała zostać w 1623 zburzona z rozkazu szacha Abbasa, a w 1638 odbudowana za Hüsreva Paszy.", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["Przejście władcy Chanatu Kasimowskiego na chrześcijaństwo i odsunięcie go od chanatu", "a1a8eeb9"], "d": ["Władca stojący na czele chanatu przyjął imię „Semen (Symeon)” i został chrześcijaninem; Rosjanie, biorąc pod uwagę reakcję muzułmańskich poddanych, odsunęli go od chanatu. Ten człowiek został wkrótce potem ogłoszony przez Iwana Groźnego w Moskwie nominalnym władcą z tytułem „wielkiego księcia cara i Rosji” (1575) — najbardziej uderzające przecięcie się Chanatu Kasimowskiego z tronem moskiewskim.", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["Związanie sandżaku Fezzan z Trypolitanią — Murzuk i skrzyżowanie karawan Sahary", "2e6554a4"], "d": ["Wskutek nacisku beylerbeyliku Trypolitanii Fezzan, skrzyżowanie karawan Sahary, z ośrodkiem w Murzuku, przyjął zwierzchnictwo osmańskie. Według hasła TDV İslâm Ansiklopedisi o Fezzanie rządząca regionem dynastia Awlâd Muhammad została pozostawiona swobodna w sprawach wewnętrznych pod warunkiem płacenia regularnego podatku; Fezzan zorganizowano jako sandżak podległy ejaletowi Trypolisu zdobytemu w 1551. W ten sposób handel niewolnikami, złotem i wielbłądami na linii Trypolis–Murzuk–Bornu przeszedł pod kontrolę osmańską. Ten pośredni zarząd miał w 1711 przejść w ręce Karamanlidów, a w 1842 w ręce bezpośredniej organizacji kaz.", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["Wejście Nachiczewanu i Ordubadu pod zarząd osmański", "24d939b3"], "d": ["Po zajęciu w 1583 Erywania i uczynieniu go ośrodkiem beylerbeyliku siły schodzące wzdłuż doliny Arasu na południowy wschód związały z zarządem osmańskim Nachiczewan i Ordubad; oba miasta stały się sandżakami nowo utworzonego ejaletu Erywań. Według hasła TDV İslâm Ansiklopedisi o Nachiczewanie pierwszy trwały zarząd osmański w mieście ustanowiono w czasie tej wojny — w wyprawie nachiczewańskiej z 1553 miasto zostało zajęte, lecz jedynie złupione i opuszczone. W ten sposób otwarto drogę armii między Erywaniem a Tabrizem i we wrześniu tego samego roku można było wejść do Tabrizu. Szach Abbas miał odzyskać Nachiczewan w 1603.", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["Powstanie Deli Hasana Paszy i jego uspokojenie beylerbeylikiem Bośni", "144f3f2d"], "d": ["Deli Hasan, brat Karayazıcı Abdülhalima, który po jego śmierci w 1602 stanął na czele ruchu, korzystając ze swobody ruchów, jaką trwające wojny austriackie dawały grupom celâlich, najechał Kütahyę i ruszył na Afyonkarahisar. W tym okresie, gdy państwo zmagało się jednocześnie z frontem austriackim i irańskim, sprawę rozwiązano „po dobroci”: Deli Hasanowi nadano rangę paszy i beylerbeylik Bośni, i powstanie zostało oficjalnie zakończone w 1603.", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["Zajęcie miasta Kasimow przez siły rosyjskie, Uraz Muhammad Chan", "b3f0bd34"], "d": ["Jako odbicie Smuty w Rosji siły rosyjskie oblegały i zajęły miasto Kasimow i wycięły większość jego ludności. Uraz Muhammad, stojący na czele chanatu, stał się celem, ponieważ poparł Dymitra II Samozwańca; w następnym roku (1610) sam został zabity w spisku.", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["Utrata twierdzy Azow na rzecz Kozaków Dońskich", "ba068b2f"], "d": ["Kozacy dońscy zdobyli twierdzę Azow, oblegając ją od 21 kwietnia 1637, po dwóch miesiącach; twierdza, będąca północno-wschodnią bramą Morza Czarnego i kluczem handlu dońskiego, po raz pierwszy wyszła z rąk osmańskich. Według hasła TDV İslâm Ansiklopedisi o Azowie Kozacy zajęli twierdzę w 1637, w 1641 wytrzymali trwające trzy miesiące wielkie oblężenie pod dowództwem Deli Hüseyina Paszy i opuścili twierdzę dopiero w 1642 wraz z przybyciem chana krymskiego Mehmeda Gireja. Państwo było wówczas zajęte frontem bagdadzkim; to, że twierdzy nie utrzymano przez pięć lat, jest pierwszym pęknięciem w „osmańskim jeziorze” Morza Czarnego.", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["Odzyskanie Limnos i Samotraki", "c445553b"], "d": ["Po wyzwoleniu Bozcaady 31 sierpnia 1657 Köprülü Mehmed Pasza skierował flotę na północ i odzyskał Limnos i Samotrakę, które Wenecja trzymała od szesnastu miesięcy. Według hasła TDV İslâm Ansiklopedisi o Limnos wyspa wpadła w ręce Wenecji w lipcu 1656 i została odzyskana w listopadzie 1657. W ten sposób blokada wenecka u wejścia do Dardaneli została całkowicie złamana, a droga zbożowa Stambułu ponownie zabezpieczona; jest to najbardziej konkretna zdobycz pierwszego roku, w którym wezyr przybył z nadzwyczajnymi uprawnieniami.", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["Utrata Kninu na rzecz Wenecji — padła 166-letnia twierdza graniczna Dalmacji", "252406b7"], "d": ["W wojnie rozpoczętej po klęsce pod Wiedniem w 1683 na wielu frontach siły weneckie posunęły się w głąb Dalmacji. Knin, oblężony przez generała Dalmacji Girolama Cornaro, został po dwunastodniowym oblężeniu oddany przez beylerbeja Mehmeda Paszę. Knin był kluczową twierdzą linii granicznej Dalmacji, zdobytej w 1522 przez Gazi Hüsrev Beja i pozostającej przez 166 lat w rękach osmańskich; jego utrata w znacznej mierze otworzyła region Wenecji.", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["Odzyskanie Basry spod okupacji irańskiej", "5b10c5c1"], "d": ["Basra, zajęta w 1776 przez Sâdıka Chana, brata Kerima Chana Zenda, została opuszczona, gdy po śmierci Kerima Chana 2 marca 1779 w Iranie rozpoczęła się walka o tron; Sâdık Chan wrócił do Iranu z roszczeniem do sułtanatu. Miasto pozostawało przez krótki czas w rękach plemienia Muntafiqów, po czym ponownie weszło pod zarząd osmański. Dawny mütesellim Süleyman Aga, który wrócił z Szirazu, zażądał namiestnictwa Basry i został pod imieniem Büyük Süleyman Paszy namiestnikiem Basry, Bagdadu i Şehrizoru. Handel w Zatoce wrócił pod kontrolę osmańską; w latach okupacji część handlu przesunęła się do Kuwejtu, a od 1778 także poczta pustynna była wysyłana z Kuwejtu.", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["Śmierć Timur Szacha, wstąpienie na tron Zaman Szacha (państwo Durrani)", "c3effdb2"], "d": ["Po śmierci Timur Szacha, który przez ponad dwadzieścia lat konsolidował kraj od wewnątrz, trzej bracia, namiestnicy Kandaharu, Heratu i Kabulu, rywalizowali o tron; namiestnik Kabulu Zaman Szach, trzymający stolicę, został szachem 20 maja 1793. Ten kryzys sukcesyjny jest faktycznym początkiem procesu rozpadu dynastii.", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa — zniesienie tradycyjnego systemu kapu na Hawajach", "0b10e1d8"], "d": ["Sześć miesięcy po śmierci Kamehamehy I nowy król Liholiho, przy poparciu matki Kaʻahumanu, świadomie złamał zakaz wspólnego jedzenia kobiet i mężczyzn (ʻaikapu). Ten czyn, zwany „ʻAi Noa” (wolne jedzenie), oficjalnie zakończył tradycyjny system religijno-prawny kapu; dawne świątynie (heiau) na wyspach wkrótce zburzono. Jest to największe załamanie religijno-polityczne przed przybyciem zachodnich misjonarzy (1820).", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["Protokół londyński — uznanie niepodległości Grecji", "4c7b4b72"], "d": ["Protokół podpisany w Londynie przez Anglię, Francję i Rosję, wykraczając poza autonomię przewidzianą w traktacie adrianopolskim, uznał Grecję za państwo NIEPODLEGŁE. Postanowienia: półwysep Morea, Attykę i Negroponte oraz Cyklady przekazano nowemu państwu; granicę wytyczono na linii Arta–Volos; postanowiono o wypłaceniu odszkodowania państwu osmańskiemu; formę rządów państwa określono jako „niepodległa monarchia”. Jest to PIERWSZE niepodległe państwo, które oderwało się od imperium, i ustanowiło prawny wzór późniejszych niepodległości bałkańskich. Do Grecji, której niepodległość uznano protokołem londyńskim, weszły wyspy Cykladów (Naksos, Tinos, Santorini, Paros, Antiparos, Syros, Mykonos i in.).", "920bfab9"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["Abdullah b. Raszid zajął emirat Hail — założenie dynastii Szammar (Raszydów)", "fb513b8a"], "d": ["Gdy w 1818, po zdobyciu Dirijji przez siły Mehmeda Alego Paszy, region Dżabal Szammar wyszedł spod panowania saudyjskiego, emirat pozostał w rękach rodu Ibn Ali. Abdullah b. Raszid, popierający ponowne ustanowienie panowania osmańskiego, wygrał w 1835 walkę prowadzoną wraz z bratem Ubeydem przeciw rodowi Ibn Ali, zajął emirat Hail i ustanowił panowanie dynastii Raszydów.", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["Ogłoszono pierwszą pisaną konstytucję Hawajów", "401a8a1d"], "d": ["Ogłoszono pierwszą pełną pisaną konstytucję królestwa; ten dokument, ograniczający uprawnienia króla i ustanawiający zgromadzenie przedstawicielskie, przekształcił Hawaje w monarchię konstytucyjną.", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["Konstytucja Bagnetowa — ograniczono uprawnienia króla Kalākauy", "4953363b"], "d": ["Uzbrojona grupa milicji, grożąc królowi Kalākaua, zmusiła go do podpisania nowej konstytucji, która w znacznej mierze ograniczyła uprawnienia królestwa; dokument zwany „Konstytucją Bagnetową” (Bayonet Constitution) faktycznie oddał tron pod kontrolę białej elity osadników.", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["Śmierć George'a Tupou I, wstąpienie na tron George'a Tupou II (Tonga)", "b56e2b32"], "d": ["Wraz ze śmiercią króla założyciela George'a Tupou I tron objął jego prawnuk George Tupou II; uroczystość koronacyjna odbyła się 17 marca 1893 w Nukuʻalofa.", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["Nowa Zelandia pierwszym samorządnym krajem przyznającym kobietom prawo głosu", "0d277cde"], "d": ["Na mocy nowej Ustawy Wyborczej podpisanej przez gubernatora lorda Glasgowa Nowa Zelandia została pierwszym samorządnym krajem na świecie przyznającym kobietom prawo głosu w wyborach parlamentarnych.", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["Ogłoszono Republikę Hawajów", "4346bd5d"], "d": ["W 1893 spiskowcy, którzy obalili królową Liliʻuokalani, przekształcili rząd tymczasowy w oficjalną republikę; prezydentem ogłoszono Sanforda Dole'a. Ten reżim przejściowy trwał do aneksji przez USA w 1898.", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["Granice Nowej Zelandii rozszerzono o Wyspy Cooka i Niue", "d0370a33"], "d": ["Granice Nowej Zelandii rozszerzono tak, by obejmowały Wyspy Cooka (Rarotonga, Aitutaki oraz wyspy południowe i północne Wyspy Cooka) i Niue; te wyspy stały się terytorium podległym Nowej Zelandii.", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["Śmierć George'a Tupou II, wstąpienie na tron Sālote Tupou III (Tonga)", "a3084f3b"], "d": ["George Tupou II zmarł na gruźlicę; jego 18-letnia córka Sālote została ogłoszona królową następnego dnia, a uroczystość koronacyjna odbyła się 11 października 1918.", "a63672b5"]},
"OLAYLAR_EK8:1920-04-26:0":{"b": ["Ogłoszenie Ludowej Republiki Chorezmu", "0a6b79f9"], "d": ["Po rewolucji październikowej 1917, wraz z obaleniem chana Chiwy, ogłoszono Ludową Republikę Chorezmu.", "1934b071"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["Traktat z Sèvres — tekst podziału imperium", "64980d7b"], "d": ["Tekst podpisany przez rząd osmański z państwami Ententy, który faktycznie likwidował imperium. Postanowienia: Trację Wschodnią i region Izmiru oddano Grecji; przewidziano niepodległą Armenię i autonomiczny Kurdystan we Wschodniej Anatolii; Syrię oddano Francji, a Irak i Palestynę Anglii jako mandaty; cieśniny przekazano komisji międzynarodowej; armię zredukowano do 50 700 osób, kapitulacje przywrócono, finanse oddano pod kontrolę Ententy. Wielkie Zgromadzenie Narodowe w Ankarze traktatu NIE UZNAŁO WCALE i ogłosiło sygnatariuszy zdrajcami ojczyzny; tekst nie wszedł w życie, a jego miejsce zajęła w 1923 Lozanna. To powód, dla którego nie ma on odpowiednika na mapie — Sèvres prawnie nigdy nie zostało zastosowane.", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["Armia Czerwona weszła do miasta Buchara — ostatni emir Âlim Chan odsunięty od tronu", "f8f5bfcf"], "d": ["Armia Czerwona weszła 2 września 1920 do miasta Buchara, a ostatni emir z dynastii Mangitów Âlim Chan został odsunięty od tronu. Emir wycofał się na wschód kraju, do Duszanbe, i przez pół roku stamtąd kierował walką z Sowietami; Armia Czerwona zajęła Duszanbe 21 lutego 1921, a emir przeszedł dalej na wschód i stamtąd do Afganistanu. Emirat został oficjalnie zniesiony 6 października 1920 (zob. Ludowa Republika Radziecka Buchary).", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["Ogłoszenie Buchary Ludowej Republiki Radzieckiej", "ef579627"], "d": ["Po tym, jak Armia Czerwona w dniach 28–31 sierpnia 1920 obaliła Emirat Buchary i zmusiła emira Alima Chana do ucieczki do Buchary Wschodniej, ogłoszono pod przewodnictwem Fajzullaha Chodżajewa Ludową Republikę Radziecką Buchary.", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["Ogłoszenie niepodległości Ludowej Republiki Tannu-Tuwy", "8710ea3d"], "d": ["Niepodległość ogłoszono pod przewodnictwem Tuwińskiej Ludowej Partii Rewolucyjnej; pierwszy artykuł pierwszej konstytucji stwierdzał, że państwo działa „w stosunkach międzynarodowych pod protekcją Rosji Sowieckiej”. Wraz z tym wydarzeniem Kyzył (Biełocarsk, Tannu-Tuwa) przeszedł do Ludowej Republiki Tannu-Tuwy.", "dc0ac64a"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["Przyjęcie nowej konstytucji Buchary Ludowej Republiki Radzieckiej", "fb17bf39"], "d": ["Przyjęto nową konstytucję, która, w odróżnieniu od rosyjskiej konstytucji z 1918, zezwalała na prywatną własność ziemi i środków produkcji i przyznawała prawo głosu także nieproletariuszom (z wyjątkiem krewnych obalonego emira i wielkich właścicieli ziemskich).", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["Przekształcenie w Chorezmijską Socjalistyczną Republikę Radziecką", "14a1d26f"], "d": ["Kraj zmienił nazwę i status i stał się Chorezmijską Socjalistyczną Republiką Radziecką; strukturę administracyjno-prawną uporządkowano na nowo według systemu radzieckiego.", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["Rząd Tannu-Tuwy faktycznie rozpoczął działalność", "22ea1516"], "d": ["Rząd utworzony po pierwszym zebraniu partyjnym w lutym 1922 faktycznie rozpoczął działalność.", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["Zebrał się pierwszy Wielki Churał Tannu-Tuwy", "80fe15f2"], "d": ["Zebrał się pierwszy Wielki Churał (Zgromadzenie Ludowe) kraju; jest to pierwsze wielkie zebranie przedstawicielskie w procesie instytucjonalizacji państwa.", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["Koniec Chorezmijskiej SRR i Buchary Ludowej Republiki Radzieckiej wskutek rozgraniczenia narodowego — utworzenie SRR Uzbekistanu i Turkmenistanu", "e8c8ab4f"], "d": ["Na mocy radzieckiego „rozgraniczenia narodowego” (natsionalno-territorialnoje razmieżewanije) Chorezmijska Socjalistyczna Republika Radziecka i Ludowa Republika Radziecka Buchary zostały zlikwidowane; ich ziemie podzielono między nowo utworzone Socjalistyczne Republiki Radzieckie Uzbekistanu i Turkmenistanu (wschód Chiwy do Uzbekistanu, zachód do Turkmenistanu). Hasło TDV `harizm`: „W 1924 wschodnie części Chanatu Chiwy zostały pozostawione Uzbeckiej Socjalistycznej Republice Radzieckiej, a strona zachodnia Turkmeńskiej Socjalistycznej Republice Radzieckiej.” — podaje tylko rok.", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["Sprzedaż Alaji sułtanowi mameluków Barsbajowi", "c8bd35f2"], "d": ["Alaja, zdobyta w 1293 roku przez Karamanoğlu Mecdüddina Mahmuda Beja, stała się odrębnym beylikiem rządzonym przez jedną z linii Karamanoğlu; Ibn Battuta odnotowuje, że w 1333 roku władał nią Karamanoğlu Jusuf Bej. Karaman b. Savci Bej sprzedał w 1427 roku miasto za pięć tysięcy złotych sułtanowi mameluków Barsbajowi i Alaja weszła pod rządy mameluków. Ten kluczowy port Morza Śródziemnego stał się tym samym przeszkodą w rękach mameluków na drodze Osmanów ku południu; w 1471 roku, gdy oblegał go Gedik Ahmed Pasza, ostatni bej Kılıçarslan oddał miasto.", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["Zajęcie Tabarki od Genueńczyków — koniec przywileju koralowego Lomellinich", "b1f33eb5"], "d": ["Po traktacie, który Karol V zawarł w 1544 z bejem Tunisu, genueński ród Lomellini osiadł na wyspie Tabarka i przez dwieście lat trzymał przywilej połowu koralowców; wyspa pozostawała pośrodku osmańskiego Tunisu chrześcijańską placówką handlową. Ali Pasza z dynastii Husajnidów, dowiedziawszy się o próbie pozbycia się wyspy przez ród, wysłał siły i zajął wyspę 12 czerwca 1741; około półtora tysiąca chrześcijan przeniesiono do Tunisu. Tabarka weszła od tej daty pod zarząd odżaku tunezyjskiego.", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["Bitwa pod piramidami i zajęcie Kairu przez Francuzów", "3ddd6b96"], "d": ["Napoleon ruszył z Aleksandrii na południe wzdłuż Nilu i 21 lipca 1798 roku pod Imbabą naprzeciw Gizy stoczył bój z kawalerią mameluków Murad Beja. Francuska piechota w szyku czworoboku odparła szarże kawalerii; armia mameluków się rozproszyła, a Kair poddał się dwa dni później bez walki. Murad Bej wycofał się do Górnego Egiptu, Ibrahim Bej do Syrii. Francuzi założyli w Kairze dywan i próbowali sprawować rządy rękami ulemów; w październiku 1798 i marcu 1800 roku wybuchły dwa wielkie powstania kairskie.", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["Oblężenie Akki przez Napoleona — zatrzymanie wyprawy syryjskiej", "d2a947ad"], "d": ["Napoleon, chcąc rozproszyć siły przygotowywane przez Osmanów w celu odzyskania Egiptu, wyruszył na początku 1799 roku do Syrii; zajął Al-Arisz 18 lutego, Jaffę w marcu, a 18 marca 1799 roku obległ Akkę. Obrona Dżazzara Ahmeda Paszy i wsparcie od strony morza brytyjskiego admirała Sidneya Smitha łamały oblężenie przez dwa miesiące; ponieważ działa oblężnicze przechwycono na morzu, murów nie zdołano sforsować. Napoleon wycofał się w maju, a klęska ta stała się najdalszym punktem francuskiej okupacji.", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["Powstanie państwa emira Abd al-Kadira — scentralizowanie oporu w zachodniej Algierii", "9e482383"], "d": ["Opór rozproszony po upadku Algieru skupił się wokół młodego Abd al-Kadira, syna szejka kadirytów Muhji ad-Dina; 22 listopada 1832 roku w pobliżu Mu'askaru przywódcy plemion złożyli mu przysięgę jako „emirowi wiernych”. Stworzona przez niego struktura nie była sojuszem plemion, lecz zorganizowanym państwem: miała mennicę, wytwórnię prochu, system podatkowy i stolicę w Tagdemcie. Francja w 1837 roku układem w Tafnie formalnie uznała jego władzę. Abd al-Kadir uznał zwierzchnictwo nie Osmanów, lecz sułtana Maroka Abd ar-Rahmana; zatem ziemie te po 1832 roku nie podlegają Osmanom. Poddał się 23 grudnia 1847 roku, a Państwo Osmańskie w tym samym roku ogłosiło wygaśnięcie swoich praw do Algierii.", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["Upadek Konstantyny — koniec bejlika wschodniego Algierii", "159fed36"], "d": ["Po upadku Algieru w 1830 roku wschodni beylerbeylik nie rozpadł się: ostatni bej Ahmed utrzymał własne rządy w Konstantynie i ogłosił, że działa w imieniu Osmanów. Pierwsza francuska wyprawa w 1836 roku zakończyła się klęską; druga oblegała miasto od 6 października 1837, dowódca Damrémont zginął od ognia armat 12 października, a 13 października mury zostały sforsowane i miasto zdobyto walcząc ulica po ulicy. Bej Ahmed wycofał się w góry i poddał się dopiero w 1848 roku. Ta data oznacza faktyczny koniec trzystuletnich rządów osmańsko-tureckich we wschodniej Algierii.", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["Podbój regionu Taka i założenie Kassali", "cc3e0631"], "d": ["Władca Sudanu Ahmed Pasza Abu Widan w 1840 roku podporządkował administracji egipskiej region Taka między rzekami Atbara i Gasz oraz założył miasto Kassala jako obóz wojskowy. Miasto stało się ośrodkiem mudiriji kontrolującej szlak karawan między Sennarem a Suakinem oraz abisyński pas graniczny.", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["Francuska okupacja Mascary (Muaskar) — utrata stolicy Abd al-Kadira", "bd363c05"], "d": ["Wraz z objęciem namiestnictwa przez Bugeauda w 1841 strategia francuska się zmieniła: zamiast utrzymywania się na wybrzeżu — zajmowanie jedno po drugim miast wewnętrznych. Ruchome kolumny wychodzące z Oranu, Mostaganem i Médéa zajęły ośrodki zorganizowanego państwa Abd al-Kadira; najważniejszą z nich była Mascara, prawdziwa stolica z mennicą, wytwórnią prochu i spichlerzami zbożowymi. Emir zrezygnował odtąd z zakładania stałego ośrodka i przekształcił swą armię w koczowniczy obóz zwany „smala”.", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["Zajęcie doliny Chélif i Ténès — założenie Orléansville", "e1eeeb68"], "d": ["Aby móc ścigać Abd al-Kadira, Francuzi założyli w kwietniu 1843 pośrodku doliny Chélif nowe miasto Orléansville; w tym samym roku zajęto także przybrzeżny port Ténès. W ten sposób wewnętrzny korytarz między Algierem a Oranem znalazł się pod kontrolą francuską, a opór w górach Dahra został otoczony. 16 maja tego samego roku koczowniczy obóz „smala” Abd al-Kadira został przypadkowo odnaleziony i rozproszony.", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["Założenie umocnionego obozu Sidi Bel Abbès", "fb33ec29"], "d": ["Bugeaud wydał 12 czerwca 1843 generałowi Bedeau rozkaz założenia w Sidi Bel Abbès umocnionego obozu z rowem i murem; budowę rozpoczęto 18 czerwca, a w listopadzie tego samego roku osiadł tu batalion Legii Cudzoziemskiej. Obóz stał się trwałą bazą kontrolującą wewnętrzną równinę między Oranem a Tlemcenem.", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["Przejście Nédromy i pasa granicznego z Marokiem pod kontrolę francuską", "61d821f3"], "d": ["Po wycofaniu się Abd al-Kadira do Maroka w 1843 Nédroma na północny zachód od Tlemcenu i wybrzeże Trara weszły pod kontrolę francuską. Bitwa pod Isly z 14 sierpnia 1844 rozbiła armię marokańską, a granicę między oboma krajami wytyczono konwencją z Lalla Maghnia z 18 marca 1845; Nédroma pozostała po algierskiej stronie tej linii.", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["Upadek Laghouat — otwarcie bramy Sahary", "b161b32c"], "d": ["Generał Pélissier oblegał Laghouat 21 listopada 1852 z sześciotysięcznymi siłami, a 4 grudnia miasto padło w krwawym szturmie. Laghouat było miastem-oazą trzymającym przejście między Tellem a Saharą; jego upadek otworzył francuskie natarcie na pustynne szlaki karawan i przygotował grunt pod objęcie w ciągu roku daniną konfederacji Mzab.", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["Przyłączenie ziemi Bogos (Keren) do Egiptu", "b2ab83ce"], "d": ["Werner Munzinger Pasza, gubernator wilajetu „Wschodni Sudan i wybrzeże Morza Czerwonego”, utworzonego przez chedywa Isma'ila na zachodnim brzegu Morza Czerwonego, w 1872 roku przyłączył do Egiptu ziemię Bogos, zamieszkaną przez lud Bilen, wraz z jej ośrodkiem Keren. Było to najtrwalsze posunięcie Egiptu na skraju wyżyny abisyńskiej i zapoczątkowało trwający dwanaście lat spór graniczny z Abisynią.", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["Aneksja Sułtanatu Darfuru do Egiptu — Zubayr Pasza wkroczył do El Fasher", "f41268ed"], "d": ["Zubayr Rahmat Pasza, który wzmocnił się handlem kością słoniową i niewolnikami, rozproszył 25 października 1874 pod Menawaszi armię Furów siłami uzbrojonymi w karabiny Remington; sułtan Ibrahim zginął w bitwie. Zubayr wkroczył bez walki do El Fasher 2 listopada i panowanie dynastii Kejra trwające od 1603 faktycznie się skończyło. Darfur został w ten sposób przyłączony do prowincji Sudanu Egiptu z Kawali; opór rodu Kejra w górach trwał jednak do 1891.", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["Aneksja oaz Mzab (Ghardaïa)", "9372959f"], "d": ["Ibadyckie miasta Mzab w 1852 zgodziły się płacić Francji podatek, lecz zachowały zarząd wewnętrzny; po trzydziestu latach, w 1882, region został bezpośrednio przyłączony do ziem francuskich, a Ghardaïa związano z zarządem wojskowym. W ten sposób ostatni autonomiczny pas północnej Sahary również prawnie się skończył.", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["Bombardowanie Aleksandrii i lądowanie brytyjskie", "18d57bf8"], "d": ["Gdy ruch oficerów pod wodzą Urabi Paszy wziął chedywa pod kontrolę, Wielka Brytania interweniowała pod pretekstem bezpieczeństwa szlaku sueskiego. Flota admirała Seymoura ostrzelała w dniach 11-12 lipca 1882 roku nadbrzeżne bastiony Aleksandrii; po pożarze i grabieży w mieście 15 lipca wylądowały wojska brytyjskie. Państwo Osmańskie nie zdołało powstrzymać tej operacji w prawnie podległej mu prowincji i nie odpowiedziało na wezwanie do udziału w interwencji. Tak postawiono pierwszy krok ku okupacji, która miała trwać trzydzieści dwa lata.", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["Bitwa pod Tel el-Kebir — rozbicie armii Urabiego", "8e38fecf"], "d": ["Wolseley wysadził swoje siły w Ismailii nad Kanałem Sueskim i po marszu przez pustynię o świcie 13 września 1882 roku zaatakował z zaskoczenia egipskie szańce pod Tel el-Kebir; bitwa trwała godzinę. Urabi poddał się następnego dnia, a kawaleria brytyjska wkroczyła tego samego dnia do Kairu. Od tej daty finanse, wojsko i sprawy zagraniczne Egiptu faktycznie przeszły pod kontrolę brytyjską; zwierzchnictwo osmańskie trwało prawnie do 1914 roku.", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["Konwencja z Marsa (La Marsa) — dopełnienie protektoratu nad Tunezją", "71338640"], "d": ["Układ z Bardo (Kasr as-Sa'id) z 12 maja 1881 roku oddał Francji sprawy zagraniczne Tunezji, lecz sprawy wewnętrzne pozostawił beja; podpisana dwa lata później, 8 czerwca 1883 roku, Konwencja z Marsa oddała pod kontrolę francuską także reformy finansowe i administracyjne i dopełniła protektoratu. Państwo Osmańskie podtrzymywało roszczenie do zwierzchnictwa nad Tunezją i nigdy nie uznało okupacji, lecz nie zdołało podjąć faktycznego kroku przeciwnego. W ten sposób Tunezja, od 1574 roku osmański ocak, formalnie weszła pod protektorat francuski.", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["Klęska pod Szajkan — zagłada armii Hicksa Paszy", "a0e08986"], "d": ["Hicks Pasza, emerytowany oficer brytyjski dowodzący wysłanymi z Kairu egipskimi siłami liczącymi około dziesięciu tysięcy ludzi, posuwając się przez pustynię Kordofanu bez wody i bez przewodników, został 5 listopada 1883 roku okrążony pod Szajkan przez siły Mahdiego, a armia została niemal całkowicie zniszczona. Klęska ta złamała kręgosłup egipskich rządów w Sudanie: w ciągu miesiąca poddały się Darfur i Bahr el-Ghazal, a cały Kordofan przeszedł w ręce Mahdiego. Stąd zaczyna się droga ku upadkowi Chartumu.", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["Przejście Darfuru w ręce sił Mahdiego — poddanie się Slatina Paszy", "6d8992d4"], "d": ["Generalny namiestnik Darfuru Slatin Pasza od 1882 zmagał się z mahdystowskim powstaniem plemienia Rizeikat; uznając, że jego żołnierze przypisywali swe klęski jego chrześcijaństwu, w 1883 jawnie przyjął islam i przybrał imię Abdülkâdir. Po zniszczeniu armii Hicksa Paszy w listopadzie 1883 w Kordofanie opór stracił sens i 23 grudnia 1883 poddał się emirowi Madibbo. Małe posterunki egipskie w Darfurze szybko poszły tą samą drogą; dziesięcioletni zarząd turecko-egipski dobiegł końca. Wraz z tym wydarzeniem Dżabal Marra (Darfur) przeszedł pod zarząd państwa Mahdiego.", "bd700253"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["Przejście Zejli i wybrzeża Somalii pod administrację brytyjską", "1d649502"], "d": ["Gdy powstanie mahdystów załamało egipskie garnizony w Sudanie i nad Morzem Czerwonym, Kair musiał opróżnić odległe posterunki na wybrzeżu abisyńskim. Administracja brytyjska w Adenie w 1884 roku wysadziła wojska w Zejli i Berberze; w następnym roku podpisano z wodzami plemion somalijskich układy protektoratowe i powstała Somalia Brytyjska. Zejla, od 1559 roku podległa prowincji abisyńskiej, została w ten sposób utracona.", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["Poddanie garnizonu Fasher mahdystom", "68f0760d"], "d": ["Także po poddaniu się Slatina 23 grudnia 1883 garnizon egipski w twierdzy Fasher stawiał opór. Garnizon, który w siedmiodniowym oblężeniu stracił studnie, poddał się 15 stycznia 1884; broń złożono, a twierdza przeszła w ręce mahdystów.", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["Układ Hewetta (Adua) — oddanie Bogos Abisynii", "0de1b701"], "d": ["Gdy powstanie mahdystów otoczyło egipskie garnizony w Sudanie, Wielka Brytania, chcąc pozyskać pomoc Abisynii, podpisała 3 czerwca 1884 roku w Aduie układ z Janem IV. Drugi artykuł układu zwracał Bogos Abisynii, w zamian Abisynia miała umożliwić ewakuację oblężonych garnizonów przez Massawę. Keren wyszło w ten sposób spod dwunastoletnich rządów egipskich; pięć lat później region miał zostać włączony do włoskiej Erytrei.", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["Odzyskanie Dongoli — początek wyprawy wzdłuż Nilu", "f63aa14f"], "d": ["Po klęsce Włochów pod Aduą Wielka Brytania poprowadziła armię egipską pod dowództwem Kitchenera na południe wzdłuż Nilu. W miarę jak kolej posuwała się przez pustynię, rozwiązano problem zaopatrzenia i wilajet Dongola został odzyskany 23 września 1896 roku. Tu zakończyły się jedenastoletnie rządy mahdystów; wyprawa trwała jeszcze dwa lata, aż do Omdurmanu.", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["Bitwa pod Omdurmanem — upadek państwa Mahdiego", "28dff7b2"], "d": ["Armia angielsko-egipska Kitchenera, uzbrojona w artylerię i karabiny maszynowe, rozproszyła 2 września 1898 roku w ciągu kilku godzin pod Omdurmanem siły kalifa Abdullaha at-Ta'aishiego. Następnego dnia wkroczono do Chartumu i podniesiono flagę w pałacu, w którym trzynaście lat wcześniej zginął Gordon. Stolica państwa Mahdiego upadła; kalif zginął pod koniec 1899 roku w pościgu. Faktyczne zwierzchnictwo zmienia ręce w tej dacie — 19 stycznia 1899 to zaś układ ustanawiający ramy prawne administracji. Po tej klęsce państwa Mahdiego Darfur (El-Faszir, Njala, Dżunajna, Kutum i in.) przeszedł pod władzę Sułtanatu Darfuru odbudowanego przez Alego Dinara.", "ad27827a"]},
"OLAYLAR_EK9:1899-01-19:0":{"b": ["Układ o kondominium — wspólna anglo-egipska administracja Sudanu", "8033c688"], "d": ["Układ podpisany w Kairze cztery miesiące po Omdurmanie poddał Sudan wspólnym rządom obu państw pod nazwą „Sudanu anglo-egipskiego”: miały być podnoszone razem dwie flagi, a generalny gubernator miał być mianowany przez chedywa za zgodą Wielkiej Brytanii. W praktyce administracja była całkowicie w rękach Brytyjczyków. Państwo Osmańskie, twierdząc, że jego prawa do Sudanu należą do niego za pośrednictwem Egiptu, nie przystąpiło do układu i go nie uznało; faktycznie jednak pozostało na zewnątrz. Na mocy tego układu ziemie Sudanu na południe od 22. równoleżnika (Dongola, Chartum, Sennar, Kordofan, wybrzeże Suakinu i in.) przeszły pod wspólną administrację anglo-egipską (Sudan anglo-egipski).", "097331bb"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["Włoskie lądowanie w Tobruku — pierwsza okupacja w Trypolitanii", "44780018"], "d": ["Włochy wypowiedziały wojnę 29 września 1911 roku, a ich flota w dniach 25-26 września objęła wybrzeże blokadą. Pierwsza operacja lądowa nastąpiła 8 października w Tobruku: niewielki garnizon osmański wycofał się w głąb lądu, a port zajęto bez walki. Tobruk był osmańskim portem najbliższym granicy egipskiej; jego upadek otworzył wschodnie skrzydło Barki i ułatwił siłom włoskim marsz na zachód wzdłuż wybrzeża.", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["Kapitulacja miasta Trypolis przed Włochami", "785091ad"], "d": ["Trypolis poddał się 9 października 1911 roku po trzech dniach bombardowania. Siły osmańskie zamiast bronić miasta wolały wycofać się do Azizijji i Garjanu, by zorganizować opór w głębi kraju; opór ten, w którym uczestniczyli Enver i Mustafa Kemal, uwięził Włochów na pasie wybrzeża do końca wojny. Zatem choć miasto padło, wnętrze wilajetu pozostało pod kontrolą osmańską.", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["Utrata Derny wskutek włoskiego desantu", "f014c741"], "d": ["Po Tobruku przyszła kolej na Dernę, drugi port Barki; miasto zajęto 16 października 1911 roku. Płaskowyż wokół Derny był regionem o największym zagęszczeniu bractwa Senusijja, a mudżahedini zebrani na wezwanie szejka Ahmeda Szarifa utrzymywali Włochów w okrążeniu wokół portu. Okupacja ograniczyła się do miasta i nigdy nie sięgnęła zaplecza.", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["Włoskie lądowanie w Benghazi — utrata ośrodka sandżaku Barka", "f9183c40"], "d": ["Benghazi, ośrodek Barki, zajęto 21 października 1911 roku czwartym i najważniejszym desantem na wybrzeżu. Tak więc Włochy w trzy tygodnie po wypowiedzeniu wojny trzymały wszystkie duże porty wilajetu Trypolitanii (Trypolis, Tobruk, Dernę, Benghazi), lecz do zaplecza żadnego z nich nie zdołały wejść. Pozostały rok wojny upłynął na bezskutecznych natarciach w głąb lądu z tych czterech punktów na wybrzeżu.", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["Jednostronny dekret włoski o aneksji", "cfe3f9c2"], "d": ["Włochy, w trakcie wojny, 5 listopada 1911 roku wydały dekret ogłaszający aneksję Trypolitanii i Barki. Państwo Osmańskie go nie uznało i wojna trwała jeszcze rok; aneksja uzyskała moc prawną dopiero na mocy traktatu w Ouchy z 18 października 1912 roku. Dlatego dekret nie zmienia na mapie osmańskiego koloru — własność prawna należy do Osmanów do 1912 roku, a włoska kontrola jest pokazana jako okupacja zakreskowana.", "23668758"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Zajęcie Köprühisar i przygotowanie do założenia Yenişehir", "39abff03"], "d": ["Zdobyto twierdze przejściowe między Bursą a Nikeą, kładąc podwaliny wysuniętej kwatery, która miała otoczyć oba miasta.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Założenie Yenişehir", "d3275837"], "d": ["Dla kierowania oblężeniami Bursy i Nikei utworzono pierwsze regularne osiedle garnizonowe osmańskie; Orhan Gazi urodził się tutaj.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Pierwsze oblężenie Nikei i zdobycie Marmaracık", "cdca2349"], "d": ["Nikeę oblężono po raz pierwszy, lecz nie zdobyto (ostateczne zdobycie nastąpi w 1331); w tym czasie zajęto pobliską twierdzę Marmaracık.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Wyprawa Katalończyków w Anatolii", "4fd940d5"], "d": ["Oddział katalońskich najemników wynajęty przez Bizancjum do powstrzymania tureckiego natarcia odniósł tymczasowe sukcesy, lecz nie utrzymał się; po ich wycofaniu natarcie bejlików pogranicznych przyspieszyło.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal przyjął islam i dołączył do Osmanów", "ca0d86e1"], "d": ["Tekfur Harmankaya Köse Mihal, przyjąwszy islam, dołączył do Osmana Gazi wraz z twierdzą i swoimi ludźmi; został pierwszym bizantyjskim dowódcą osmańskim.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan Bej faktycznie przejął rządy", "6dadbefc"], "d": ["Wskutek starości i choroby Osmana Gazi faktyczne dowodzenie oblężeniem Bursy i wyprawami przeszło na jego syna Orhana Beja (oficjalne wstąpienie na tron nastąpiło w 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Zajęcie Mudanyi", "0a623368"], "d": ["Zdobyto port Bursy, Mudanyę, odcinając miasto od morza; oblężenie Bursy weszło w fazę duszenia.", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Zdobycie Akyazı i wyspy İmralı", "d041b0c8"], "d": ["Zdobyto Akyazı na północ od Sakaryi; wraz z zajęciem wyspy İmralı Osmanowie po raz pierwszy zaczęli sąsiadować z Wyspą Marmara.", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["Zdobycie Gemlik (Kios) i Armutlu", "682d3bac"], "d": ["Odcięto ostatnie połączenie morskie Bursy, doprowadzając miasto do stanu gotowości do poddania się w 1326.", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akça Koca zajął Kandıra i okolice", "341bb97e"], "d": ["Akça Koca, jeden z bejów pogranicznych Orhana Gazi, prowadząc z kwatery na zachód od jeziora Sapanca napady na okolice İzmitu, ku 1326 roku zajął Kandıra i okolice. İzmit pozostawał jeszcze w rękach bizantyjskich; miasto miało upaść dopiero w 1337.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Przyłączenie Yalova i Karamürsel", "133cb07a"], "d": ["Yalova i okolice na południowym brzegu zatoki İzmitu przeszły w tym roku w ręce Turków; pas przybrzeżny Orhan Bej nadał jako timar Karamürselowi Gazi.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akça Koca zdobył Aydos i twierdzę Samandıra", "ce4daa8a"], "d": ["Po zajęciu Kandıry Akça Koca wraz z Konuralpem i Gazi Abdurrahmanem zdobył twierdzę Aydos w okolicach Kartal, a następnie leżącą na północ twierdzę Samandıra; okolice Samandıry nadano mu jako własność. Akça Koca zmarł w 1328 w pobliżu Kandıry; dowództwo graniczne nad regionem powierzono księciu Muradowi.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Sojusz osmańsko-aydyńsko-saruhański", "9df6bb74"], "d": ["Trzy bejliki wystąpiły wspólnie przeciw Bizancjum; flota Umura Beja z Aydınoğlu, dokonując napadów na wybrzeża Tracji, wyczerpywała Bizancjum na drugim froncie.", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Małżeństwo Orhana Gazi z Teodorą: sojusz z Bizancjum", "9b67a590"], "d": ["Orhan Gazi, który w bizantyjskiej walce o tron poparł Kantakuzena, ożenił się z jego córką Teodorą; sojusz ten pozwolił siłom osmańskim dobrze poznać Rumelię.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Zajęcie Ankary", "49bf1f6d"], "d": ["Ankara pod zarządem ahich weszła pod władzę osmańską; otwarto drogę przez Anatolię Środkową. W tym samym dniu przyłączono także inne miejscowości: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Natarcie w Tracji za czasów Süleymana Paszy: Malkara, İpsala i Tekirdağ", "fb31cf02"], "d": ["Po utworzeniu przyczółka w Gallipoli Süleyman Pasza, wychodząc z półwyspu na północ, krok po kroku zajął równinę między wybrzeżem Marmary a ujściem Maricy. Malkara, İpsala i Rodosçuk (Tekirdağ) utworzyły w ten sposób nieprzerwany korytarz łączący Gallipoli z doliną Maricy. Bez tego korytarza nie można było ruszyć na Edirne; natarcie wstrzymane nagłą śmiercią księcia w 1357 kontynuowali Lala Şahin i Hacı İlbey.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Porwanie księcia Halila", "b52ac3d7"], "d": ["Młodszy syn Orhana Gazi, Halil, został porwany przez piratów z Fokai; kryzys okupu przez lata zajmował stosunki osmańsko-bizantyjskie.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Odcięcie dróg pomocy dla Edirne: twierdze Çorlu, Lüleburgaz, Babaeski i Keşan", "8e8ad485"], "d": ["Książę Murad, który po uwolnieniu Halila ponownie rozpoczął działania zdobywcze, wysłał akindżich aż pod Stambuł, by odizolować Edirne od pomocy z zewnątrz. Zajęto twierdze Çorlu, Lüleburgaz i Babaeski na drodze Stambuł–Edirne oraz Keşan na skrzyżowaniu dróg Południowej Tracji. Poddanie Edirne nastąpiło po zamknięciu tego pierścienia oblężniczego.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Zajęcie Dimetoki — otwarcie doliny Maricy", "b59aee83"], "d": ["Zdobyto Dimetokę, kluczową twierdzę doliny Maricy; otworzyło to drogę do zdobycia Edirne. Nie można było ruszyć na Edirne bez dokończenia korytarza biegnącego od Gallipoli na północ, dlatego twierdza w kolejności podbojów Rumelii poprzedza Edirne. Miasto przez pewien czas było kwaterą sułtanów w Rumelii. Siły, które zajęły Dimetokę, objęły następnie kontrolą cały region Środkowej Maricy wraz z małymi twierdzami, takimi jak Kuleli Burgaz (Pythion).", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Utrata Gallipoli (wyprawa krzyżowa sabaudzka)", "00e7e415"], "d": ["Flota Amadeusza Sabaudzkiego, kuzyna cesarza bizantyjskiego, zdobyła Gallipoli i oddała je Bizancjum; osmański przyczółek w Rumelii był przez dziesięć lat zarządzany z drugiej strony cieśniny. W tym samym dniu utracono także inne miejscowości: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Bitwa pod Çirmen — kontrola doliny Maricy", "cd738d8d"], "d": ["Armia serbskich bejów została rozproszona w nocnym napadzie; lokalni serbscy i bułgarscy beje w Macedonii i Rodopach zaczęli jeden po drugim płacić Osmanom daninę — nie było to bezpośrednie zdobycie, lecz początek fali wasalizacji. W przekazie osmańskim bitwa ta opowiadana jest także pod nazwą «Sırpsındığı» i pod rokiem 1364, jako nocny napad Hacı İlbeya na armię krzyżowców, która przybyła, by odzyskać Edirne; TDV zaznacza, że ta data jest błędna i że obie relacje dotyczą tej samej bitwy.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Zdobycie Płowdiwu i Starej Zagory", "e780c9ae"], "d": ["Zdobyto Płowdiw w górze doliny Maricy i leżącą na północ Starą Zagorę; carstwo bułgarskie objęto daniną. Szlak Tatarpazarcığı i İhtiman między Płowdiwem a Sofią pozostał w rękach lokalnych bejów, którzy po Çirmen stali się wasalami.", "b8131db8"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Bizancjum jako wasal: Jan V w armii Murada I (skutek zwycięstwa pod Çirmen w 1371)", "13ffe568"], "d": ["Według TDV po zwycięstwie pod Çirmen (Marica) z 26 września 1371 Cesarstwo Bizantyjskie uznało zwierzchnictwo osmańskie i, godząc się na płacenie daniny i służbę w armii osmańskiej, znalazło się w położeniu państwa wasalnego. Cesarz Jan V przyłączył się z tym zobowiązaniem w 1373 do armii Murada I; jego syn Andronik IV, którego zostawił wówczas w Stambule, zbuntował się przeciw ojcu wraz z księciem Savcı Bejem w Bursie.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Odzyskanie Gallipoli", "5f96c0a5"], "d": ["Andronik IV, który w bizantyjskim sporze o tron otrzymał wsparcie osmańskie, w zamian zwrócił Gallipoli; most między Rumelią a Anatolią został odtworzony. W tym samym dniu przyłączono także inne miejscowości: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Posag germiyański: przyłączenie Kütahyi", "d6a6fe61"], "d": ["Przy małżeństwie Devletşah Hatun, córki Germiyanoğlu Süleymana Szaha, z Bayezidem Błyskawicą Kütahya, Simav, Tavşanlı i Eğrigöz przeszły do Osmanów jako posag — klasyczny przykład ekspansji bez wojny. W tym samym dniu przyłączono także inne miejscowości: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Zakup prowincji Hamîd: przyłączenie Isparty", "4a1b6047"], "d": ["Hamîdoğlu Hüseyin Bej sprzedał Muradowi I za gotówkę część swojego bejliku (Akşehir–Beyşehir–Isparta); pozostała część prowincji Hamîd miała zostać anektowana przez Błyskawicę w 1391.", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Zdobycie Serez", "d4d28b60"], "d": ["Zdobyto Serez, klucz do Macedonii Wschodniej; Saloniki znalazły się w pierścieniu oblężenia. Linia Köstendil–Petriç–Nevrokop–Drama między Sofią a Serez nie była w tym czasie jeszcze bezpośrednio przyłączona; przechodziła kolejno w okresie lat 1370–1383 do zależności wasalnej, a po 1383 do zarządu bezpośredniego.", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Zdobycie Sofii", "96d5f01f"], "d": ["Opanowano zachodnie przełęcze gór Bałkan; ponieważ Serez znajdowało się już od 1383 w rękach osmańskich, ziemie Tracji i Macedonii tworzyły w tym czasie nieprzerwaną całość.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Zdobycie Niszu", "77f5d632"], "d": ["Wraz ze zdobyciem Niszu, klucza do doliny Morawy, serbski despotat znalazł się pod bezpośrednim zagrożeniem.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Pierwsze poddanie Salonik", "96010ee9"], "d": ["Po długiej blokadzie miasto się poddało (w 1403 zostanie zwrócone Bizancjum, w 1430 ostatecznie zdobyte). W tym samym dniu przyłączono także inne miejscowości: Kawala.", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Ahidname osmańsko-genueńskie — odnowienie układu z 1352", "be11d17a"], "d": ["Z posłami genueńskimi z Pery odnowiono układ handlowy z 1352 roku z czasów Orhana Gazi; ponownie ustalono podatki między obu państwami, traktowanie jeńców i wolny handel. Uważa się go za pierwszy oficjalnie znany akt przyjaźni i handlu (ahidname) między Osmanami a Genueńczykami — nie sojusz wojskowy, lecz układ całkowicie handlowy.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Wyprawa Çandarlı Alego Paszy do Bułgarii: zajęcie Şumnu i Ruse", "2781c3a9"], "d": ["Twierdze Carstwa Bułgarskiego nad Dunajem zostały przejęte podczas jednej wyprawy; nie należy mylić jej z klęską poniesioną w tym samym roku w Bośni pod Bileą — był to jednoczesny sukces na odrębnym froncie. Tyrnowo i Widyń były jeszcze ostatnimi utrzymywanymi ośrodkami bułgarskimi.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Klęska pod Bileą", "89ba0a64"], "d": ["Oddział akindżich zmierzający do Bośni został wciągnięty w zasadzkę pod Bileą i zniszczony; ta pierwsza wielka niepowodzenie na Bałkanach dodało odwagi sojuszowi zmierzającemu ku Kosowu.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Aneksja bejlików Anatolii Zachodniej: Saruhan, Aydın, Menteşe", "dcc33b71"], "d": ["Trzy bejliki przyłączono jednorazowo: Manisa, ośrodek Saruhanoğulları; Aydın, ośrodek Aydınoğulları (łącznie z górną twierdzą Izmiru, ale port i dolna twierdza nadal w rękach joannitów — do 1402); Muğla–Milas, ośrodek Menteşeoğulları, łącznie z pasem przybrzeżnym Datça–Bodrum–Marmaris–Fethiye. Wybrzeża Morza Egejskiego po raz pierwszy zjednoczono w jednym ręku. W tym samym dniu przyłączono także inne miejscowości: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Aneksja prowincji Teke: przyłączenie Antalyi", "fdbeee5c"], "d": ["Prowincję Teke na wybrzeżu Morza Śródziemnego przyłączono do ziem osmańskich. Tekeoğulları są odgałęzieniem oddzielonym od Hamîdoğulları: Feleküddin Dündar Bej zostawił zdobytą Antalyę bratu Yûnusowi Bejowi i około 1321 roku powstał odrębny bejlik. Dlatego Antalya i okolice są na mapie po 1321 roku pokazane kolorem Tekeoğulları, a nie Hamîdoğulları. Bejlik został odtworzony po bitwie pod Ankarą i ostatecznie zlikwidowany dopiero w 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Zdobycie Skopje", "9e5a1af5"], "d": ["Zdobyto ośrodek Macedonii Wardarskiej; Skopje stało się jednym z głównych ośrodków pogranicznych Rumelii.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Aneksja Kastamonu", "876330ba"], "d": ["Zlikwidowano gałąź Kastamonu rodu Candaroğulları; gałąź z Synopy trwała jako wasalna. W tym samym dniu przyłączono także inne miejscowości: Bartın, Safranbolu.", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Upadek Tyrnowa — aneksja Bułgarii", "ff666977"], "d": ["Stolica carstwa bułgarskiego padła; Bułgaria weszła pod bezpośredni zarząd osmański. W tym samym dniu przyłączono także inne miejscowości: Plewen, Łowecz.", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["Twierdza Łowecz (Loveç) przeszła do Osmanów", "a55e87a0"], "d": ["Łowecz, jedna z twierdz cara bułgarskiego Iwana Szyszmana, została przyłączona do ziem osmańskich w wyprawie 1393 roku, w której padło Tyrnowo, razem z pozostałymi prowincjami Szyszmana. Źródło nie wypowiada się stanowczo: «przypuszcza się», że zdobycie nastąpiło w tym roku.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Przyłączenie Dobrudży", "478e36f2"], "d": ["Przyłączono ziemie Dobrudży sięgające delty Dunaju. W tym samym dniu przyłączono także inne miejscowości: Silistra, Konstanca.", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Zejście do Tesalii", "8bec60dd"], "d": ["Równinę Tesalii z ośrodkiem w Yenişehir (Larissa) objęto zarządem osmańskim. W tym samym dniu przyłączono także inne miejscowości: Tırhala, İzdin (Lamia).", "d9f2128c"]},
"OLAYLAR_EK:1394-01-01:1":{"b": ["Początek ścisłego oblężenia Stambułu (blokada od ok. 1387)", "0068bc04"], "d": ["Bayezid Błyskawica trzymał Stambuł w blokadzie z przerwami przez dziesięć lat; miasto ocalało dopiero dzięki zbliżaniu się Timura.", "504fcb33"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Bitwa pod Rovine — wyprawa na Wołoszczyznę", "343ae7a9"], "d": ["Po krwawej bitwie o spornym wyniku z wojewodą wołoskim Mirczą Wołoszczyzna zgodziła się płacić Osmanom daninę; ustanowiono ład wasalny na północ od Dunaju.", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Zdobycie Nikopolis", "b9791717"], "d": ["Po bitwie pod Rovine w 1395 roku przeciw Wołochom Bayezid Błyskawica zajął twierdzę Nikopol nad Dunajem; niektóre anonimowe kroniki bułgarskie podają, że zdobycie nastąpiło 3 czerwca 1395. Data zdobycia nie jest w źródłach jednolita: hasło o bitwie pod Nikopolis w TDV İslâm Ansiklopedisi pisze, że Bayezid zdobył Silistrę i Nikopol w wyprawie naddunajskiej w 1394. Twierdza miała być oblężona w słynnej wyprawie krzyżowej 1396, lecz nie upadła. W tym samym dniu przyłączono także inne miejscowości: Ochryda.", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["Twierdza Nikopol przeszła do Osmanów", "327012c9"], "d": ["Po napadzie pod Rovine Bayezid Błyskawica zajął Nikopol; car bułgarski Iwan Szyszman, który tam rezydował jako wasal osmański, został usunięty. W atlasie Nikopol jest zapisany od tego dnia jako przechodzący od Carstwa Bułgarskiego do Osmanów.", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Budowa Anadolu Hisarı", "aa259b00"], "d": ["Dla wsparcia blokady Stambułu zbudowano na anatolijskim brzegu Bosforu Güzelcehisar (Anadolu Hisarı) — pierwszy trwały krok ku kontroli cieśniny.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Aneksja Widynia", "ee1ae44b"], "d": ["Po zwycięstwie pod Nikopolis anektowano także ostatnie bułgarskie księstwo, Widyń.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Pierwsza aneksja Karamanu", "3cf07876"], "d": ["Dzięki zwycięstwu pod Akçay po raz pierwszy przyłączono ziemie Karamanoğlu do Osmanów (zostaną odtworzone w czasie Interregnum).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Przyłączenie wybrzeży Canik: Samsun", "af9c40fa"], "d": ["W próżni powstałej po dostaniu się Kadı Burhâneddina do niewoli Karayülüka Osmana Beja z Akkoyunlu Bayezid Błyskawica objął najpierw zarządem osmańskim region Canik nad Morzem Czarnym. Samsun i okolice stały się w ten sposób pierwszym czarnomorskim portem dynastii. Linia Sivas–Tokat–Kayseri we wnętrzu kraju miała zostać przyłączona dwa tygodnie później, wraz z faktycznym rozpadem państwa Kadı Burhâneddina.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Zajęcie Malatyi", "7cb6ae16"], "d": ["Zajęto Malatyę na granicy mameluckiej — jeden z kroków zaostrzających napięcie z Timurem.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Timur zajął Malatyę, oddał ją Karayülükowi Osmanowi — po odejściu Timura odzyskali ją Dulkadıroğulları", "ad2ce7d8"], "d": ["Bayezid Błyskawica, który zajął Malatyę w 1399, oddał ją Dulkadıroğlu Nasreddinowi Mehmedowi i wrócił do Bursy. Timur, który w 1400 wkroczył do Anatolii, zajął najpierw Sivas i Elbistan, a następnie Malatyę; miasto i okolice splądrowano, a zarząd oddano Karayülükowi Osmanowi, który był przy Timurze. Gdy Timur opuścił region, Malatyą ponownie zawładnęli Dulkadıroğulları; panowanie osmańskie zakończyło się więc jeszcze przed Ankarą.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Układ Süleymana Çelebiego z Bizancjum: zwrot Salonik", "cc503cc2"], "d": ["Süleyman Çelebi, który w czasie Interregnum władał Rumelią, porozumiawszy się z państwami bizantyjskim i łacińskimi, zostawił Bizancjum Saloniki i wybrzeża Morza Czarnego aż po Mesembrię (TDV fetret-devri: układ w Gallipoli, luty 1403) — na mapie İğneada, Rezve i Ahtapolu przechodzą do Bizancjum; Saloniki w tym dniu wychodzą z rąk osmańskich.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Klęska morska pod Gallipoli (Wenecja)", "b71d4d68"], "d": ["Flota wenecka zadała flocie osmańskiej ciężką klęskę pod Gallipoli; wydarzenie ukazało ograniczenia osmańskiej żeglugi we wczesnym okresie.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Powstanie Düzmece Mustafy", "0ec43138"], "d": ["Mustafa Çelebi, podający się za syna Błyskawicy, ogłosił z poparciem Bizancjum sułtanat w Rumelii; Murad II stłumił powstanie w 1422 i kazał stracić rywala.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Oblężenie Stambułu przez Murada II", "4b9d9fba"], "d": ["W odpowiedzi na poparcie Bizancjum dla Düzmece Mustafy Murad II oblegał Stambuł; oblężenie zniesiono, gdy w Anatolii wzniesiono powstanie jego brata Küçük Mustafy.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Oddanie Salonik Wenecji", "bfa6c4a0"], "d": ["Namiestnik bizantyjski pod osmańską presją oddał miasto Wenecji; rozpoczęła się trwająca siedem lat rywalizacja osmańsko-wenecka.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Ponowna aneksja bejlików Anatolii Zachodniej: Menteşe i Aydın", "aca30a48"], "d": ["Dwa bejliki egejskie, odtworzone w czasie Interregnum, zostały ostatecznie przyłączone do ziem osmańskich za Murada II. Według hasła TDV o Menteşeoğulları Murad II zajął prowincję Menteşe w 827 (1424) i kazał uwięzić dwóch braci stojących na czele bejliku. Według hasła o Aydınoğulları beylerbej Anatolii Hamza Bej kazał schwytać Cüneyda Beja, który ponownie wypowiedział posłuszeństwo, i stracić go wraz z rodziną (829/1425–26), a prowincja Aydın przeszła do Osmanów. Joannici, którzy od 1344 trzymali portową twierdzę Izmiru, utracili ją w 1402 na rzecz Timura, a region wrócił pod kontrolę Aydınoğlu; wraz z tą aneksją także ona została przyłączona do Osmanów. Prowincja Teke (Antalya) nie jest przedmiotem tego wpisu: Tekeoğulları zostali zlikwidowani osobno w 1423. Germiyan miał zostać przyłączony w 1429 na mocy testamentu.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Aneksja Germiyanu na mocy testamentu", "9eb86b77"], "d": ["Zmarły bezpotomnie bej Germiyanu Yakub II zostawił swój kraj Osmanom w testamencie — przykład bezwojennej aneksji, który wszedł do podręczników. W tym samym dniu przyłączono także inne miejscowości: Karahisâr-ı Sâhib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Ostateczne zdobycie Salonik", "bc021768"], "d": ["Miasto pod zarządem weneckim zdobyto szturmem; drugi wielki port Rumelii stał się ostatecznie osmański. W tym samym dniu przyłączono także inne miejscowości: Kasandra (Kassandra).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Poddanie Janiny", "ee45cb52"], "d": ["Janina, ośrodek Epiru, poddała się na mocy układu.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Pierwsze zdobycie Smedereva", "c11ca17d"], "d": ["Po trzymiesięcznym oblężeniu zajęto stolicę despotatu serbskiego i Serbię po raz pierwszy anektowano (zostanie zwrócona na mocy układu Edirne–Segedyn z 1444).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Oblężenie Belgradu (nieudane)", "3e05f425"], "d": ["Trwające sześć miesięcy pierwsze wielkie oblężenie Belgradu nie przyniosło skutku; twierdza przez osiemdziesiąt lat pozostała zamkiem blokującym osmańskie natarcie.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Klęska pod Zlatica — „Długa Wyprawa”", "97df1466"], "d": ["Armia, którą Hunyadi w środku zimy wprowadził na Bałkany, minęła Niš i Sofię i dotarła pod Zlaticę; osmańska obrona z trudem się utrzymała. Ta atmosfera klęski przyprowadziła do stołu pokój Edirne–Segedyn.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Pokój Edirne–Segedyn", "0aa4e0de"], "d": ["Dziesięcioletni pokój: despotat serbski zwrócono, Dunaj uznano za granicę. Złamanie traktatu w ciągu miesięcy z podżegania papieskiego doprowadziło do katastrofy pod Warną.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Zwrot Smedereva i twierdz serbskich Serbii", "cda3cf9e"], "d": ["Wprowadzono w życie postanowienie układu Edirne–Segedyn: Murad II zwrócił 15 sierpnia 1444 Đurađowi Brankoviciowi Smederevo wraz z dwudziestoma czterema ważnymi twierdzami i innymi zajętymi ziemiami serbskimi (TDV semendire); Niš (TDV nis), Alacahisar (TDV alacahisar), Şehirköy (TDV sehirkoy) i Prisztina (TDV pristine) także pozostawiono Serbom. Widyń, ponieważ nie był ziemią serbską, nie wszedł do zwrotu — to źródło północno-zachodniej utraty terytorium widocznej na mapie w okolicach zwycięstwa pod Warną; po kilku miesiącach, wraz z klęską pod Warną, układ i tak utracił ważność.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Ukończenie Rumeli Hisarı — „Przecinacz Cieśniny”", "480e8a76"], "d": ["Dzięki twierdzy ukończonej, według źródeł, w nadzwyczaj szybkiej budowie trwającej cztery, pięć miesięcy kontrola nad cieśniną przeszła całkowicie w ręce osmańskie; droga pomocy z Morza Czarnego do Stambułu została zamknięta. Uważa się ją za faktyczny pierwszy krok oblężenia.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Początek oblężenia Stambułu", "8af50742"], "d": ["Armia rozłożyła się przed murami; w trwającym 54 dni oblężeniu olbrzymie działa po raz pierwszy użyto systematycznie przeciw murom stolicy.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Okręty spuszczone drogą lądową do Złotego Rogu", "4f2ba07c"], "d": ["Około 70 okrętów floty, która nie mogła wejść do zamkniętego łańcuchem Złotego Rogu, przeciągnięto po natłuszczonych ślizgach przez wzgórza Galaty i spuszczono w ciągu jednej nocy do Złotego Rogu; obrona została podzielona na dwa fronty.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Zdobycie Aten", "4f0f1bb2"], "d": ["Księstwo Aten dobiegło końca; na Akropolu wciągnięto sztandar osmański. W tym samym dniu przyłączono także inne miejscowości: İstefe (Teby), Livadya.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Aneksja Serbii (upadek Smedereva)", "75fd0a62"], "d": ["Smederevo, stolica serbskiego despotatu, poddało się; Serbia stała się sandżakiem osmańskim.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Zdobycie Morei", "7d5a3c18"], "d": ["Despotat Morei zlikwidowano; półwysep (z wyjątkiem twierdz weneckich) wszedł pod zarząd osmański.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Przyłączenie Synopy", "e03c2739"], "d": ["Candaroğlu poddał Synopę bez walki; otwarto drogę do wyprawy na Trapezunt. W tym samym dniu przyłączono także inne miejscowości: Kastamonu, Bartın, Safranbolu. Hasło TDV o Candaroğulları wymienia także Bolu, Eflani i Tosyę wśród ziem bejliku Candaroğlu anektowanych w 1461; w atlasie te trzy miejscowości są również zapisane od tego dnia jako przechodzące od Candaroğlu do Osmanów.", "4ef62060"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Upadek Królestwa Bośni — wyprawa Fatiha do Bośni", "5362e3f2"], "d": ["Gdy ostatni król Bośni Stjepan Tomašević (1461–1463), ufając poparciu Zachodu, odmówił płacenia daniny, uznano go za pozbawionego statusu władcy zależnego, a armia pod dowództwem sułtana Mehmeda Zdobywcy zlikwidowała Królestwo Bośni w jednej wyprawie. Król został schwytany i stracony, królestwo przestało istnieć, a w regionie utworzono sandżak bośniacki. Jednak upadek królestwa nie jest tym samym co zdobycie Bośni. Zarząd osmański w dolinie istniał już od piętnastu lat — Hodidjed i równinę Saraj zajęto w 1448, a pogranicze Îsâ Beja powstało w samym środku królestwa. Zdobywanie nie zakończyło się też w 1463: Foča w 1465, Livno w 1469, Księstwo Hercegowiny w 1483, banat Srebrenika w 1512, a Jajce i Banja Luka na północy dopiero po Mohaczu, w 1528 — Węgrzy po 1463 utworzyli na północy Bośni banat, który utrzymał się przez sześćdziesiąt pięć lat. W tym dniu bezpośrednio zmieniło właściciela Travnik; Jajce natomiast przeszło w tym czasie nie do Osmanów, lecz do Węgier.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Ostateczna aneksja Karamanu", "f1dcecaa"], "d": ["Ziemie centralne Karamanoğulları przyłączono ostatecznie; spory wewnętrzne trwały aż do lat 70. XV wieku. W tym samym dniu przyłączono także inne miejscowości: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Zdobycie Negroponte (Eğriboz)", "5c97daf3"], "d": ["Padło Negroponte, główna baza Wenecji na Morzu Egejskim.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Aneksja Alanyi, Anamur i Silifke (İçel)", "a0b9d461"], "d": ["Pas przybrzeżny İçel zależny od Karamanoğulları (całe wybrzeże Morza Śródziemnego między Antalyą a Mersin) został przyłączony w wyprawie morskiej Gediga Ahmeda Paszy; Alanya była ważna dzięki strategicznej stoczni z okresu seldżuckiego.", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["Aneksja Nowogrodu przez Moskwę", "bed87170"], "d": ["Wielki książę Iwan III usunął symboliczny dzwon wiecu (wieczy) w Nowogrodzie, zastąpił miejscowych władców własnymi namiestnikami i faktycznie przyłączył miasto do Moskwy; Nowogród przestał być niepodległą republiką. Ziemia nowogrodzka sięgała od Morza Bałtyckiego po Morze Białe i Ural. W atlasie od tego dnia Nowogród jest zapisany jako przechodzący z Republiki Nowogrodzkiej do Moskwy.", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Traktat stambulski — Albania i Szkodra", "b09652f7"], "d": ["Szesnastoletnia wojna osmańsko-wenecka dobiegła końca; Szkodra i wybrzeża Albanii pozostały przy Osmanach. W tym samym dniu przyłączono także inne miejscowości: Limnos, Samos, Bozbaba (Ajios Efstratios).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Lądowanie pod Otranto", "7916b89d"], "d": ["Siły osmańskie, które wylądowały na wybrzeżu Apulii, oblegały i zdobyły twierdzę Otranto; ponieważ do miasta wdarto się walką, część stawiających opór notabli stracono, część wzięto do niewoli. Tradycja kościelna wspomina poległych jako około 800 „męczenników z Otranto”; TDV wiąże zawyżenie tej liczby z propagandą kościelną. Utrzymano jedynie twierdzę na krańcu półwyspu Salento i jej wąskie otoczenie; pozostałe ziemie Królestwa Neapolu na linii Taranto–Brindisi–Lecce nie zostały utracone — ten przyczółek otwarty na Włochy miał trwać rok.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Ewakuacja Otranto", "37371bb0"], "d": ["Po śmierci Mehmeda Zdobywcy (3 maja 1481), gdy garnizon Otranto nie miał już nadziei na posiłki, oddał twierdzę na mocy układu wobec oblężenia prowadzonego przez następcę tronu Neapolu Alfonsa; jedyny osmański przyczółek we Włoszech przepadł więc po roku.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Zdobycie Modon i Koron", "38b608c4"], "d": ["Zdobyto Modon i Koron, „dwoje oczu” Wenecji w Morei.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Zdobycie Durrës", "1f231b98"], "d": ["W czasie wojny osmańsko-weneckiej 1499–1503 siły dowodzone przez Mehmeda Beja zajęły Durrës, ostatni wielki albański port Wenecji na Adriatyku. Po Szkodrze (1479) i Wlorze (1417) wraz z tym zdobyciem pas przybrzeżny Albanii całkowicie znalazł się pod kontrolą osmańską.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Przyłączenie Anatolii Wschodniej", "e0cb8f8f"], "d": ["Po Çaldıranie przyłączono Diyarbakır i okolice; beliki kurdyjskie związano z Osmanami za sprawą İdrîsa-i Bitlisîego.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Zdobycie twierdzy Varadin (Petrovaradin)", "abf392a5"], "d": ["Armia wyruszająca na Mohacz przeszła z Belgradu na ziemie węgierskie; najpierw zdobyto zewnętrzne dzielnice Varadinu, a po czternastodniowym oblężeniu padła też twierdza. Sulejman rozkazał nie palić wsi na drodze, gdyż uważano już je za ziemię osmańską.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Poddanie Budy po Mohaczu — dwaj królowie na tronie węgierskim", "9d3568a0"], "d": ["Po zwycięstwie pod Mohaczem klucze miasta wręczono sułtanowi 11 września 1526 roku, gdy armia osmańska pomaszerowała na Budę; Sulejman jednak nie zatrzymał Budy i wycofał armię. W pozbawionych króla Węgrzech szlachta wybrała dwóch odrębnych królów: 10 listopada 1526 Jánosa Szapolyaiego, 17 grudnia 1526 Habsburga Ferdynanda I. Ferdynand zajął Budę w sierpniu 1527. Osiedlenie się Szapolyaiego w Budzie jako króla pod protektoratem osmańskim nastąpi w wyprawie 1529 (zob. wpis z 1529), a bezpośredni zarząd osmański zostanie ustanowiony w 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["János Szapolyai wybrany królem Węgier — Osmanowie uznali jego królestwo pod warunkiem zależności", "32bc6baf"], "d": ["Na tron węgierski opróżniony śmiercią króla pod Mohaczem część możnych wybrała wojewodę Siedmiogrodu Jánosa Szapolyaiego; Szapolyai został koronowany w Székesfehérvár. Osmanowie, którzy opuścili Budę, aby utrzymać region jako strefę buforową, uznali królestwo Szapolyaiego pod warunkiem, że będzie od nich zależne. Na mapie miejscowości podległe Szapolyaiemu od tego dnia widnieją jako zależne od Osmanów.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Ferdynand I ogłoszony królem Węgier — zachodnie i północne Węgry pod koroną Habsburgów", "b3910a2f"], "d": ["Arcyksiążę Ferdynand Habsburg, powołując się na małżeństwo swojej siostry z Ludwikiem II, zgłosił pretensje do tronu węgierskiego i został ogłoszony królem przez część szlachty. Węgry zostały w ten sposób podzielone między dwóch królów; część zachodnia i północna uznała Ferdynanda. Szlachta chorwacka wybrała go osobno na początku 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Spór dwóch królów: Ostrzyhom pod protektoratem Habsburgów, Segedyn przy Szapolyaim", "da92dee5"], "d": ["Ostrzyhom, przechodzący od 1526 między dwóch królów, znalazł się pod protektoratem Habsburgów po przeniesieniu się arcybiskupa z archiwum i skarbem na północ. Od tego samego roku do 1541 Segedyn pozostał pod władzą Szapolyaiego.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["Mieszkańcy Peczuju przeszli na stronę Szapolyaiego", "3fc4e7f2"], "d": ["Peczuj, który w 1528 otrzymał przywileje od Ferdynanda, wkrótce przeszedł na stronę Szapolyaiego; król János przebywał w mieście przez jakiś czas w 1533. Po upadku Budy w 1541 miasto wróciło na stronę Ferdynanda.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Zdobycie Trypolisu", "8c659986"], "d": ["Zdobyto Trypolis od joannitów; środkowe wybrzeże Afryki Północnej stało się osmańskie. W tym samym dniu przyłączono także inne miejscowości: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Zdobycie Timișoary", "e9fd4995"], "d": ["Zajęto region Banatu i utworzono beylerbeylik Timișoary.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Ostateczne zdobycie Tunisu", "7bbd11bc"], "d": ["Tunis, znajdujący się pod kontrolą hiszpańsko-hafsydzką, przeszedł ostatecznie pod zarząd osmański; linia Afryki Północnej została dopełniona. W tym samym dniu przyłączono także inne miejscowości: Kairouan, Gabès, Sfaks.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Zdobycie Nagykanizsy (Kanije)", "0c7b6aa3"], "d": ["W Długiej Wojnie zdobyto Kanizsę; w następnym roku jej obrona pod wodzą Tiryâkiego Hasana Paszy obrosła legendą.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Początek wyprawy na Uyvar — Fâzıl Ahmed Pasza wyruszył z Edirne przeciw Austrii", "306a86db"], "d": ["Gdy Austria zaatakowała Siedmiogród i zajęła twierdze Székelyhíd i Kolozsvár, Stambuł postanowił podjąć wyprawę przeciw Habsburgom. Wielki wezyr Köprülüzâde Fâzıl Ahmed Pasza wyruszył z Edirne 13 kwietnia 1663 roku. W Belgradzie nadeszła austriacka prośba o pokój, lecz w dwóch rozmowach w Osijeku warunki osmańskie zostały odrzucone. Na naradzie w Budzie celem wyznaczono Uyvar.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Zdobycie Uyvaru (Nové Zámky)", "ce289470"], "d": ["Zdobyto Uyvar, kluczową twierdzę Węgier Północnych; powiedzenie „silny jak Turek pod Uyvarem” przeszło do języków europejskich. Po Uyvarze Nitra i Léva poddały się po krótkim oporze; obie odebrał w 1664 wiosną De Souches.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Odzyskanie Morei", "9b6460f1"], "d": ["Morea, oddana Wenecji w Karłowicach, została odzyskana jedną wyprawą. W tym samym dniu przyłączono także inne miejscowości: Balyabadra (Patras), Lepanto.", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Druga utrata Belgradu — oblężenie księcia Eugeniusza", "6a194354"], "d": ["Po klęsce pod Varadinem i utracie Timișoary książę Eugeniusz oblegał Belgrad; gdy armia odsieczy przybyła ratować miasto została również rozbita, twierdza się poddała. Miasto odzyskane w 1690 po Karłowicach zostało w ten sposób ponownie utracone, a linia obrony Dunaju się załamała. Belgrad miał zostać odzyskany dopiero po dwudziestu dwóch latach, traktatem belgradzkim z 1739. W tym samym dniu utracono także inne miejscowości: Smederevo. Atlas zapisuje ponadto okolice Hisarcık (Grocka) i Jagodiny tego dnia po stronie Habsburgów (dzień regionu; dzień na poziomie miejscowości nie występuje w źródle, przybliżenie z deklaracją); Mehádia przechodzi natomiast do Habsburgów z datą 27 sierpnia 1717 (Bánlaky 0019/1715).", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Upadek Oczakowa", "90a67a6c"], "d": ["Oczaków, kluczowa twierdza na północy Morza Czarnego, wpadł w ręce Rosji w krwawym szturmie; ludność miasta wycięto.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Traktat bukareszteński — utrata Besarabii", "932da4d6"], "d": ["Na mocy traktatu kończącego wojnę rosyjską 1806–1812 ziemie na wschód od Prutu (Besarabię) oddano Rosji. W tym samym dniu utracono także inne miejscowości: Akerman, Kilia, Chocim, Bender, Izmaił. Atlas uznaje ponadto za przekazane Rosji w tym samym dniu Kiszyniów (Chișinău), Bălți, Cahul i Orhei w Besarabii od Mołdawii (wasala osmańskiego). Soroca również przechodzi do Rosji tego samego dnia.", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Traktat adrianopolski", "b3a8fe4c"], "d": ["Pod koniec wojny, w której armia rosyjska wkroczyła do Edirne, utracono deltę Dunaju; faktycznie uznano autonomię/niepodległość Grecji. W tym samym dniu utracono także inne miejscowości: Braiła, Anapa, Achalciche. Choć traktat zwrócił ziemie, nie zakończył okupacji od razu: Wołoszczyzna i Mołdawia oraz Silistra pozostały jako zastaw pod zarządem rosyjskim do spłaty odszkodowania wojennego — dlatego na mapie miejscowości te widnieją jako okupowane także po 1829.", "d09a34fb"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Ferman autonomii dla Serbii — dziedziczne księstwo i warunek garnizonów", "6a5d901d"], "d": ["Hatt-ı hümâyun wydany na mocy postanowienia traktatu adrianopolskiego dotyczącego Serbii uznał Miloša Obrenovicia za księcia dziedzicznego i uczynił Serbię autonomicznym księstwem, swobodnym w sprawach wewnętrznych, a na zewnątrz zależnym od Osmanów. Postanowienia: godność księcia miała przechodzić z ojca na syna, roczny podatek miał być płacony ryczałtem, serbska skupszczyna miała ustanowić własny zarząd wewnętrzny, a kościół miał być autonomiczny; w zamian w twierdzach Belgrad, Smederevo, Šabac, Bogurdelen i Fethülislâm miały pozostać garnizony osmańskie. Ta podwójna struktura trwała do wycofania garnizonów w 1867. Na mapie miasto Belgrad przyłącza się w tym dniu do autonomicznej Serbii; twierdza Kalemegdan do 1867 jest pokazywana z garnizonem osmańskim.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Oddanie Cypru pod zarząd brytyjski", "423da3ee"], "d": ["W zamian za sojusz wobec zagrożenia rosyjskiego zarząd nad Cyprem przekazano Anglii; prawnie pozostał on ziemią osmańską. W tym samym dniu utracono także inne miejscowości: Nikozja, Famagusta, Kyrenia, Limassol, Larnaka (Tuzla), Pafos, Morphou (Güzelyurt), Akrotiri, Episkopi, Dhekelia; czyli cała wyspa.", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Oddanie Tesalii Grecji", "ac614d24"], "d": ["Zgodnie z postanowieniami Kongresu Berlińskiego Tesalię i okolice Narda przekazano Grecji. W tym samym dniu utracono także inne miejscowości: Arta, Yenişehir (Larissa), Tırhala, İzdin (Lamia). Wraz z tym przekazaniem do Grecji przeszły Volos, Kalambaka i Karditsa (Tesalia).", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Przyłączenie Rumelii Wschodniej do Bułgarii", "ee43f137"], "d": ["Autonomiczną prowincję Rumelii Wschodniej przyłączono do Bułgarii w wyniku zamachu; Wysoka Porta pogodziła się z faktem dokonanym. Wraz z tym zjednoczeniem cała Rumelia Wschodnia (Stara Zagora, Tatarpazarcığı, İslimye, Hasköy, Burgas, Aydos, Elhova) przeszła do Księstwa Bułgarii.", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Bitwa pod Domokos", "9c6f29a5"], "d": ["W wojnie osmańsko-greckiej 1897 armia odniosła pod Domokos decydujące zwycięstwo; wskutek presji dyplomatycznej zdobycze terytorialne pozostały ograniczone.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Autonomia Krety", "2e764881"], "d": ["Choć wojna osmańsko-grecka zakończyła się zwycięstwem osmańskim, Anglia, Rosja, Francja i Włochy ogłosiły 18 grudnia 1897 autonomię Krety; wyspa miała być neutralną i autonomiczną prowincją pod zwierzchnictwem osmańskim. Po 6 listopada 1898 w Kandii i Kisamos nie podnoszono już flagi tureckiej; gdy syn króla Grecji, książę Jerzy, objął 22 grudnia 1898 urząd nadzwyczajnego komisarza, Kreta faktycznie wyszła spod zarządu osmańskiego (formalnie oddzielona w 1913). W tym samym dniu utracono także inne miejscowości: Kandia (Kreta), Chania.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Niepodległość Bułgarii i aneksja Bośni", "393feaa4"], "d": ["W zamęcie monarchii konstytucyjnej Bułgaria ogłosiła niepodległość, a Austro-Węgry anektowały Bośnię i Hercegowinę. Dzięki tej proklamacji wszystkie ziemie Księstwa Bułgarii (Warna, Şumnu, Ruse, Burgas, İslimye i in.) stały się niepodległym Królestwem Bułgarii.", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Odzyskanie Edirne", "536e5599"], "d": ["W II wojnie bałkańskiej armia, przekraczając Maricę, odzyskała Edirne bez walki. W tym samym dniu przyłączono także inne miejscowości: Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Zwycięstwo pod Kut al-Amara", "98b972bc"], "d": ["Dowódca oblężonej w Kut dywizji brytyjskiej poddał się wraz z 13 tysiącami żołnierzy — jedno z największych zwycięstw osmańskich w I wojnie światowej.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Utrata Bagdadu", "2c18a816"], "d": ["383-letni osmański Bagdad przeszedł w ręce armii brytyjskiej. W tym samym dniu utracono także inne miejscowości: Karbala.", "4add66da"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Utrata Jerozolimy", "94067617"], "d": ["401-letnia osmańska Jerozolima została oddana bez obrony.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Utrata Damaszku", "ed177b68"], "d": ["Wskutek załamania frontu palestyńskiego Damaszek opuszczono; czterowiekowe rządy osmańskie w Syrii dobiegły końca. W tym samym dniu utracono także inne miejscowości: Hama, Hims.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Poddanie Medyny", "76b505f6"], "d": ["72 dni po rozejmie opór „Pustynnego Tygrysa” Fahreddina Paszy zakończono z woli sułtana; ostatni oddział osmański w Hidżazie złożył broń.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Okupacja Izmiru", "e32e5e77"], "d": ["Armia grecka wylądowała w Izmirze; opór rozpoczęty od pierwszego strzału zapalił lont Walki Narodowej. Aydın został natomiast zajęty 27 maja 1919 (osobny wpis).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Oficjalna okupacja Stambułu", "a8e98ada"], "d": ["Siły Ententy oficjalnie zajęły Stambuł, rozwiązano Meclis-i Meb'ûsan; posłowie udali się do Ankary.", "09ed005b"]},
"OLAYLAR_EK:1921-10-13:0":{"b": ["Traktat w Karsie", "bb32d4e0"], "d": ["Między Wielkim Zgromadzeniem Narodowym a republikami kaukaskimi wytyczono wschodnią granicę w dzisiejszym kształcie.", "fe736259"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["Zajęcie emiratu Hail przez siły saudyjsko-wahhabickie — zarząd w rękach rodu Ibn Ali z rodu Abde", "2d29ceb9"], "d": ["Gdy siły Pierwszego Państwa Saudyjskiego zajęły emirat Hail, zarząd miasta znajdował się w rękach rodu Ibn Ali z rodu Abde plemienia Szammar. Ród ten rządził Hailem do 1835, aż Abdullah b. Raszid objął emirat; dynastia Raszydów powstała dopiero w tej dacie. W atlasie Hail do tej pory figurowało jako bezpańskie aż do 1836, tymczasem źródło podaje z imienia emira miasta w 1820.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["Przejście wysp Kvarner do Królestwa Włoch Napoleona, a Zatoki Kotorskiej pod zarząd rosyjski", "c5e411c8"], "d": ["Po traktacie w Pressburgu wyspy Kvarner zostały — w odróżnieniu od Dalmacji — związane nie bezpośrednio z Francją, lecz z Królestwem Włoch Napoleona; do Prowincji Iliryjskich weszły dopiero w 1809. W Zatoce Kotorskiej zarząd austriacki się skończył, a w latach 1806–1807 ustanowiono zarząd rosyjski; Zatoka przeszła do Francji dopiero w 1807. Tych dwóch rozróżnień nie da się ująć w jedno okno atlasu „Francja”.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["Przejście Dalmacji pod zarząd francuski — wprowadzenie w życie traktatu w Pressburgu (Pojun)", "00bfe4f6"], "d": ["Traktat w Pressburgu (Bratysława) z 26 grudnia 1805 zmusił Austrię do zrzeczenia się Istrii, Dalmacji i wszystkich wysp Adriatyku. Francja faktycznie przejęła zarząd w lutym 1806; Zadar pozostał ośrodkiem generalnego prowizora, a w latach 1806–1810 funkcję tę pełnił Wenecjanin Vicenzo Dandolo. Dalmację przyłączono do Prowincji Iliryjskich po traktacie w Schönbrunn z 1809. W ten sposób pierwszy zarząd austriacki trwający od 1797 się skończył — w atlasie ten okres do tej pory figurował jako nieprzerwanie austriacki.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["Odzyskanie przez Austrię Prowincji Iliryjskich i Dalmacji — koniec zarządu Napoleona", "1b2ac942"], "d": ["Pod koniec 1813 oddziały habsburskie odzyskały region na południe od Sawy i ponownie ustanowiono dawną organizację graniczną; armia austriacka weszła do Istrii w październiku 1813. Karlovac od tej daty stał się częścią Królestwa Iliryjskiego Austrii. Okres zarządu francuskiego w Dalmacji także zamknął się w 1813. Przynależność regionu do Austrii została oficjalnie potwierdzona postanowieniami pokoju paryskiego z 1814 i Kongresu Wiedeńskiego z 1815. W tej akcji Villach, Tarvisio, Gorycja, Gradisca i Pula (Prowincje Iliryjskie) wróciły pod koniec 1813 do Austrii.", "bf1e49a8"]},
"OLAYLAR_MISIR1801:1801-05-14:0":{"b": ["Odzyskanie Damietty od Francuzów — opuszczenie twierdzy Lesbe", "06b1e7b0"], "d": ["Do Damietty wysłano oddział z armii wielkiego wezyra pod dowództwem İbrahima Paszy. 14 maja rano, gdy szykowano szturm na twierdzę Lesbe chroniącą Damiettę, stwierdzono, że twierdzę opuszczono, a garnizon się wycofał; zajęto także dwie podległe jej małe twierdze. Damietta została drugim miastem u ujścia Nilu, które wyszło spod kontroli francuskiej po Rosetcie, która padła w kwietniu.", "2eb4936c"]},
"OLAYLAR_MISIR1801:1801-06-27:0":{"b": ["Przejęcie Kairu od Francuzów — kapitulacja Belliarda", "7a11bb5e"], "d": ["W czasie wspólnej operacji osmańskich i angielskich sił w Egipcie dowódca sił francuskich w Kairze generał Belliard podpisał kapitulację. Wraz z Kairem spod kontroli francuskiej wyszedł także Suez, zajęty przez Francuzów w listopadzie 1798 roku. Zakończenie okupacji miało zostać dopełnione dwa miesiące później w Aleksandrii, a ewakuacja z kraju miała trwać do października.", "e8dac3f4"]},
"OLAYLAR_MISIR1801:1801-08-31:0":{"b": ["Przejęcie Aleksandrii od Francuzów — kapitulacja Menou", "cd50663c"], "d": ["Naczelny dowódca Armii Wschodu generał Menou został 17 sierpnia oblężony w Aleksandrii; 21 sierpnia Anglicy zajęli położoną pod miastem twierdzę Marabout, a 31 sierpnia Menou podpisał kapitulację armii. Powrót wojsk francuskich do Francji rozpoczął się 2 września. Tak okupacja, która zaczęła się lądowaniem w Aleksandrii w czerwcu 1798 roku, zakończyła się w mieście, w którym się zaczęła.", "22e807c1"]},
"OLAYLAR_ORTADOGU_0919:1801-01-01:0":{"b": ["Plemiona okolic Taifu weszły w strefę wpływów wahhabitów — Turaba i Churma oderwały się od Szarifatu Mekki", "d3b644be"], "d": ["Plemiona wokół Taifu, podległe szarifowi Mekki Galibowi, weszły w 1801 roku w strefę wpływów wahhabitów; emir Dirijji oddał je pod zarząd beduińskiego szejka Osmana al-Mudajfiego, szwagra i wroga szarifa. Oazy Turaba i Churma na wschodzie również przeszły w tym pasie na stronę saudyjską. Było to zapowiedzią zajęcia przez wahhabitów Taifu w lutym 1803 roku, a następnie Mekki.", "4fe448d3"]},
"OLAYLAR_ORTADOGU_0919:1816-01-01:0":{"b": ["Garnizony egipskie wycofały się z Turaby, Biszy i Ranji w południowym Hidżazie", "72b87aa1"], "d": ["W miesiącach po pogodzeniu się Tosuna Paszy z wahhabitami i jego powrocie do Kairu w listopadzie 1815 roku w południowym Hidżazie wybuchły zamieszki; garnizony Kavalalı Mehmeda Alego Paszy musiały wycofać się z Biszy, Ranji i Turaby. Wyjazd İbrahima Paszy z Kairu w sierpniu 1816 roku na nową wyprawę nastąpił po tym wycofaniu. Kto rządził Turabą aż do upadku Dirijji (1818), nie jest zapisane w źródle.", "90e76189"]},
"OLAYLAR_ORTADOGU_0919:1819-08-13:0":{"b": ["Garnizon egipski wycofał się z Sulajmijji w Charadż i dotarł do Manfuhy — południe Nadżdu bez władzy", "2743f70d"], "d": ["Egipski posterunek, który İbrahim Pasza po zniszczeniu Dirijji umieścił w Sulajmijji w Charadż, na rozkaz wycofania Paszy, zanim wyruszył, kazał na uczcie zabić czterech szejków Dilam i został oblężony przez beduinów. Uratowany garnizon dotarł 13 sierpnia 1819 roku do Manfuhy i rozpoczął marsz do Kasimu. Na południu Nadżdu nie pozostała władza centralna; próby rodziny Saudów przez długi czas, do 1824 roku, nie przyniosły skutku.", "fc53fbd1"]},
"OLAYLAR_P0043A:1456-01-01:0":{"b": ["Şehirköy wrócił pod zwierzchnictwo osmańskie — śmierć Đurđa Brankovicia", "e37156d1"], "d": ["Şehirköy, zajęty w 1443 roku przez armię krzyżowców i oddany Serbom przez Murada II po Układzie Edirne-Segedyn z 1444 roku, wrócił w 1456 roku wraz ze śmiercią despoty Serbii Đurđa Brankovicia pod zwierzchnictwo osmańskie. W tym samym roku i z tego samego powodu także Niš ostatecznie wszedł pod rządy osmańskie; linia doliny Nišavy otwierająca drogę do Sofii została w ten sposób dopełniona. Układ podpisano na dziesięć lat, a po Warnie (1444) i drugim Kosowie (1448) żywot Despotatu trwał tylko tyle, ile życie Brankovicia.", "4b6ec617"]},
"OLAYLAR_P0043B:1514-03-20:0":{"b": ["Selim Groźny wyruszył z Edirne na wyprawę czałdyrańską", "1f7921f7"], "d": ["Selim Groźny, pozostawiwszy w Stambule jako zastępcę syna Şehzadego Sulejmana z Manisy, wyruszył z Edirne na wyprawę przeciw Państwu Safawidów. Armia, przechodząc przez Anatolię linią Sivas-Erzincan-Erzurum, miała pod koniec sierpnia spotkać się z siłami szacha Isma'ila pod Çaldıranem.", "430f5ccc"]},
"OLAYLAR_P0043KIRIM:1526-01-01:0":{"b": ["Kızıkermen (Gazi Kerman) i prawy brzeg Dniepru weszły pod bezpośrednią kontrolę osmańską", "56a28224"], "d": ["Twierdza Kızıkermen i prawy brzeg Dniepru, od połowy XV wieku w rękach Chanatu Krymskiego, weszły w tej dacie pod bezpośrednią kontrolę Państwa Osmańskiego; twierdza przekształciła się w osmański wysunięty posterunek na północnym krańcu stepu. W odróżnieniu od ziem Chanatu Krymskiego wokół Bakczysaraju i Or Kapı zarząd Kızıkermenu należał bezpośrednio do Osmanów.", "a0eaba40"]},
"OLAYLAR_P0043KIRIM:1776-12-03:0":{"b": ["Prozorowski zajął Or Kapı — siły rosyjskie pozostały w Orkapı do aneksji", "afdfe804"], "d": ["Gdy generał Prozorowski, maszerujący, by osadzić Şahina Gireja na tronie krymskim, dotarł do linii Perekopu, Devlet Giray, kajmakam i Tatarzy wycofali się z miasta; Prozorowski zajął twierdzę Or i linię Perekopu bez walki. Rosjanie osiedlili się w Or Kapı i pozostali tam do aneksji Krymu w 1783 roku.", "2c53b49b"]},
"OLAYLAR_P0043KIRIM:1791-07-26:0":{"b": ["Zajęcie Anapy przez Rosjan (trzecie oblężenie)", "e6a7d6d5"], "d": ["Twierdza Anapa, zbudowana w 1781 roku pod zarządem Ferah Alego Paszy, była w czasie wojny oblegana trzykrotnie przez Rosjan; w trzecim oblężeniu została zajęta 26 lipca 1791 roku. Zajęcie było tymczasowe — ponieważ pokojem w Jassach (1792) przyjęto dawne granice na Kaukazie, twierdzę zwrócono Państwu Osmańskiemu.", "6f3b16fa"]},
"OLAYLAR_P0043KIRIM:1828-06-24:0":{"b": ["Poddanie Anapy przez Osmana Paszę Rosjanom", "3ccbdd1d"], "d": ["W początkowej fazie wojny osmańsko-rosyjskiej 1828-29 Anapa została oblężona, a siły osmańskie w twierdzy pod dowództwem Osmana Paszy poddały się Rosjanom 24 czerwca 1828 roku. Tym razem poddanie było trwałe: Traktatem Edirneńskim podpisanym w następnym roku (14 września 1829) Anapa i Kaukaz formalnie wyszły spod zwierzchnictwa osmańskiego.", "d49b4078"]},
"OLAYLAR_P0044:1556-01-01:0":{"b": ["Turgut Reis został beylerbeyem Trypolisu — ejalet rozszerzył się na wschodzie o Tobruk i Dernę", "160fa43c"], "d": ["Po zdobyciu Trypolisu w 1551 roku Turgut Reis przybył do Trypolisu z tytułem beylerbeya w Dżumada I 963 (marzec 1556). W czasie dziewięcioletniego namiestnictwa zabiegał o rozbudowę i umocnienie ejaletu, rozciągnął zarząd osmański na południu aż do Fezzanu i rozszerzając granice na wschód, zajął Tobruk i Dernę na wybrzeżu Barki. Ejalet Trypolisu objął w ten sposób pas wybrzeża sięgający aż do granicy z Egiptem.", "44cf4583"]},
"OLAYLAR_P0044:1556-01-01:1":{"b": ["Carstwo Moskiewskie zajęło Astrachań — dolna Wołga pod kontrolą rosyjską", "d02abd83"], "d": ["Carstwo Moskiewskie zajęło w 1556 roku także Astrachań, dokonując, jak to ujmuje TDV, „ruchu o bardzo ważnych skutkach na przyszłość”; wraz z zajęciem Chanatu Astrachańskiego dolna Wołga weszła pod kontrolę rosyjską. Chan Krymski Devlet Giray chciał zapobiec tym zajęciom, lecz mu się nie udało. Osmanowie odpowiedzieli na ten rozwój wyprawą astrachańską w 1569 roku; lecz nie odniósłszy sukcesu w kontroli regionu dolnej Wołgi, walkę z Carstwem Moskiewskim pozostawili chanowi krymskiemu.", "7e08ba29"]},
"OLAYLAR_P0044:1556-07-16:0":{"b": ["Zdobycie Kostajnicy i Novi — dwie twierdze linii Uny", "2093e452"], "d": ["Kostajnicy, oblężonej latem 1556 roku przez Malkoç Beja, broniło kapitan Pankracije Lusthaller z ponad sześćdziesięcioma żołnierzami; twierdza została poddana zaledwie dzień po rozpoczęciu oblężenia, 16 lipca, a Lusthallera oskarżono o sprzedanie twierdzy. Wkrótce zajęto i spalono także Novi; w ten sposób dwie najważniejsze twierdze nad Uną wpadły jednym ruchem w ręce osmańskie. W tym samym roku w Wiedniu utworzono Nadworną Radę Wojenną (Hofkriegsrat), która miała kierować z centrum obroną marchii.", "b985cbdf"]},
"OLAYLAR_P0044:1574-01-01:0":{"b": ["Maku przeszło do Osmanów — zlecenie Mahmudiemu İvazowi Bejowi budowy twierdzy", "5932ad38"], "d": ["W 1574 roku Państwo Osmańskie zleciło wodzowi plemienia kurdyjskiego Mahmudi İvazowi Bejowi zajęcie Maku od Irańczyków i zbudowanie tam twierdzy. Ta twierdza na wschodnim krańcu ejaletu Wan zajęła ważne miejsce w wydarzeniach zachodzących w regionie w okresie osmańskim.", "bd663d7c"]},
"OLAYLAR_P0044:1840-01-01:0":{"b": ["Wydano pierwszy osmański papierowy pieniądz (kâime)", "d2e5e192"], "d": ["W pierwszych latach Tanzimatu, w poszukiwaniu dochodów dla skarbu, za wnioskiem Ârifa Hikmeta Beja, późniejszego şeyhülislama, przyjęto kâime, rozwiniętą formę systemu esham. Pierwsze kâime o łącznej wartości 160 000 lir (32 000 kes), z powodu pilnej potrzeby pieniędzy, wydano nie czekając na druk, odręcznie, za ministra finansów Sâiba Paszy, prawdopodobnie w czerwcu 1840 roku. Te papiery, mające moc gotówki, miały osiem lat obiegu i oprocentowanie 12,5% rocznie; nie miały pokrycia, tylko na ich odsetki wyznaczono dochód z celnicy stambulskiej. Ludność, nieprzyzwyczajona, przyjęła ten pieniądz niechętnie, a odręczne kâime wkrótce stały się celem fałszerzy.", "1f5f905c"]},
"OLAYLAR_P0047:1511-08-10:0":{"b": ["Zajęcie Malakki przez Portugalczyków", "e1556746"], "d": ["Malakka, założona w latach dziewięćdziesiątych XIV wieku, stała się najruchliwszym portem regionu w handlu morskim między Chinami, Indiami i Zachodem oraz ośrodkiem Sułtanatu Malakki, a tym samym głównym ogniskiem rozprzestrzeniania się islamu na okoliczne wyspy. Portugalczyk Afonso de Albuquerque zajął miasto 10 sierpnia 1511 roku; miasto złupiono, jego meczety, groby dynastii i inne kamienne budowle zburzono, by użyć kamieni do budowy twierdzy. Malakka pod rządami portugalskimi nie zdołała utrzymać dawnej przewagi handlowej; kupcy muzułmańscy zwrócili się ku portowi Sułtanatu Aceh na Sumatrze. Wskutek ataków Portugalczyków osiadłych w Malakce na Aceh sułtan Aceh Alaeddin Riayat Szah poprosił w 1565 roku o pomoc Sulejmana Prawodawcę.", "bfb60150"]},
"OLAYLAR_P0048:1592-01-01:0":{"b": ["Władca Luristanu Szahverdi złożył hołd szachowi Abbasowi", "85791f94"], "d": ["Władca Luristanu Szahverdi, który w 1589 roku poddał się Osmanom i stał się zależny od beylerbeya Bagdadu, musiał według relacji historyka safawidzkiego İskendera Beja Münşîego w roku 1000 (1591-92) wyrazić wierność koronie Safawidów. To samo źródło pisze, że w tych latach chodził on tam i z powrotem między dwiema stronami, niepokoił namiestników Hamadanu, robiąc napady na Burudżird, a w 1002 (1593-94) szach Abbas zajął Churramabad i mianował w mieście namiestnika. TDV İslâm Ansiklopedisi natomiast umieszcza pełne podporządkowanie Safawidom Luristanu, związanego z rządami osmańskimi układem stambulskim z 1590 roku, w roku 1603. Obie tradycje podają różne daty; ten zapis przedstawia deklarację wierności w tradycji safawidzkiej, zapis z 1603 roku pokazuje ostateczną utratę. Na mapie ten zapis nie zmienia właściciela: Luristan do 1603 roku widnieje po stronie osmańskiej.", "d15b2c77"]},
"OLAYLAR_P0048:1603-01-01:0":{"b": ["Ostateczne przejście Luristanu do Safawidów", "4c5cf67b"], "d": ["Luristan, związany z rządami osmańskimi układem stambulskim (Ferhad Paszy) z 1590 roku, został w 1603 roku w pełni podporządkowany Safawidom przez szacha Abbasa I. Historyk safawidzki İskender Bej Münşî pisze jednak, że Churramabad został wcześniej, w 1002 (1593-94), zajęty przez szacha Abbasa i mianowano w nim namiestnika safawidzkiego; ta różnica między obiema tradycjami nie została rozstrzygnięta. W tym samym roku osmańska twierdza Nihawend na północ od Luristanu wpadła w ręce szacha Abbasa; namiestnik Hamadanu Hasan Chan zrównał twierdzę z ziemią.", "3e110da7"]},
"OLAYLAR_P0049:1303-09-01:0":{"b": ["Kompania Katalońska weszła w służbę Bizancjum — początek wyprawy anatolijskiej", "6623e7db"], "d": ["Cesarstwo Bizantyńskie, tracące ziemie na rzecz beylików tureckich w zachodniej Anatolii, przyjęło w służbę jako żołnierzy najemnych około 6500-osobowy oddział Katalończyków pod dowództwem Rogera de Flora. Według hasła Bizans w TDV oddział przybył na pomoc cesarstwu w 1303 roku i w następnym roku uratował Alaşehir oblegany przez Germiyanoğulları. Jednak kompania wkrótce zaczęła łupić miejsca, przez które przechodziła; Bizancjum przeprawiło ją do Tracji, a w 1305 roku kazało zabić Rogera de Flora.", "87b98a94"]},
"OLAYLAR_P0049:1538-11-27:0":{"b": ["Władca Hadramautu i Szihr uznał zwierzchnictwo osmańskie — powrót Hadıma Sulejmana Paszy z wyprawy indyjskiej", "b5cb9363"], "d": ["Hadım Sulejman Pasza, wracający spod oblężenia Diu, zawinął 27 listopada 1538 roku do portu Szihr; gdy władca Hadramautu i Szihr przyjął zwierzchnictwo osmańskie, przeszedł do Adenu. Hadramaut został zorganizowany jako sandżak podległy Jemenowi, lecz zarząd w regionie nadal trzymali wodzowie plemienia Kasiri. Ta zależność trwała do wycofania się Osmanów z Jemenu w 1635 roku.", "cff04bbb"]},
"OLAYLAR_P0049:1555-05-29:0":{"b": ["Beylik Megrelii (Dadyan) pozostawiony w osmańskiej strefie wpływów", "ea54e8ea"], "d": ["Postanowieniami Traktatu z Amasyi dzielącymi Gruzję beylik Dadyan (Megrelia i Swanetia) w Gruzji Zachodniej został pozostawiony w osmańskiej strefie wpływów wraz z Imeretią i Gurieli. Na mapie ośrodek Megrelii, Zugdidi, widnieje od tego dnia jako beylik zależny od Osmanów; faktyczne złożenie hołdu miało nastąpić w 1578 roku.", "1724aa10"]},
"OLAYLAR_P0049:1578-08-09:0":{"b": ["Wejście atabegatu Achalciche pod rządy osmańskie — Altunkale, Hırtıs i Ahılkelek", "024bb326"], "d": ["Zaraz po pokonaniu przez Lalę Mustafę Paszę przednich sił safawidzkich pod Çıldırem ziemie będące w rękach gruzińskich atabegów także przeszły pod rządy osmańskie. Dedis Imedi i jego synowie, trzymający Altunkale i okolice, złożyli swą uległość; sandżakbej Ardahanu zajął Çıldır i Tümük, inne oddziały osmańskie Hırtıs i Ahılkelek. Menuçihrowi i jego bratu pozostawiono po jednym sandżaku, resztę ziem atabegatu podporządkowano bezpośredniemu zarządowi. Achalciche miało stać się potem ośrodkiem nowo utworzonego ejaletu Çıldır; Menuçihr, który przybył do Stambułu, przyjął islam i otrzymał imię Mustafa, miał 1 lipca 1579 roku zostać mianowany na czele tego ejaletu.", "23731679"]},
"OLAYLAR_P0049:1579-07-26:0":{"b": ["Kılıç Ali Pasza zbudował twierdzę Faş (Poti) — baza osmańska u ujścia Rioni", "f729ba95"], "d": ["Kapudan paşa Kılıç Ali Pasza zbudował 26 lipca 1579 roku twierdzę Faş w miejscu, gdzie rzeka Rioni (Faş) wpada do Morza Czarnego.", "13606f9d"]},
"OLAYLAR_P0049:1587-01-01:0":{"b": ["Utworzono ejalet Gori — bezpośredni zarząd osmański na zachodzie Kartlii", "9a7c8bc5"], "d": ["W 1578 roku bejowie gruzińscy w regionach Gori i Muhran poddali się Osmanom. W 1587 roku na zachodzie Kartlii utworzono ejalet Gori, a region podporządkowano bezpośredniemu zarządowi osmańskiemu. Twierdza Gori, utracona w czasie buntu Gruzina Simona, została odzyskana w 1601 roku; zarząd osmański zakończył się w 1603 roku wraz z wyprawą szacha Abbasa.", "7ee17c2b"]},
"OLAYLAR_P0049:1595-01-01:0":{"b": ["Napady Michała Walecznego na twierdze naddunajskie — spalony Rusczuk, zajęta Braiła, złupiona Silistra", "d0b83f6a"], "d": ["Wojewoda Wołoszczyzny Michał Waleczny, który przystąpił do Świętej Ligi, uderzył zimą 1594-95 na twierdze i miasta nad Dunajem będące pod bezpośrednim zarządem osmańskim. Według hasła Rusçuk w TDV w lutym 1595 roku, choć nie zdobył twierdzy, zajął i spalił miasto. Według hasła İbrâil zdobył İbrâil na lewym brzegu Dunaju i miasto pozostawało w jego rękach do 1601 roku; hasło Murad III pisze też, że armia wołoska spaliła twierdzę İbrâil i dotarła aż do Silistry. Według zapisu tahrir wspomnianego w haśle Silistre armia wołoska przekroczyła Dunaj wiosną 1595 roku i złupiła Silistrę; twierdza miasta została zniszczona i długo była nieużywana. Tego samego lata Koca Sinan Pasza miał ruszyć na wyprawę na Wołoszczyznę.", "c115852f"]},
"OLAYLAR_P0049:1603-01-01:0":{"b": ["Szach Abbas odzyskał Tyflis — koniec rządów osmańskich w Kartlii i Kachetii", "a6995ea8"], "d": ["Szach Abbas I odzyskał w 1603 roku Tyflis od Osmanów i ogłosił Kartlię chanatem; w Kachetii również ustanowiono zarząd safawidzki. Rządy osmańskie we Wschodniej Gruzji, rozpoczęte wyprawą Lali Mustafy Paszy w 1578 roku, dobiegły w ten sposób końca; Tyflis miał ponownie wpaść w ręce osmańskie dopiero w 1723 roku.", "e37dcbfc"]},
"OLAYLAR_P0049:1640-01-01:0":{"b": ["Twierdza Faş (Poti) zburzona przez siły Imeretii, Gurii i Megrelii", "3c3d4ed7"], "d": ["Twierdza Faş została w 1640 roku zrównana z ziemią przez siły Imeretii z udziałem książąt Gurii i Megrelii. Obecność osmańska u ujścia Rioni została przerwana do ponownego założenia twierdzy w 1724 roku.", "2bb31f58"]},
"OLAYLAR_P0049:1711-04-09:0":{"b": ["Rozpoczęła się Wyprawa Pruth — armia wyruszyła ze Stambułu w wojnie osmańsko-rosyjskiej 1710-1711", "3161364b"], "d": ["Napaść Rosji na ziemie osmańskie, niedotrzymanie przez cara Piotra postanowień Traktatu Stambulskiego z 1700 roku oraz podszepty chana krymskiego Devleta Gireja doprowadziły Ahmeda III do wypowiedzenia wojny Rosji. Według hasła III. Ahmed w TDV ta wojna, później nazywana Wyprawą Pruth, faktycznie rozpoczęła się wyruszeniem armii osmańskiej ze Stambułu 9 kwietnia 1711 roku. Armia pod dowództwem Baltacıego Mehmeda Paszy, połączywszy się z siłami krymskimi, posuwała się ku rzece Prut; wyprawa miała zakończyć się w lipcu przyparciem armii rosyjskiej nad Prutem.", "49618c54"]},
"OLAYLAR_P0049:1724-03-01:0":{"b": ["Rozpoczęto odbudowę twierdzy Faş (Poti)", "0afbc4b0"], "d": ["Zgodnie z decyzją z 23 grudnia 1723 roku odbudowę zniszczonej twierdzy Faş rozpoczęto w marcu 1724 roku; budowę ukończono w 1729 roku.", "e9e6b3d8"]},
"OLAYLAR_P0049:1724-05-06:0":{"b": ["Region Choj, Kapan i Karadağ ponownie przeszedł pod rządy osmańskie", "c52c94d1"], "d": ["W czasie wyprawy irańskiej rozpoczętej w 1723 roku Choj oraz region Kapan i Karadağ przeszły 6 maja 1724 roku ponownie pod rządy osmańskie i w 1728 roku zostały zapisane w osmańskim rejestrze tahrir. Atlas uznaje, że także Kotur, położony 40 km na południowy zachód od Choju, przeszedł tego dnia od Safawidów do Osmanów (łańcuch przejęty od Choju: Uluerler 2015, Turkish Studies 10/5, s. 6; dnia specyficznego dla Koturu brak w źródle — deklarowane przybliżenie).", "eb5141eb"]},
"OLAYLAR_P0049:1733-08-17:0":{"b": ["Nadir wszedł do Szemachy — ośrodek Szirwanu wyszedł spod rządów osmańskich", "778a4988"], "d": ["Do Szemachy, która przypadła Osmanom wraz z centralną częścią Szirwanu na mocy Traktatu Stambulskiego z 24 czerwca 1724 roku, Nadir wszedł 17 sierpnia 1733 roku. Rządy osmańskie na Kaukazie zaczęły się potem szybko rozpadać; Gandża i Tyflis zostały utracone w 1735 roku.", "4ab61a36"]},
"OLAYLAR_P0049:1787-07-27:0":{"b": ["Ultimatum dla posła rosyjskiego — ostatni krok ku wojnie osmańsko-rosyjskiej 1787-1792", "cb389693"], "d": ["Napięcie trwające po aneksji Krymu przez Rosję w 1783 roku pękło, gdy zrozumiano, że rosyjski konsulat w Aleksandrii podburza mameluków w Egipcie przeciw Osmanom. Według hasła I. Abdülhamid w TDV reisülküttâb Süleyman Feyzi Efendi wręczył 27 lipca 1787 roku poselstwu rosyjskiemu w Stambule siedmioartykułowe ultimatum. Nie czekając na odpowiedź Rosji, podjęto decyzję o wojnie i w ciągu kilku tygodni ją ogłoszono; celem wojny było odzyskanie Krymu.", "04debfa8"]},
"OLAYLAR_P0049:1809-11-27:0":{"b": ["Siły rosyjskie zajęły twierdzę Faş (Poti) — utracono ujście Rioni", "c1241b5a"], "d": ["W czasie wojny osmańsko-rosyjskiej 1806-1812 rosyjski atak z maja 1809 roku nie powiódł się; jednak twierdza została poddana Rosjanom 27 listopada 1809 roku.", "84e0aac2"]},
"OLAYLAR_P0049:1812-12-19:0":{"b": ["Twierdza Faş (Poti) zwrócona Osmanom zgodnie z Traktatem Bukareszteńskim", "6a3a8a0a"], "d": ["Zgodnie z Traktatem Bukareszteńskim z 1812 roku twierdza Faş została przekazana Państwu Osmańskiemu 19 grudnia 1812 roku.", "d59bceb8"]},
"OLAYLAR_P0049:1828-06-26:0":{"b": ["Twierdza Faş (Poti) po raz drugi w rękach rosyjskich — pozostała przy Rosji na mocy Traktatu Edirneńskiego", "682d58f0"], "d": ["Na początku wojny osmańsko-rosyjskiej 1828-1829 twierdza Faş została poddana Rosjanom 26 czerwca 1828 roku. Traktatem Edirneńskim z 14 września 1829 roku Poti wraz z Achalciche, Ahılkelek i Anapą zostało oddane Rosji.", "364c160c"]},
"OLAYLAR_P0049:1915-07-25:0":{"b": ["Anglicy zajęli Nasirijję — front Eufratu", "669b979e"], "d": ["Siły angielskie posuwające się z Basry wzdłuż Eufratu pobiły oddziały osmańskie 24 lipca 1915 roku i następnego dnia zajęły Nasirijję. Basra padła w listopadzie 1914 roku; Nasirijja pozostawała w rękach osmańskich jeszcze około ośmiu miesięcy.", "bd125229"]},
"OLAYLAR_P0049:1919-04-12:0":{"b": ["Brytyjska okupacja Karsu — rozwiązano Rząd Południowo-Zachodniego Kaukazu", "9004afc9"], "d": ["Zgodnie z postanowieniem Rozejmu w Mudros o wycofaniu się do granic z 1914 roku armia osmańska opuściła Kars. Ludność regionu założyła 5 listopada 1918 roku wobec ataków ormiańskich i gruzińskich Islamską Radę Karsu i w styczniu 1919 roku kongresem przekształciła ją w Południowo-Zachodni Kaukaski Tymczasowy Rząd Narodowy. Według hasła Kars w TDV Anglicy zajęli Kars 12 kwietnia 1919 roku i rozwiązali ten rząd, aresztowali jego członków i wysłali na zesłanie, a kontrolę nad miastem pozostawili Ormianom.", "06392190"]},
"OLAYLAR_P0049:1919-04-29:0":{"b": ["Włoska okupacja Antalyi", "328331da"], "d": ["Gdy po Rozejmie w Mudros państwa Ententy rozmieszczały się w strefach okupacyjnych w Anatolii, Włochy zwróciły się ku południowo-zachodniej Anatolii. Według hasła Antalya w TDV miasto i jego okolice zostały zajęte przez Włochów 29 kwietnia 1919 roku na podstawie postanowień rozejmu. Okupacja miała trwać około dwóch lat.", "41127caf"]},
"OLAYLAR_P0049:1920-02-11:0":{"b": ["Wyzwolenie Marasza — Francuzi opuścili miasto", "a57d884e"], "d": ["Marasz, zajęty przez Anglików 22 lutego 1919 roku, został umową między oboma państwami 29 października 1919 roku pozostawiony Francuzom. Postawa Ormian w oddziałach francuskich i zdjęcie tureckiej flagi z twierdzy wzburzyły ludność; w mieście zorganizowano Towarzystwo Obrony Praw i Kuwa-yi Milliye. Według hasła Kahramanmaraş w TDV pod koniec walk Francuzi opuścili miasto 11 lutego 1920 roku i zaczęli wycofywać się w kierunku İslâhiye, a Marasz został wyzwolony 11-12 lutego. Miasto otrzymało w 1925 roku medal İstiklâl.", "d3bff1ef"]},
"OLAYLAR_P0049:1920-04-11:0":{"b": ["Wyzwolenie Urfy — garnizon francuski opuścił miasto", "c889488c"], "d": ["W Urfie, zajętej w marcu 1919 roku przez Anglików, a około siedem miesięcy później przez Francuzów, ludność powstała 7 lutego 1920 roku przeciw siłom okupacyjnym. Według hasła Şanlıurfa w TDV po dwumiesięcznych walkach Francuzi zgodzili się 10 kwietnia 1920 roku opuścić Urfę na warunkach układu i następnego dnia wyszli z miasta.", "88526a6f"]},
"OLAYLAR_P0049:1920-09-28:0":{"b": ["Rozpoczęła się operacja Frontu Wschodniego — Kâzım Karabekir przeszedł do ataku na Armenię", "151678df"], "d": ["Wobec oddania Armenii przez Traktat z Sèvres Erzurum, Trabzonu, Wanu, Bitlis i Bingöl oraz wzrostu ataków ormiańskich w regionie rząd Wielkiego Zgromadzenia Narodowego Turcji zezwolił 20 września 1920 roku na operację. Według hasła Kâzım Karabekir w TDV dowódca Frontu Wschodniego Karabekir, wydając rozkaz ataku oddziałom trzymającym przełęcze góry Soğanlı, rozpoczął 28 września operację wschodnią. Zajęto Sarıkamış, Göle i Kağızman; operacja miała trwać miesiąc później wyzwoleniem Karsu.", "add8f41a"]},
"OLAYLAR_P0049:1920-10-30:0":{"b": ["Wyzwolenie Karsu — Front Wschodni wszedł do Karsu", "4e578071"], "d": ["Według hasła Kars w TDV Kâzım Karabekir Pasza wszedł do Karsu 30 października 1920 roku i miasto zostało uwolnione od ormiańskiego zarządu, któremu Anglicy pozostawili kontrolę w 1919 roku. Hasło Karabekir podkreśla, że było to drugie wyzwolenie Karsu: miasto po raz pierwszy zostało odebrane Ormianom w kwietniu 1918 roku. Front Wschodni, posuwając się, zajął 7 listopada Gümrü; wojna zakończyła się Układem z Gümrü z 3 grudnia 1920 roku.", "1841f6d3"]},
"OLAYLAR_P0049:1920-11-07:0":{"b": ["Zajęcie Gümrü — Front Wschodni posunął się w głąb Armenii", "cfddf791"], "d": ["Oddziały Kâzıma Karabekira Paszy, który kontynuował operację po wyzwoleniu Karsu, zajęły Gümrü 7 listopada 1920 roku. Rokowania z Ormianami, którzy zgodzili się na zawieszenie broni, toczyły się w Gümrü, a wojna zakończyła się Układem z Gümrü podpisanym 3 grudnia 1920 roku.", "4c34b9ce"]},
"OLAYLAR_P0049:1920-11-12:0":{"b": ["Zajęcie Iğdıru", "6e952d2e"], "d": ["Pięć dni po zajęciu Gümrü, 12 listopada 1920 roku, Front Wschodni zajął także Iğdır. Iğdır został pozostawiony Turcji Układem z Gümrü z 3 grudnia 1920 roku.", "f96469bd"]},
"OLAYLAR_P0049:1921-02-09:0":{"b": ["Koniec obrony Antepu — miasto po dziesięciu miesiącach oporu pozostawione Francuzom", "e080af8b"], "d": ["Antep, do którego Anglicy weszli 17 grudnia 1918 roku, został 5 listopada 1919 roku pozostawiony Francuzom; pierwszym oporem na linii Antep-Kilis dowodził Şahin Bej. Według hasła Gaziantep w TDV ludność miasta opierała się siłom francuskim od 1 kwietnia 1920 do 7 lutego 1921 roku; gdy opór został złamany, siły obrońców się wycofały, a Francuzi zapanowali nad miastem 9 lutego. Wielkie Zgromadzenie Narodowe Turcji nadało miastu, które dziesięć miesięcy wytrzymało okupację, tytuł gazi trzy dni wcześniej, 6 lutego 1921 roku. Antep miał zostać opuszczony 25 grudnia 1921 roku po Układzie Ankarskim.", "086ee824"]},
"OLAYLAR_P0049:1921-02-23:0":{"b": ["Wyzwolenie Ardahanu i Artvinu", "b9e50d5e"], "d": ["Po Układzie z Gümrü Front Wschodni zwrócił się ku części elviye-i selâse znajdującej się w rękach Gruzji. Według hasła Ardahan w TDV po walkach z bandami gruzińskimi i ormiańskimi 23 lutego 1921 roku wyzwolono wraz z Artvinem także sandżak Ardahan. Hasło Kâzım Karabekir pisze, że tym ruchem odzyskano ziemie elviye-i selâse z wyjątkiem kaz Çürüksu, Adżarii i Batumu.", "1ee51ba4"]},
"OLAYLAR_P0049:1921-03-16:0":{"b": ["Układ moskiewski — Wielkie Zgromadzenie Narodowe Turcji i Rosja Sowiecka wyznaczyły granicę wschodnią", "78d46573"], "d": ["Układ moskiewski został podpisany 16 marca 1921 roku między rządem Wielkiego Zgromadzenia Narodowego Turcji a Rosją Sowiecką. Według hasła Kars w TDV w wyniku tego układu i regulacji granicznych Układu z Karsu z 13 października 1921 roku Kars pozostał w granicach nowego państwa tureckiego. Według hasła Ahıska Achalciche została tym układem przyłączona do guberni tyfliskiej Gruzińskiej Socjalistycznej Republiki Sowieckiej. Granica wschodnia miała zostać ostatecznie ustalona siedem miesięcy później Układem z Karsu podpisanym z republikami Południowego Kaukazu. Tym układem Batum i Adżaria (Hulo, Sarp, Murvaneti, Makhalak'auri) zostały oddane Sowieckiej Gruzji.", "7951b57b"]},
"OLAYLAR_P0049:1921-06-01:0":{"b": ["Włosi zaczęli opuszczać Antalyę", "f7a4eaa7"], "d": ["Według hasła Antalya w TDV włoska okupacja trwająca od 29 kwietnia 1919 roku dobiegła końca, gdy Włosi zaczęli opuszczać miasto 1 czerwca 1921 roku. Antalya i okolice uwolniły się w ten sposób od okupacji, nie czekając na wojskowy wynik Walki Narodowej.", "ffd82d73"]},
"OLAYLAR_P0050:1527-01-01:0":{"b": ["Sejm w Cetinie — szlachta chorwacka wybrała po Mohaczu Ferdynanda Habsburga królem Chorwacji", "55fc9d7e"], "d": ["Gdy po śmierci króla węgiersko-chorwackiego Ludwika II pod Mohaczem tron opustoszał, szlachta chorwacka zebrała się 31 grudnia 1526 roku w Cetinie i w dniu Nowego Roku ogłosiła królem arcyksięcia Austrii Ferdynanda. Według słów TDV Chorwaci dokonali tego wyboru niezależnie od szlachty węgierskiej; dokument wyboru opierał się na uzasadnieniu, że wobec napadów osmańskich nie należy odrywać się od państwa chrześcijańskiego. W ten sposób chorwackie twierdze sąsiadujące z osmańską Bośnią zostały związane z koroną dynastii Habsburgów; według TDV gdy w latach trzydziestych XVI wieku Habsburgowie zaczęli porządkować chorwacki region graniczny, głównym ośrodkiem tej linii stał się Bihać.", "5e7c69d8"]},
"OLAYLAR_P0050:1527-01-01:1":{"b": ["Krótkotrwałe rządy osmańskie w Bihaću — po Mohaczu i upadku Jajca", "fd4118fe"], "d": ["Po zwycięstwie pod Mohaczem Osmanowie zajęli w Bośni Jajce, ośrodek węgierskiej strefy buforowej, i Banję Lukę. Według hasła Bihać w TDV po zdobyciu twierdzy Jajce w roku następującym po Mohaczu Bihać na krótko ponownie przeszedł pod rządy osmańskie. Kiedy i jak twierdza wyszła z rąk osmańskich, źródło nie podaje; TDV zaznacza tylko, że w latach trzydziestych XVI wieku Habsburgowie, porządkując chorwacki region graniczny, uczynili Bihać będący w rękach chrześcijan głównym ośrodkiem. Trwałe zdobycie Bihaća miało nastąpić w 1592 roku w wyprawie beylerbeya Bośni Hasana Paszy.", "3421f09a"]},
"OLAYLAR_P0050:1814-01-28:0":{"b": ["Koniec rządów francuskich w Dubrowniku — do miasta, dawnego płatnika haraczu Osmanom, weszły siły austriackie", "38d42444"], "d": ["Według TDV Republika Dubrownicka, od 1365 roku pozostająca pod opieką osmańską, została przez Francuzów zlikwidowana zajęciem miasta 27 maja 1806 roku. Zimą 1813-1814 mieszkańcy miasta powstali przeciw Francuzom; 3 stycznia 1814 roku austriacki generał-major Milutinović, który przybył do Gruža z dwoma batalionami chorwackimi, oblegał garnizon; po czterodniowym bombardowaniu garnizon francuski wysłał do generała posła. O świcie 28 stycznia wojska austriackie i angielskie weszły do miasta z Gruža; 31 stycznia w regionie zaczął działać tymczasowy zarząd austriacki. Włączenie miasta do ziem austriackich zostało przypieczętowane na Kongresie Wiedeńskim w 1815 roku.", "bb94e4af"]},
"OLAYLAR_P0050:1882-03-06:0":{"b": ["Ogłoszenie Królestwa Serbii — dawne zależne od Osmanów księstwo przekształcone w królestwo", "7d90e712"], "d": ["Księstwo Serbii, które w 1878 roku uzyskało niepodległość i w tym samym roku zajęło będący w rękach osmańskich Niš, zostało za Milana Obrenovicia przekształcone w królestwo. Pierwszym artykułem ustawy wydanej w Belgradzie księstwo ogłoszono Królestwem Serbii, a książę Milan został królem jako Milan I; ustawa została tego samego dnia opublikowana w oficjalnej gazecie Srpske novine. Tak Serbia, do 1878 roku księstwo zależne od Osmanów, zajęła na Bałkanach miejsce z tytułem królestwa. Tym ogłoszeniem całe Księstwo Serbii (Belgrad, Niš, Jagodina, Vranje, Leskovac, Prokuplje, Pirot i in.) stało się Królestwem Serbii.", "a2849d70"]},
"OLAYLAR_P0050:1920-07-01:0":{"b": ["Ustanowiono brytyjski cywilny zarząd mandatowy w Palestynie — koniec zarządu wojskowego na ziemiach odebranych Osmanom", "c0d7b76a"], "d": ["Wraz ze zdobyciem Gazy, a następnie Jerozolimy przez generała Allenby'ego w 1917 roku czterowiekowe zwierzchnictwo osmańskie w Palestynie dobiegło końca, a Jerozolima pozostawała w latach 1917-1920 pod brytyjskim zarządem wojskowym. Konferencja w San Remo z 1920 roku oddała Palestynę pod mandat brytyjski; Anglia od lipca 1920 roku ustanowiła w regionie cywilny zarząd mandatowy i zaczęła rządzić krajem przez wysokiego komisarza. Na czele cywilnej administracji stał wysoki komisarz Herbert Samuel. Powstania arabskie i starcia żydowsko-arabskie, które rozpoczęły się w tym samym roku, miały naznaczyć całą epokę mandatu. Tym wydarzeniem Tyberiada (Palestyna) przeszła pod brytyjski cywilny zarząd mandatowy.", "bc1ec892"]},
"OLAYLAR_P0050:1922-03-15:0":{"b": ["Ogłoszono Królestwo Egiptu — sułtan Ahmad Fuad przyjął tytuł króla", "c6ad08d1"], "d": ["Anglia 18 grudnia 1914 roku jednostronnie zniosła prawa zwierzchnie Państwa Osmańskiego nad Egiptem i objęła kraj protektoratem. Gdy po wojnie rokowania między Anglią a Egiptem nie przyniosły wyniku, Anglia 28 lutego 1922 roku kolejną jednostronną deklaracją ogłosiła Egipt państwem niepodległym. Sułtan Ahmad Fuad przyjął 15 marca 1922 roku tytuł króla (malik) i w Egipcie ogłoszono monarchię. TDV uznaje tę niepodległość za formalną; konstytucja ładu królewskiego miała wejść w życie 19 kwietnia 1923 roku.", "f9b00023"]},
"OLAYLAR_P0051:1480-01-01:0":{"b": ["Wyjście twierdzy Hacıbey (Kaçibey) z rąk Litwy", "382b51e3"], "d": ["Port Kaçibey na północno-zachodnim wybrzeżu Morza Czarnego został ufortyfikowany na początku XV wieku przez wielkiego księcia litewskiego Witolda. W 1480 roku twierdza wyszła z rąk litewskich i otrzymała nazwę Hacıbey. Wybrzeże przeszło pod koniec XV wieku pod kontrolę zależnego od Osmanów Chanatu Krymskiego; włączenie regionu bezpośrednio w osmańską organizację administracyjną nastąpiło w 1538 roku.", "cea3442c"]},
"OLAYLAR_P0051:1570-01-01:0":{"b": ["Gramota Iwana IV dla Kozaków dońskich — pierwszy wiarygodny zapis Wojska Dońskiego", "16c0732e"], "d": ["Wiadomości o obecności kozaków nad Donem zaczynają się od połowy XVI wieku. Według rosyjskiej encyklopedii wojskowej starszeństwo Wojska Dońskiego liczy się od 1570 roku: w tym roku car Iwan IV wysłał do kozaków żyjących nad Dońcem Siewierskim gramotę, prosząc, by pomogli Iwanowi Nowosilcewowi wysłanemu przez Azow jako poseł do sułtana osmańskiego, i obiecał ich nagrodzić. Jest to pierwszy wiarygodny zapis o służbie Kozaków dońskich państwu moskiewskiemu. Głównym ośrodkiem kozaków był najpierw Górne Razdory, potem Czerkask.", "3ce37828"]},
"OLAYLAR_P0051:1585-01-01:0":{"b": ["Moskwa zakłada w Woroneżu wysunięty garnizon przeciw stepowi", "89c941fe"], "d": ["Pod koniec XVI wieku dzisiejsza Ukraina Słobodzka i górne dorzecze Donu były bezludnym dzikim stepem, przez który Tatarzy przechodzili na napady na Moskwę. Rząd moskiewski założył na tym stepie szereg wysuniętych garnizonów; Woroneż założono w 1585 roku jako jeden z nich. Twierdza w następnych dziesięcioleciach była, wraz z Biełgorodem i Kurskiem, jednym z pierwszych ogniw południowej linii obronnej Moskwy.", "ceb11b6b"]},
"OLAYLAR_P0051:1596-01-01:0":{"b": ["Moskwa zakłada Biełgorod, Oskoł i Kursk jako wysunięte garnizony na stepie", "4ff3e225"], "d": ["Rząd moskiewski, przesuwając południową granicę naprzód wobec napadów krymskich, założył w 1596 roku Biełgorod, Oskoł i Kursk jako punkty garnizonowe na dzikim stepie. Biełgorod od tej daty stał się miastem-twierdzą i ośrodkiem 300-kilometrowej Biełgorodzkiej linii obronnej, która miała się rozciągnąć w następnym stuleciu.", "50cb899c"]},
"OLAYLAR_P0052:1884-01-01:0":{"b": ["Sandżak Siirt przeniesiony z Diyarbakıru do wilajetu Bitlis — kaza Eruh i wieś Şırnak również przypisane do Bitlis", "3922d040"], "d": ["Gdy po Tanzimacie z systemu ejaletów przeszło się na system wilajetów, sandżak Siirt, który pozostawał w wilajecie Diyarbakır, został w 1884 roku przeniesiony do wilajetu Bitlis. Według hasła Şırnak w TDV ziemie, na których leży dzisiejszy Şırnak, znalazły się w ten sposób w kazie Eruh należącej do sandżaku Siirt wilajetu Bitlis. Şırnak był wówczas małą wsią w kazie Eruh; jego nazwa pojawia się w zapisach pod koniec XIX wieku, a status ośrodka kazy przypadł na pierwsze lata Republiki. Te ziemie zostały przyłączone do Osmanów w 1514 roku po wyprawie czałdyrańskiej i zarządzane w ramach sandżaku Siirt ejaletu Diyarbakır.", "1539b089"]},
"OLAYLAR_P0053:1624-01-01:0":{"b": ["Przejście Mosulu i Kirkuku w ręce Safawidów — po upadku Bagdadu", "86e176c8"], "d": ["Szach Abbas, który po wydarzeniach rozpoczętych buntem Bekira Subaszy zajął Bagdad, wysłał swego dowódcę Karçakaya Chana z siłami na Mosul i Kirkuk. Namiestnik Mosulu Çerkez Ahmed Pasza zdołał bronić miasta przez kilka dni; Mosul, jak Kirkuk, przeszedł pod zwierzchnictwo Iranu, a namiestnikiem mianowano Kasima Chana. Gdy pod Mosulem pojawił się Sipahi Küçük Ahmed, dowodzący przednimi siłami Hafiza Ahmeda Paszy, Kasim Chan opuścił miasto i wycofał się do Bagdadu, lecz w przeciwnatarciu szacha Abbasa Mosul w 1624 roku ponownie wpadł w ręce Safawidów.", "81474bd6"]},
"OLAYLAR_P0053:1625-01-01:0":{"b": ["Wyzwolenie Mosulu spod Safawidów — wyprawa bagdadzka Hafiza Ahmeda Paszy", "1f9ca4a1"], "d": ["Murad IV wysłał armię pod dowództwem wielkiego wezyra Hafiza Ahmeda Paszy na Bagdad. Gdy armia była w okolicach Diyarbakıru, przednie siły beylerbeya Karamanu Çerkeza Hasana pognały do Kirkuku zwolenników Iranu zebranych pod Altınköprü i objęły kontrolą region, w tym Kirkuk; Safawidzi nie zdołali także tym razem długo utrzymać Mosulu. Hafiz Ahmed Pasza na początku września dotarł najpierw do Mosulu, następnie do Kirkuku i 13 listopada 1625 roku obległ Bagdad; oblężenie zakończyło się bezskutecznie, a Bagdad pozostał w rękach Safawidów. Hasło Kerkük w TDV wiąże natomiast odzyskanie miasta od Safawidów z rokiem 1630 i z Hüsrevem Paszą.", "ad32f3ae"]},
"OLAYLAR_P0053:1630-03-16:0":{"b": ["Odbudowa przez Hüsreva Paszę twierdzy Gülanber w Szehrizor — beylerbeylik Szehrizor", "9511853c"], "d": ["Wielki wezyr Hüsrev Pasza, który wyruszył na wyprawę bagdadzką, po długim pobycie w Mosulu z powodu ulewnych deszczów skierował się do Szehrizor. Rozpoczęto odbudowę twierdzy Gülanber, zburzonej z rozkazu szacha Abbasa w czasie jego najazdu; Szehrizor ponownie uczyniono ośrodkiem beylerbeylikatu, a w twierdzy pozostawiono jako beylerbeya Arnavuda Mustafę Paszę. Hüsrev Pasza podporządkował plemiona regionu, zajął twierdzę Mihriban i 5 maja 1630 roku zadał pod tą twierdzą armii safawidzkiej ciężkie straty.", "ff2c7cea"]},
"OLAYLAR_P0055:1369-01-01:0":{"b": ["Timurtaş Bej zajął w dolinie Tundży Yenice Kızılcaağaç (Elhowo) i Jambol", "2c2aebea"], "d": ["W czasie operacji Murada I przeciw Bułgarii i Bizancjum Kara Timurtaş Bej został wysłany do doliny Tundży; zajął Yenice Kızılcaağaç i Jambol i wrócił do Edirne z licznym łupem.", "e2ca7962"]},
"OLAYLAR_P0055:1371-09-26:0":{"b": ["Księstwo Dejanowiciów (Kostadin-ili) stało się wasalem osmańskim", "54b8dd6c"], "d": ["Gdy po klęsce nad Maricą (Czirmen) państwo serbskie się rozpadło, bracia Jovan i Konstantin Dejanowić założyli własne księstwo z ośrodkiem w Velbužd (później Köstendil), obejmujące region İştip, Ustrumca, Dojran i Köprülü. Gdy Jovan wkrótce zmarł, Konstantin uznał zwierzchnictwo Murada I i został wasalem osmańskim; księstwo żyło dzięki tej więzi półniezależnie. Gdy Konstantin zginął w 1395 roku pod Rovine po stronie Bayezida Błyskawicy, jego kraj bez walki przeszedł pod rządy osmańskie i jako Kostadin-ili stał się sandżakiem.", "25fd68b1"]},
"OLAYLAR_P0055:1412-01-01:0":{"b": ["Despota serbski Stefan Lazarević zajął Şehirköy (Pirot)", "87e1ecb3"], "d": ["Gdy w czasie Interregnum trwała walka między władającym Rumelią Musą Çelebim a jego bratem Çelebim Mehmedem, despota serbski Stefan Lazarević zajął twierdzę Şehirköy leżącą na drodze między Niszem a Sofią i utrzymał ją przeciw atakowi Musy Çelebiego. W następnym roku wraz ze śmiercią Musy Çelebi Mehmed formalnie oddał twierdzę wasalowi Stefanowi; Osmanowie odzyskali Şehirköy dopiero w 1428 roku po śmierci Lazarevicia.", "f50a8066"]},
"OLAYLAR_P0055:1538-01-01:0":{"b": ["Herceg Novi (Castelnuovo) zajęty przez Andreę Dorię", "a8276ff1"], "d": ["Dowódca sprzymierzonej floty zjednoczonej przeciw Osmanom, Andrea Doria, zajął twierdzę Herceg Novi (Castelnuovo) nad Adriatykiem, na południu Dalmacji. W tym samym roku w Dalmacji także Wenecjanie zajęli niektóre miasteczka będące w rękach osmańskich, a siły osmańskie odpowiedziały zajęciem innych twierdz. Twierdza została odzyskana rok później; ponieważ zwierzchnictwo osmańskie prawnie trwało, ten okres przejściowy jest pokazany na mapie jako zakreskowana nakładka okupacyjna.", "a9462728"]},
"OLAYLAR_P0055:1539-08-10:0":{"b": ["Odzyskanie Herceg Novi (Castelnuovo) przez Barbarossę Hayreddina Paszę", "1e5b49ae"], "d": ["Osmanowie, którzy po zwycięstwie pod Prevezą zdobyli przewagę także na środkowym Morzu Śródziemnym, zwrócili się ku twierdzy Nova (Castelnuovo) nad Adriatykiem, zajętej rok wcześniej przez Andreę Dorię. W operacji prowadzonej wspólnie przez Barbarossę Hayreddina Paszę i beja Bośni Gazi Hüsrev Beja twierdzę odzyskano i okupacja dobiegła końca.", "29e2c28b"]},
"OLAYLAR_P0055:1798-12-25:0":{"b": ["Wyprawa Desaix do Górnego Egiptu — dywizja francuska dotarła do Minji, Asjutu i Girgi", "8ff8e4fe"], "d": ["Gdy Napoleon przebywał w Kairze, dywizja generała Desaix, ścigając siły mameluków, posuwała się na południe doliną Nilu: 21 grudnia 1798 roku dotarła do Minji, w Boże Narodzenie do Asjutu, 29 grudnia do Girgi. Tym marszem, który w lutym 1799 roku dotarł do Asuanu, dolina między Kairem a Asuanem weszła pod kontrolę francuską.", "96ddd684"]},
"OLAYLAR_P0055:1799-02-18:0":{"b": ["Napoleon zajął Al-Arisz — początek wyprawy syryjskiej", "69dc52ce"], "d": ["Armia francuska, która zajęła Egipt, maszerując do Syrii, zajęła Al-Arisz na wybrzeżu Synaju.", "8feb359c"]},
"OLAYLAR_P0055:1799-12-28:0":{"b": ["Odzyskanie Al-Arisz od Francuzów", "c25e48a7"], "d": ["Al-Arisz, zajęty przez Napoleona w lutym 1799 roku, został odzyskany pod koniec grudnia tego samego roku przez armię wielkiego wezyra Yusufa Ziyi Paszy.", "3bde687a"]},
"OLAYLAR_P0056:1739-08-28:0":{"b": ["Klęska pod Stawuczanami i poddanie Chocimia Rosjanom (wojna osmańsko-rosyjska 1736-1739)", "657d82d2"], "d": ["W wyprawie 1739 roku główna armia rosyjska pod dowództwem marszałka Münnicha przeszła przez ziemię polską i weszła do Mołdawii, a pod Stawuczanami koło Chocimia zadała ciężką klęskę armii serasker Veli Paszy. Zaraz po tej bitwie twierdza Chocim poddała się Rosjanom, a siły rosyjskie weszły na początku września do Jassów. Jednak gdy Austria zawarła osobny pokój, wojna zakończyła się Traktatem Belgradzkim podpisanym w tym samym miesiącu.", "2e7457b9"]},
"OLAYLAR_P0056:1769-01-01:0":{"b": ["Przekroczenie Dniestru przez armię rosyjską i wejście do Mołdawii (wojna osmańsko-rosyjska 1768-1774)", "938bd834"], "d": ["Około sześć miesięcy po wypowiedzeniu wojny główna armia rosyjska zebrała się na Podolu pod dowództwem księcia Golicyna. Na wezwanie metropolity Mołdawii Dositeja do objęcia Mołdawii opieką rosyjską Golicyn przekroczył Dniestr i przed marszem na Jassy próbował zająć Chocim. Ta pierwsza próba się nie powiodła, armia z powodu braków zaopatrzenia wróciła na Podole; Chocim padł dopiero we wrześniu 1769 roku.", "df52a8ec"]},
"OLAYLAR_P0056:1788-01-01:0":{"b": ["Przekroczenie Dniestru przez rosyjską armię ukraińską pod Mohylowem i wejście do Mołdawii (wojna osmańsko-rosyjska 1787-1792)", "822c7361"], "d": ["W wojnie rozpoczętej wypowiedzeniem przez Osmanów w 1787 roku Rosja utworzyła dwie armie: gdy armia Potiomkina oblegała Özi, armia ukraińska Rumiancewa miała zagrozić Benderom między Dniestrem a Bugiem i utrzymać łączność z Austrią. Rumiancew wydzielił jedną kolumnę na wsparcie Austriaków oblegających Chocim, a głównymi siłami przekroczył Dniestr pod Mohylowem i wszedł do Mołdawii. Tak rozpoczęła się mołdawska noga rosyjskiej operacji, która miała sięgnąć Izmaila i Dunaju.", "7c701213"]},
"OLAYLAR_P0056:1806-11-23:0":{"b": ["Rozpoczęcie przez armię rosyjską bez wypowiedzenia wojny przekroczenia Dniestru i okupacji Księstw Naddunajskich (wojna osmańsko-rosyjska 1806-1812)", "2094a4d9"], "d": ["W październiku 1806 roku generał Michelson otrzymał rozkaz zajęcia Mołdawii i Wołoszczyzny; wojny formalnie jeszcze nie wypowiedziano. Siły rosyjskie zaczęły przekraczać Dniestr, a dowódcy twierdz Chocim, Bender, Akkerman i Kilia poddali swe twierdze bez walki. Tylko strażnik Izmaila nie uległ rosyjskim namowom. Wypowiedzenie wojny przez Wysoką Portę nastąpiło po tej okupacji.", "c770c2b4"]},
"OLAYLAR_P0056:1806-11-30:0":{"b": ["Zajęcie Akkermanu przez Rosjan (1806)", "25aed8d6"], "d": ["Tydzień po przekroczeniu Dniestru przez armię rosyjską bez wypowiedzenia wojny Akkerman został zajęty przez siły księcia Kantakuzina; Tatarzy w mieście opuścili je. Akkerman został Traktatem Bukareszteńskim z 1812 roku oddany Rosji wraz z Besarabią.", "1e7e3f9e"]},
"OLAYLAR_P0056:1806-12-25:0":{"b": ["Wejście Miłoradowicza do Bukaresztu — rosyjska okupacja Wołoszczyzny", "62e4a8e1"], "d": ["Gdy armia rosyjska weszła do Mołdawii, strażnik Rusczuku Mustafa Pasza wysłał do Bukaresztu oddział, który utrzymał miasto. Oddział generała Miłoradowicza wyparł go z miasta; siły osmańskie wycofały się do Giurgiu. Bukareszt pozostawał od tej daty pod okupacją rosyjską do Traktatu Bukareszteńskiego z 1812 roku.", "217aa20b"]},
"OLAYLAR_P0056:1810-06-10:0":{"b": ["Poddanie Silistry Rosjanom", "d687d04b"], "d": ["Silistra, oblegana jesienią 1809 roku przez Bagrationa, została w wyprawie 1810 roku ponownie oblężona z rozkazu naczelnego wodza Kamienskiego. Roboty oblężnicze rozpoczęte pod koniec maja trwały kilka dni, a twierdza poddała się pod warunkiem swobodnego wyjścia garnizonu. W tych samych dniach Pazardżik zdobyto szturmem, a Razgrad padł. Rosjanie trzymali Silistrę rok; wiosną 1811 roku Kutuzow wysadził mury i opuścił twierdzę.", "56cdb224"]},
"OLAYLAR_P0056:1810-10-01:0":{"b": ["Poddanie Nikopola i Kule (Turnu) Rosjanom bez oporu", "e297a862"], "d": ["Po poddaniu się Rusczuku i Giurgiu naczelny wódz Kamienski ruszył wzdłuż rzeki na zachód, by zająć twierdze naddunajskie aż do granicy serbskiej. Nikopol i Kule na przeciwległym brzegu poddały się bez oporu; oddziały rosyjskie zajęły Plewnę, Łowczę i Selvi i zburzyły ich umocnienia. Rosjanie trzymali Nikopol sześć miesięcy, a w kwietniu 1811 roku opuścili twierdzę, wysadziwszy ją.", "f77715d7"]},
"OLAYLAR_P0056:1811-07-04:0":{"b": ["Bitwa pod Rusczukiem i zburzenie przez Kutuzowa Rusczuku oraz wycofanie się na lewy brzeg Dunaju", "6af4bf85"], "d": ["Na początku czerwca wielki wezyr wyszedł z Szumenu i zaatakował pod Rusczukiem armię rosyjską, a pobity wycofał się na umocnioną pozycję na południu. Kutuzow, mimo wygranej bitwy, uznał pozostanie w Rusczuku za niebezpieczne; kazał zburzyć umocnienia twierdzy i przeprawił wszystkie siły na lewy brzeg Dunaju. Wielki wezyr ponownie zajął opuszczony Rusczuk. W ten sposób rosyjskie utrzymanie miasta, które Kamienski przejął po krwawym oblężeniu 26 września 1810 roku, trwało dziewięć miesięcy. Według zapisu TDV Kutuzow przed odejściem kazał wysadzić umocnienia wokół miasta i średniowieczną twierdzę; w wywołanym pożarze ze trzydziestu ośmiu meczetów istniejących w 1810 roku w mieście dwanaście oraz dwa z ośmiu mescidów zostało całkowicie zniszczonych. Przekroczenie Dunaju przez armię osmańską jesienią tego samego roku miało zakończyć się oblężeniem Slobozji.", "3b247b6b"]},
"OLAYLAR_P0056:1828-05-07:0":{"b": ["Przekroczenie Prutu przez rosyjski 6. Korpus Piechoty i wejście do Księstw Naddunajskich (wojna osmańsko-rosyjska 1828-1829)", "9d9aaaad"], "d": ["Po wypowiedzeniu wojny przez Rosję armia marszałka Wittgensteina przystąpiła do działań. 6. Korpus Piechoty przekroczył Prut i wszedł do Mołdawii i Wołoszczyzny, jego awangarda pod dowództwem generała Geismara skierowała się na Małą Wołoszczyznę. Kilka dni później 7. Korpus oblegał Braiłę, a 3. Korpus przygotował się do przekroczenia Dunaju między Izmailem a Reni. Księstwa Naddunajskie miały pozostawać pod okupacją rosyjską do 1834 roku.", "cba5d549"]},
"OLAYLAR_P0056:1829-06-30:0":{"b": ["Poddanie Silistry Dybiczowi — okupacja rosyjska trwająca do 1836 roku", "55e28ab1"], "d": ["Na początku wyprawy 1829 roku nowy rosyjski naczelny wódz Dybicz wybrał na pierwszy cel Silistrę. Garnizon uparcie opierał się robotom oblężniczym prowadzonym przez generała Schildera; Dybicz, pozostawiwszy część sił przy oblężeniu, pomaszerował na tyły wielkiego wezyra. Oblężenie trwało, a twierdza się poddała. Rosjanie trzymali Silistrę także po zakończeniu wojny do 1836 roku.", "4c1a9e8e"]},
"OLAYLAR_P0056:1836-01-01:0":{"b": ["Opuszczenie Silistry przez Rosjan", "4fe2afaf"], "d": ["Po Traktacie Edirneńskim z 1829 roku Rosjanie nie opuścili Silistry i trzymali twierdzę do 1836 roku. Po wycofaniu się żołnierzy rosyjskich namiestnik Selim Pasza kazał zbudować pośrodku miasta, do połowy zburzonego, wielki jednokopułowy meczet.", "39444f60"]},
"OLAYLAR_P0056:1853-07-03:0":{"b": ["Przekroczenie Prutu przez armię rosyjską i rozpoczęcie okupacji Księstw Naddunajskich (Wołoszczyzny-Mołdawii) — droga do wojny krymskiej", "77862041"], "d": ["Gdy Wysoka Porta odrzuciła żądania Mienszykowa w sporze o święte miejsca w Jerozolimie, car Mikołaj I rozkazał zająć zależne od Osmanów księstwa naddunajskie „jako zakładnika, dopóki Turcja nie spełni naszych słusznych żądań”. Awangarda armii pod dowództwem księcia Gorczakowa przekroczyła Prut, a dwanaście dni później weszła do Bukaresztu; za nią główne siły rozlały się na księstwa trzema kolumnami. Ta okupacja bez wypowiedzenia wojny doprowadziła w Europie do kryzysu dyplomatycznego, a w październiku 1853 roku do wypowiedzenia wojny przez Osmanów; Rosjanie opuścili księstwa dopiero latem 1854 roku pod naciskiem Austrii.", "04443242"]},
"OLAYLAR_P0057:1442-01-16:0":{"b": ["Maszasza osiedlili się w Hawizie — początek rządów Maszasza w Chuzestanie", "674d0173"], "d": ["Muhammad b. Falah, który wystąpił z roszczeniem do mahdyzmu, po umocnieniu się wśród plemion Ma'adi zdołał w następnym roku osiąść w Hawizie, będącej pod kontrolą Timurydów. Miasto stało się ośrodkiem dynastii Maszasza, która miała panować w Chuzestanie.", "53937c8f"]},
"OLAYLAR_P0057:1508-05-02:0":{"b": ["Szach Isma'il przyłączył Hawizę — Maszasza stali się namiestnikami podległymi Safawidom", "7e245f4d"], "d": ["Szach Isma'il kazał zabić niektórych członków dynastii Maszasza, oskarżając ich o herezję, i objął region Hawiza swoimi rządami. Wodzowie Maszasza kontynuowali odtąd swe istnienie jako namiestnicy podlegli Safawidom.", "ee776160"]},
"OLAYLAR_P0057:1534-01-01:0":{"b": ["Twierdze Pasin, Şüregel i Oltu zajęte od Safawidów — między Erzurum a Karsem", "68f297aa"], "d": ["W czasie Wyprawy Irakejn Sulejmana Prawodawcy twierdze Pasin, Şüregel i Oltu między Erzurum a Karsem zostały zajęte od Safawidów.", "06909003"]},
"OLAYLAR_P0057:1557-04-02:0":{"b": ["Zajęcie portu Massawa przez Özdemira Paszę", "4cc1d4ad"], "d": ["Beylerbey Ejaletu Habesz Özdemir Pasza, po zajęciu wysp Dahlak, zajął 2 kwietnia 1557 roku miasto Massawa na przeciwległym brzegu; następnie także Arkiko weszło pod rządy osmańskie. W ten sposób główny port Abisynii otwarty na Morze Czerwone wpadł w ręce osmańskie.", "7c5e89f0"]},
"OLAYLAR_P0057:1793-01-31:0":{"b": ["Przyłączenie hrabstwa Nicei do Francji", "a140cab2"], "d": ["Po przyłączeniu Sabaudii w listopadzie 1792 roku francuski Konwent Narodowy zatwierdził 31 stycznia 1793 roku przyłączenie hrabstwa Nicei, należącego do Królestwa Sardynii, do Francji; region stał się departamentem Alpes-Maritimes. Nicea wróciła po klęsce Napoleona do Sardynii na mocy I Traktatu Paryskiego z 30 maja 1814 roku.", "b313c90b"]},
"OLAYLAR_P0057:1917-01-09:0":{"b": ["Bitwa pod Rafah — angielsko-anzacka kawaleria zajęła pozycje Magruntein i Rafah", "5053c8ef"], "d": ["Dywizja Konna Anzac Egipskich Sił Ekspedycyjnych, które przeszły Synaj, brygada Korpusu Wielbłądziego i angielska brygada jeomenów zaatakowały osmańską pozycję trzymaną bastionami w Magruntein, około kilometra na południe od Rafah. Po trudnej walce przełamanie dokonane przez Nowozelandczyków i oddziały wielbłądzie załamało osmańską obronę; pozycję i leżące obok Rafah zajęto, a siły angielskie dotarły do granicy Palestyny.", "7f90289f"]},
"OLAYLAR_P0057:1918-03-12:0":{"b": ["Zimowa operacja Kâzıma Karabekira: wraz z Erzurum odzyskano Hasankale (Pasinler)", "27df4879"], "d": ["Siły osmańskie pod dowództwem Kâzıma Karabekira Paszy, który po rozpadzie armii rosyjskiej przeszedł do działań na wschodzie, mimo ciężkich warunków zimowych odzyskały Erzincan, Erzurum i leżące na wschód od Erzurum Hasankale; marsz sięgnął 25 kwietnia 1918 roku Karsu.", "80a72c73"]},
"OLAYLAR_P0057:1919-01-23:0":{"b": ["Brytyjska okupacja Eskişehir", "8e349037"], "d": ["Po Rozejmie w Mudros państwa Ententy zaczęły obejmować kontrolą węzły kolejowe Anatolii. Według hasła Eskişehir w TDV miasto zostało zajęte przez Anglików 23 stycznia 1919 roku. Oddziały angielskie opuściły Eskişehir 20 marca 1920 roku.", "5bb8774d"]},
"OLAYLAR_P0057:1919-05-11:0":{"b": ["Lądowanie Włochów na wybrzeżach południowo-zachodniej Anatolii — Marmaris, Bodrum, Kuşadası", "15d6fb7a"], "d": ["Włochy, które na Konferencji Pokojowej w Paryżu opuściły obrady na znak protestu przeciw progreckiej postawie sojuszników, po Antalyi wysadziły wojska na wybrzeżach południowo-zachodnich. Według TDV 5 maja Marmaris, 11 maja Bodrum, 13 maja Kuşadası zostały zajęte przez Włochów. W tych samych dniach Grecy wylądowali w Fethiye; rywalizacja obu państw o zachodnią Anatolię przygotowała drogę do zajęcia Izmiru.", "82266143"]},
"OLAYLAR_P0057:1919-05-26:0":{"b": ["Wejście sił greckich do Manisy i Aydın", "a4230775"], "d": ["Armia grecka, która wylądowała w Izmirze 15 maja, w krótkim czasie rozszerzyła się w głąb lądu. Według hasła Manisa w TDV siły greckie weszły do miasta 26 maja 1919 roku; według hasła Aydın Aydın został zajęty następnego dnia, 27 maja. Okupacja Manisy miała trwać do września 1922 roku.", "514ead8b"]},
"OLAYLAR_P0057:1919-06-28:0":{"b": ["Włoska okupacja Burdur — wycofanie kompanii kierującej się na Isparta", "874e9d6d"], "d": ["Włosi, którzy zajęli Antalyę, posuwali się w głąb regionów wewnętrznych. Według hasła Isparta w TDV oddziały włoskie zajęły 28 czerwca Burdur, a 15 sierpnia skierowały się z kompanią żołnierzy do Isparty. Gdy mieszkańcy Isparty odrzucili propozycję złożenia broni i oświadczyli, że będą się opierać, Włosi wycofali się następnego dnia.", "35806188"]},
"OLAYLAR_P0057:1919-06-30:0":{"b": ["Krótkotrwałe wyzwolenie Aydın i ponowna okupacja 4 lipca", "753c739f"], "d": ["Przeciw okupacji greckiej zorganizowały się siły narodowe wokół Ödemiş, Nazilli i Aydın. Według hasła Aydın w TDV miasto zajęte 27 maja 1919 roku zostało 30 czerwca na krótko wyzwolone, lecz 4 lipca ponownie dostało się pod okupację grecką. Miasto pozostawało odtąd pod okupacją do 7 września 1922 roku.", "a0031b01"]},
"OLAYLAR_P0057:1919-07-23:0":{"b": ["Włoska okupacja Muğli", "a4f5a926"], "d": ["Włochy rozszerzyły swą okupację wybrzeży południowo-zachodnich w głąb lądu. Według hasła Muğla w TDV miasto zostało zajęte przez Włochów 23 lipca 1919 roku. Okupacja Muğli trwała do 5 lipca 1921 roku.", "b77c243c"]},
"OLAYLAR_P0057:1919-10-15:0":{"b": ["Początek francuskiego zarządu wojskowego w Tracji Zachodniej", "5801e6de"], "d": ["Tracja Zachodnia, będąca w rękach Bułgarii, która przegrała I wojnę światową, została objęta kontrolą państw Ententy w czasie rokowań pokojowych. Według hasła Batı Trakya w TDV region został zajęty przez siły francuskie 15 października 1919 roku; Towarzystwo Obrony Praw Tracji Zachodniej przeniosło w tym okresie swój ośrodek do Gümülcine. Zarząd francuski trwał do oddania regionu Grecji w maju 1920 roku decyzją z San Remo.", "58f44e3a"]},
"OLAYLAR_P0057:1920-03-20:0":{"b": ["Opuszczenie Eskişehir przez Anglików", "6820e164"], "d": ["Eskişehir, od stycznia 1919 roku pod okupacją angielską, został według hasła Eskişehir w TDV opuszczony przez Anglików 20 marca 1920 roku. Miasto kilka miesięcy później, w czerwcu 1920 roku, stało się ośrodkiem Frontu Zachodniego utworzonego przez Wielkie Zgromadzenie Narodowe Turcji.", "5f817d34"]},
"OLAYLAR_P0057:1920-06-22:0":{"b": ["Letnia ofensywa grecka — okupacja Akhisaru, Somy, Balıkesiru i Alaşehiru", "f096d2b4"], "d": ["Wraz z zezwoleniem sprzymierzonych dla armii greckiej na przekroczenie linii Milne'a w zachodniej Anatolii rozpoczęła się wielka ofensywa grecka. Według hasła Millî Mücadele w TDV oddziały greckie, które 22 czerwca ruszyły trzema kolumnami, zajęły Akhisar, Kırkağaç, Somę i Balıkesir. Na południu 26 czerwca zajęto Alaşehir, a 3 lipca Nazilli.", "bb4b4b94"]},
"OLAYLAR_P0057:1920-07-08:0":{"b": ["Grecka okupacja Bursy", "7c2b32a1"], "d": ["Północna kolumna letniej ofensywy po Balıkesirze zwróciła się ku Marmarze. Według haseł Bursa i Millî Mücadele w TDV Bursa została zajęta przez Greków 8 lipca 1920 roku. Brak szacunku okazany mauzoleom pierwszych władców osmańskich wywołał w całym kraju wielką reakcję.", "2f040dcd"]},
"OLAYLAR_P0057:1920-07-20:0":{"b": ["Zajęcie Tracji Wschodniej przez armię grecką — Edirne i Kırklareli", "9eb3bda1"], "d": ["Grecja przed podpisaniem Traktatu z Sèvres zabrała się do faktycznego zajęcia także Tracji Wschodniej. Według hasła Millî Mücadele w TDV armia grecka zajęła 20 lipca całą Trację; wydarzenie to skłoniło w Stambule padyszacha do zwołania dwa dni później Rady Sułtanatu. Kırklareli został zajęty 26 lipca, a Edirne weszło pod zarząd grecki w tym samym miesiącu.", "4c68dd1f"]},
"OLAYLAR_P0057:1920-07-28:0":{"b": ["Wejście Armii Czerwonej do Nachiczewania", "6dcb9005"], "d": ["Anglicy, którzy na początku 1919 roku weszli do regionu, rozwiązali Republikę Aras i opuścili Nachiczewań latem tego samego roku. Według hasła Nahçıvan w TDV Armia Czerwona weszła 28 lipca 1920 roku do Nachiczewania, oddała zarząd komunistom i utworzono Nachiczewańską Socjalistyczną Republikę Sowiecką. Status regionu został w 1921 roku układem podpisanym w Karsie określony jako autonomiczna jednostka podległa Azerbejdżanowi.", "bc49ebba"]},
"OLAYLAR_P0057:1920-08-29:0":{"b": ["Grecka okupacja Uşak", "74ad2713"], "d": ["Armia grecka kontynuowała marsz w celu narzucenia Traktatu z Sèvres, którego Ankara nie uznawała. Według haseł Uşak i Millî Mücadele w TDV po Gediz także Uşak został zajęty 29 sierpnia 1920 roku. Mustafa Kemal Pasza skontrolował oddziały Kuwa-yi Milliye w mieście około miesiąc przed tą okupacją.", "b7c70a40"]},
"OLAYLAR_P0057:1920-10-25:0":{"b": ["Grecka okupacja İnegöl i Yenişehir", "4a0460e7"], "d": ["Oddziały greckie w Bursie zaczęły posuwać się na wschód, w kierunku Eskişehir. Według hasła Millî Mücadele w TDV 25 października 1920 roku zajęto İnegöl i Yenişehir. Gdy zrozumiano, że marszu greckiego nie da się zatrzymać siłami milicyjnymi, front zachodni został zorganizowany na nowo na zasadzie armii regularnej.", "53e977e3"]},
"OLAYLAR_P0057:1921-01-01:0":{"b": ["Koniec włoskiej okupacji Burdur (rok)", "609123c8"], "d": ["Burdur, zajęty przez Włochów 28 czerwca 1919 roku, doświadczył według hasła Burdur w TDV krótkotrwałej okupacji włoskiej w latach 1919-1921. Źródło nie podaje dnia ewakuacji; na mapie okupacja kończy się na początku 1921 roku. Włochy wycofały się ze strefy okupacyjnej w Anatolii całkowicie latem 1921 roku.", "0ac33ff9"]},
"OLAYLAR_P0057:1921-03-23:0":{"b": ["Druga ofensywa armii greckiej — okupacja Bilecik, Afyon i Adapazarı", "9ae146e2"], "d": ["Armia grecka, która po klęsce pod pierwszym İnönü wysadziła w Izmirze nowe siły, przeszła do ponownej ofensywy, nie czekając na upływ terminu uznanego przez Konferencję Londyńską. Według hasła Millî Mücadele w TDV Grecy zajęli 23 marca Bilecik i Afyon. Na północy także Adapazarı został zajęty przez Greków 25 marca.", "7d247e77"]},
"OLAYLAR_P0057:1921-03-28:0":{"b": ["Opuszczenie Batumu przez siły tureckie", "ba5745dc"], "d": ["Anglicy opuścili Batum, wycofując się w lipcu 1920 roku z Kaukazu, a miasto zajął rząd Gruzji. Według hasła Batum w TDV Układ Moskiewski podpisany 16 marca 1921 roku z Rosją Sowiecką oddał Batum Gruzji. Siły tureckie opuściły miasto 28 marca 1921 roku, a Batum stał się ośrodkiem Autonomicznej Republiki Adżarii utworzonej w ramach Gruzji.", "9555d8e0"]},
"OLAYLAR_P0057:1921-04-07:0":{"b": ["Odzyskanie Afyonu — walki pod Aslıhanlar", "2bbba17b"], "d": ["Po ofensywie grecka zatrzymanej 1 kwietnia pod drugim İnönü na froncie południowym 7 kwietnia odzyskano Afyon. Hasło Millî Mücadele w TDV podsumowuje to słowami „Po ciężkiej klęsce pod Aslıhanlar 7 kwietnia odzyskano Afyon”; jednak prace z historii wojskowości umieszczają walki pod Aslıhanlar-Dumlupınar po opuszczeniu Afyonu, między 8 a 15 kwietnia, i piszą, że przewaga taktyczna pozostała po stronie greckiej — obie relacje się nie zgadzają, podano obie. Zwycięstwo pod İnönü było świętowane wiecami w całym kraju, przede wszystkim w Stambule.", "3525b97a"]},
"OLAYLAR_P0057:1921-06-28:0":{"b": ["Wyzwolenie Izmitu — po Adapazarı", "cec60e36"], "d": ["Adapazarı, zajęty przez Greków w marcu 1921 roku, został według hasła Adapazarı w TDV odzyskany 21 czerwca. Według hasła İzmit w TDV Izmit, zajęty 6 lipca 1920 roku najpierw przez Anglików, potem przez Greków, został wyzwolony 28 czerwca 1921 roku. Grecy, opuszczając miasto, spalili część bazarową.", "da5f0806"]},
"OLAYLAR_P0057:1921-07-05:0":{"b": ["Wyzwolenie Muğli spod okupacji włoskiej", "143ddf98"], "d": ["Włochy zaczęły latem 1921 roku wycofywać się ze strefy okupacyjnej w Anatolii; opuszczanie Antalyi rozpoczęło się 1 czerwca. Według hasła Muğla w TDV Muğla, od 23 lipca 1919 roku pod okupacją włoską, została wyzwolona 5 lipca 1921 roku.", "84bff82f"]},
"OLAYLAR_P0057:1921-07-20:0":{"b": ["Opuszczenie Eskişehir — armia grecka weszła do Eskişehir, Kütahyi i Bilecik", "a948a74d"], "d": ["Armia turecka, zaskoczona w bitwach Kütahya-Eskişehir, wycofała się z rozkazu Mustafy Kemala Paszy na wschód od Sakarii. Według haseł TDV Grecy weszli 20 lipca 1921 roku do Eskişehir, 21 lipca do Kütahyi, 22 lipca do Bilecik. Król Grecji Konstantyn przewodniczył 28 lipca w Kütahyi radzie wojennej, a armia przygotowała się do ofensywy w kierunku Ankary.", "29f7f871"]},
"OLAYLAR_P0057:1922-04-29:0":{"b": ["Wycofanie wojsk włoskich z Marmaris i Kuşadası", "1d672994"], "d": ["Włosi, którzy od maja 1919 roku przebywali na wybrzeżach południowo-zachodniej Anatolii, po zbliżeniu z rządem w Ankarze krok po kroku opróżniali strefę okupacyjną. Antalya i Bodrum zostały opuszczone latem 1921 roku; ostatnie oddziały włoskie opuściły także Kuşadası i Marmaris pod koniec kwietnia 1922 roku.", "f956076c"]},
"OLAYLAR_P0057:1922-08-26:0":{"b": ["Rozpoczęła się Wielka Ofensywa", "efba4bd3"], "d": ["Po rocznych przygotowaniach po Sakarii armia turecka przeszła na froncie Afyon do ogólnej ofensywy. Według haseł Millî Mücadele i Kütahya w TDV Wielka Ofensywa rozpoczęła się rankiem 26 sierpnia 1922 roku z Afyonu, a opór armii greckiej został w krótkim czasie złamany.", "7eaf426f"]},
"OLAYLAR_P0057:1922-08-27:0":{"b": ["Wyzwolenie Afyonu", "beaeef23"], "d": ["W drugim dniu ofensywy front grecki został przełamany pod Afyonem. Według hasła Afyonkarahisar w TDV w Wielkiej Ofensywie dowodzonej osobiście przez Atatürka siły greckie zostały rozbite, a miasto wyzwolono 27 sierpnia 1922 roku. Ten dzień jest obchodzony jako dzień wyzwolenia Afyonu.", "bfb4dd98"]},
"OLAYLAR_P0057:1922-08-30:0":{"b": ["Bitwa Naczelnego Dowódcy — wyzwolenie Kütahyi", "376d3118"], "d": ["Główne siły armii greckiej zostały okrążone między Afyonem a Dumlupınar. Według hasła Millî Mücadele w TDV operacja okrążenia została dopełniona 30 sierpnia Bitwą Naczelnego Dowódcy, którą osobiście prowadził Naczelny Dowódca Mustafa Kemal Pasza. Według hasła Kütahya w TDV tego samego dnia dywizja kawalerii wyzwoliła Kütahyę, spaloną i zburzoną przez wycofujące się siły greckie.", "6ecd76e4"]},
"OLAYLAR_P0057:1922-09-01:0":{"b": ["Wyzwolenie Uşak", "0f2d44d1"], "d": ["Po Bitwie Naczelnego Dowódcy resztki armii greckiej wycofały się na zachód, w kierunku Izmiru. Według hasła Uşak w TDV Uşak, od 29 sierpnia 1920 roku pod okupacją, został wyzwolony 1 września 1922 roku wraz z wejściem sił narodowych do miasta. W pożarze wzniecony przez wycofujące się siły okupacyjne spłonęło około trzech czwartych miasta.", "ea4dc034"]},
"OLAYLAR_P0057:1922-09-02:0":{"b": ["Wyzwolenie Eskişehir", "f442de5c"], "d": ["Na północnym skrzydle Wielkiej Ofensywy siły greckie musiały opuścić także Eskişehir. Według hasła Eskişehir w TDV miasto, od 20 lipca 1921 roku pod okupacją, zostało wyzwolone 2 września 1922 roku po zwycięstwie z 30 sierpnia. Po trzynastomiesięcznej okupacji część bazarowa była spalona, a miasto zniszczone w połowie.", "3b15a7c5"]},
"OLAYLAR_P0057:1922-09-06:0":{"b": ["Wyzwolenie Bilecik", "35dbd49b"], "d": ["Według hasła Bilecik w TDV miasto w czasie Walki Narodowej trzykrotnie było pod okupacją grecką; trzecia okupacja, rozpoczęta 22 lipca 1921 roku, zakończyła się 6 września 1922 roku. W pożarze wzniecony przez siły greckie przy opuszczaniu miasta spłonęła większość domów, sklepów i konaku rządowego.", "28e74c34"]},
"OLAYLAR_P0057:1922-09-07:0":{"b": ["Wyzwolenie Aydın", "ef1280b5"], "d": ["Gdy armia turecka zbliżyła się do Izmiru, siły greckie w dolinie Meandra także się wycofały. Według hasła Aydın w TDV miasto zostało wyzwolone 7 września 1922 roku przez siły tureckie, częściowo zburzone i z mocno zmniejszoną ludnością. Wycofujący się Grecy spalili większą część miasta.", "358e3333"]},
"OLAYLAR_P0057:1922-09-11:0":{"b": ["Odzyskanie Bursy", "6ad1da0b"], "d": ["Po wyzwoleniu Izmiru armia turecka posuwała się na północy ku wybrzeżom Marmary. Według hasła Bursa w TDV miasto, od 8 lipca 1920 roku pod okupacją grecką, zostało odzyskane 10-11 września 1922 roku. Marsz armii stąd na Çanakkale zaniepokoił Anglików i otworzył drogę rozmowom w Mudanyi.", "caa09d48"]},
"OLAYLAR_P0057:1922-11-10:0":{"b": ["Przejęcie Tracji Wschodniej — Kırklareli i Tekirdağ", "2a08d65c"], "d": ["Rozejm w Mudanyi przewidywał opuszczenie Tracji Wschodniej przez armię grecką i przekazanie jej Turcji; Refet Pasza, któremu powierzono przejęcie Tracji, przybył 19 października do Stambułu. Według TDV Kırklareli, od 26 lipca 1920 roku pod okupacją, został odzyskany 10 listopada 1922 roku, a Tekirdağ został zgodnie z rozejmem zwrócony Turkom 13 listopada. W ten sposób Tracja Wschodnia została przyłączona do ziem tureckich bez walki.", "cb085872"]},
"OLAYLAR_P0058:1339-01-01:0":{"b": ["Eretna przyłączył do siebie okolice Tokat, Kayseri i Samsun", "4a088f9f"], "d": ["Emir Eretna, który jako namiestnik ilchański zyskał siłę w Anatolii, po ponownym uzyskaniu poparcia sułtana mameluków an-Nasira Muhammada rozszerzył w 1339 roku swe granice i przyłączył do siebie okolice Tokat, Kayseri i Samsun. Okolice Zamantı na wschód od Kayseri weszły w tym okresie także pod rządy Eretny. Beylik ogłosił niepodległość w 1341 roku po śmierci an-Nasira.", "5be963a4"]},
"OLAYLAR_P0058:1360-01-01:0":{"b": ["Dulkadirli Halil Bej rozszerzył granice do Zamantı", "aa911e87"], "d": ["Z powodu osłabienia ziem Eretny wskutek tego, że na czele beylika Eretny stanął w małoletności Mehmed Bej, od południa nasiliły się napady Turkmenów. W 1360 roku, gdy jeden z wodzów turkmeńskich, Omar Bej, zajął Malatyę, Dulkadiroğlu Halil Bej rozszerzył granice swego beylika do Zamantı na wschód od Kayseri. Tak okolice Zamantı między Elbistanem a Kayseri wpadły w ręce Dulkadiroğulları, a beylik trzymał ten region do osmańskiej aneksji w 1515 roku.", "6f54371d"]},
"OLAYLAR_P0058:1394-01-01:0":{"b": ["Bayezid Błyskawica ponownie ściśle oblegał Stambuł", "244834ca"], "d": ["Stambuł, od 1391 roku okresowo blokowany, został wiosną 1394 roku ponownie ściśle oblężony przez Bayezida Błyskawicę. Stosunek z Bizancjum, które od 1371 roku płaciło Osmanom haracz i wysyłało pomoc wojskową, zmienił się w ten sposób w jawną wrogość. Oblężenie zniesiono wraz z pojawieniem się zagrożenia ze strony Timura i Bitwą pod Ankarą w 1402 roku.", "c3af0f1d"]},
"OLAYLAR_P0058:1424-02-22:0":{"b": ["Pokój bizantyjski z Muradem II — Bizancjum znów zgodziło się płacić haracz", "6474d704"], "d": ["Murad II, który w 1422 roku oblegał Stambuł przeciw wspierającemu Fałszywego Mustafę Bizancjum, podpisał 22 lutego 1424 roku układ pokojowy z cesarzem bizantyjskim. Na mocy tego układu Bizancjum znów zgodziło się płacić Osmanom haracz i zwrócić miejsca zajęte po 1402 roku na wybrzeżach Marmary, Egejskiego i Czarnego, z wyjątkiem grodów Silivri i Terkos; roczny haracz, od którego uwolniło się układem z Emirem Sulejmanem w 1403 roku, wrócił w ten sposób. Bizancjum utrzymywało ten stan do zdobycia Stambułu w 1453 roku.", "dd19c749"]},
"OLAYLAR_P0058:1514-10-23:0":{"b": ["Twierdze Bayburt i Kiğı przejęte od Safawidów — Erzincan i Bayburt oddane Bıyıklı Mehmedowi Bejowi", "2c7fd65e"], "d": ["Gdy Selim Groźny, wracający z Tebrizu po zwycięstwie pod Çaldıranem, był w obozie, nadeszły wieści o przejęciu twierdz Bayburt i Kiğı. Sandżakbej Trabzonu Bıyıklı Mehmed Bej i sandżakbej Janiny Mustafa Bej zajęli w październiku 1514 roku Bayburt, broniony przez emira szacha Isma'ila Kara Maksuda-i Sultani. Erzincan, który bez walki wszedł pod rządy osmańskie, został wraz z Bayburtem 23 października 1514 roku oddany jako beylerbeylik Bıyıklı Mehmedowi Bejowi, a Bayburt uczyniono ośrodkiem sandżaku.", "d3796513"]},
"OLAYLAR_P0058:1514-11-24:0":{"b": ["Selim Groźny wrócił z wyprawy tebryskiej do Amasyi i spędził tam zimę", "49d51f94"], "d": ["Selim Groźny, który spędził w Tebrizie dziewięć dni, z powodu braków żywności i niechęci żołnierzy zrezygnował ze spędzenia zimy w Iranie i wrócił przez Kars i Bayburt. Padyszach, który obchodził w Niksarze Święto Ramadanu, dotarł do Amasyi i spędził tu zimę. Zamierzał w następnym roku ponownie ruszyć na Safawidów; w Amasyi zaczął się nacisk janczarów na powrót do Stambułu, a wyprawa była kontynuowana wiosną 1515 roku zdobyciem Kemah.", "2693e398"]},
"OLAYLAR_P0059:1594-11-13:0":{"b": ["Wołoszczyzna, Mołdawia i Siedmiogród wspólnie powstały przeciw Osmanom", "e71d3ee9"], "d": ["W połowie 1594 roku trzy wojewodztwa na północ od Dunaju — Wołoszczyzna, Mołdawia i Siedmiogród — postanowiły działać wspólnie przeciw Osmanom. Wojewoda Mołdawii Aron Tiran, przystąpiwszy do Świętej Ligi zawiązanej przez cesarza Austrii i papieża Klemensa VIII, uznał się za zależnego od Księstwa Siedmiogrodu; wojewoda Wołoszczyzny Mihai Viteazul dołączył do ruchu z niezadowolenia z ciężaru podatków. 13 listopada 1594 roku na Wołoszczyźnie i w Mołdawii rozpoczęły się jednoczesne powstania przeciw rządom osmańskim, a przy poparciu Siedmiogrodu ruch rozlał się na południe od Dunaju, na ziemie osmańskie. Według TDV İslâm Ansiklopedisi ten trójstronny sojusz otworzył północny front osmańsko-habsburskiej Długiej Wojny (1593-1606) trwającej w tych latach.", "30f44add"]},
"OLAYLAR_P0069:1523-01-01:0":{"b": ["Zdobycie twierdzy Ostrovica w dolinie Uny", "5c6cc91b"], "d": ["Ostrovica, będąca w rękach Frankopanów i innych chorwackich możnowładców, leżała na stromym grzbiecie łączącym północną i południową część doliny Uny. W 1523 roku przeszła pod rządy osmańskie i do 1878 roku mieściła garnizon osmański. Twierdza zyskała właściwe znaczenie po Karłowicach (1699): z powodu bliskości granicy weneckiej i austriackiej została rozbudowana, stała się ośrodkiem kapitanatu Stara Ostrovica; miasteczko Kulen Vakuf założono na początku XVIII wieku u jej stóp.", "0978b370"]},
"OLAYLAR_P0069:1527-05-01:0":{"b": ["Zdobycie twierdz Udbina i Krbava — Lika wchodzi pod rządy osmańskie", "5fe329d3"], "d": ["Równina Krbava opustoszała w 1524 roku, w Udbinie pozostał tylko garnizon Karlovicia. Karlović odniósł w kwietniu 1527 roku ostatnie zwycięstwo pod twierdzą, lecz pod koniec maja Udbina wraz z twierdzami Mrsinj i Komić wpadła w ręce paszy Bośni. W tym samym roku okolice Gospicia oddano agom Senković. Lika i Krbava stały się odtąd częścią sandżaku z ośrodkiem w Obrovacu, który w 1580 roku otrzymał nazwę Kırka.", "0e759e1a"]},
"OLAYLAR_P0069:1592-01-01:0":{"b": ["Ostateczne przejście Drežnika i županii Drežnik pod rządy osmańskie", "6624ad14"], "d": ["Drežnik, od 1323 roku w rękach Frankopanów, został w 1578 roku tymczasowo zajęty przez Osmanów. W 1592 roku twierdza i cała županija Drežnik weszły ostatecznie pod rządy osmańskie; w tym samym roku padł także Bihać. W XVIII wieku Drežnik podlegał kapitanatowi Ostrožac.", "b41efb59"]},
"OLAYLAR_P0069:1636-01-01:0":{"b": ["Zajęcie twierdzy Cetin przez Osmanów", "98815f97"], "d": ["Cetin, od połowy XVI wieku kluczowa twierdza w obronie regionu Slunj przed Osmanami, po wielokrotnych oblężeniach przeszła w 1636 roku pod rządy osmańskie. Ten pierwszy okres osmański trwał dwa lata.", "44a52e6e"]},
"OLAYLAR_P0069:1638-01-01:0":{"b": ["Powrót twierdzy Cetin na stronę habsburską", "690f9f84"], "d": ["Cetin, który w 1636 roku wpadł w ręce osmańskie, w 1638 roku wrócił do chorwacko-habsburskiej obrony granicy i pozostał nią do 1670 roku.", "8f16b3ec"]},
"OLAYLAR_P0069:1670-01-01:0":{"b": ["Cetin ponownie twierdzą osmańską", "e1750675"], "d": ["Cetin w 1670 roku znów został twierdzą osmańską i w XVIII wieku został gruntownie umocniony: średniowieczną twierdzę otoczono murami z basztami. Twierdza trzymała do 1790 roku północno-zachodni kraniec marchii bośniackiej.", "3cf8713d"]},
"OLAYLAR_P0069:1689-01-01:0":{"b": ["Utrata Liki i Krbavy — Udbina i Gospić w rękach habsburskich sił granicznych", "01277a38"], "d": ["W wojnie toczonej po klęsce pod Wiedniem chorwackie oddziały graniczne pod dowództwem generała Karlovaca Herbersteina zajęły w 1689 roku Udbinę; Gospić również w tym samym roku wyszedł spod zarządu osmańskiego. Osmańska Lika, trwająca ponad 160 lat, dobiegła końca, opustoszałe miejsca zasiedlono nową ludnością chorwacką, a Udbina do pokoju w Świsztowie (1791) była ważną twierdzą obrony granicznej przeciw Osmanom.", "bde1a0dc"]},
"OLAYLAR_P0069:1788-01-01:0":{"b": ["Zajęcie Drežnika przez Austriaków — zachodni front bitwy pod Dubicą", "05d5e5f1"], "d": ["W wojnie osmańsko-austriackiej 1788-1791 siły Habsburgów zajęły Drežnik na zachód od Bihaća. Na mocy artykułu 4 Traktatu w Świsztowie Drežnik i Cetin pozostały pod rządami Habsburgów i nigdy nie wróciły do Bośni.", "30f8f200"]},
"OLAYLAR_P0069:1790-01-01:0":{"b": ["Zajęcie twierdzy Cetin przez Austriaków", "df182480"], "d": ["W 1790 roku armia habsburska zaatakowała Cetin, Bužim i Veliką Kladušę i zajęła Cetin. Mobilizacja ogłoszona przez namiestnika Bośni i przeciwnatarcie nie odzyskały twierdzy; artykuł 4 Traktatu w Świsztowie pozostawił Cetin Habsburgom. Bośniaccy pogranicznicy ponownie zajęli twierdzę krótkimi napadami w 1809 i 1813 roku.", "fc69baec"]},
"OLAYLAR_SEHIR_ILK:1284-03-20:0":{"b": ["Bilecik wspomniany po raz pierwszy — granica z Bizancjum zaczynała się w Bilecik", "7b69f743"], "d": ["W wydarzeniach roku 683 przekazanych przez Neşrîego Bilecik występuje jako miejsce, w którym zaczyna się granica między marchią Osman Beja a Bizancjum. Jest to pierwsza znana w historii wzmianka o osadzie; nie jest to jej założenie.", "f668b296"]},
"OLAYLAR_SEHIR_ILK:1299-09-28:0":{"b": ["Moneta w imieniu Gazana Chana w Burdur — pierwsze znane świadectwo miasta", "01974ddc"], "d": ["Hamidoğulları musieli pod naciskiem Ilchanów w roku 699 kazać wybić w Burdur monetę w imieniu Gazana Chana. Ta moneta jest pierwszym pisemnym/datowanym świadectwem Burdur.", "83a1e1ee"]},
"OLAYLAR_SEHIR_ILK:1352-03-01:0":{"b": ["Çorum wspomniane w kraju Eretny — pierwsze znane świadectwo miasta", "bf7bd67f"], "d": ["Wśród miast pod zwierzchnictwem Eretny Beja w chwili jego śmierci w Muharramie 753 wymieniony jest także Çorum. Założenie miasta nie jest znane; ta wzmianka jest najwcześniej datowanym znalezionym świadectwem.", "68c8fd3f"]},
"OLAYLAR_SEHIR_ILK:1368-01-20:0":{"b": ["Braiła po raz pierwszy wspomniana — przywilej Vlaicu Vodă dla kupców z Braszowa", "0b3517a7"], "d": ["Wojewoda Wołoszczyzny Władysław dał kupcom z Braszowa dokument ułatwiający przewóz towarów drogą przez Braiłę. Ten dokument jest pierwszym znanym pisemnym świadectwem Braiły; miejsce występuje tu jeszcze nie jako miasto, lecz jako dunajski kraniec drogi. Nie jest to data założenia.", "8ed7db79"]},
"OLAYLAR_SEHIR_ILK:1420-01-01:0":{"b": ["Kiszyniów po raz pierwszy wspomniany w ukazie wojewody Mołdawii", "a50799d7"], "d": ["Nazwa Kiszyniowa po raz pierwszy pojawia się w ukazie wojewody Mołdawii Aleksandra z 1420 roku. Miasto długo pozostawało małym miasteczkiem mołdawskim; gdy w 1812 roku wraz z Besarabią przeszło do Rosji, stało się ośrodkiem prowincji.", "61d831d5"]},
"OLAYLAR_SEHIR_ILK:1445-01-01:0":{"b": ["Gałacz po raz pierwszy wspomniany w dokumencie wojewody Mołdawii", "a31af8a2"], "d": ["Wojewoda Mołdawii Stefan II zwolnił z opłat celnych dwa wozy klasztoru Humor wożące ryby z Gałacza. Ten dokument jest pierwszym z pewnością znanym pisemnym świadectwem Gałacza; osada mogła istnieć wcześniej jako wieś rybacka nad Dunajem.", "40d464f1"]},
"OLAYLAR_SEHIR_ILK:1452-04-03:0":{"b": ["Nazwa Mostaru po raz pierwszy w dokumencie z Dubrownika", "a599bc55"], "d": ["Nazwa Mostaru po raz pierwszy pojawia się w dokumencie z Dubrownika z 3 kwietnia 1452 roku; osada leżała na ziemiach Księstwa Hercegowiny. Podbój osmański nastąpił w latach 1466-68.", "5fba613f"]},
"OLAYLAR_SEHIR_ILK:1458-01-01:0":{"b": ["Meczet Hünkâr w Sarajewie — najwcześniej datowane świadectwo osady", "ad697a7d"], "d": ["Sandżakbej Bośni İshak Bej kazał zbudować w pierwszej muzułmańskiej osadzie na równinie Saraj dla siebie pałac, w imieniu Mehmeda Zdobywcy Meczet Hünkâr, a obok niego łaźnię. Meczet nosi datę 862 (1458); jest najwcześniej datowaną znaną budowlą Sarajewa.", "d7927c3d"]},
"OLAYLAR_SEHIR_ILK:1462-02-01:0":{"b": ["Wakfname İshak Beja — wakf zalążka miasta Sarajewa", "0b364229"], "d": ["Z wakfname İshak Beja z Dżumada I 866 (luty 1462) wynika, że oprócz meczetu i łaźni zbudowano zawiję, mewlewihane, imaret, most na Miljacce, po drugiej stronie Han Kolobara, bedesten, karawanseraj i sklepy. Dokument jest podstawą wakfową miasta; osada istniała przed nim.", "5f20e8f0"]},
"OLAYLAR_SEHIR_ILK:1472-06-08:0":{"b": ["Tatarpazarcığı po raz pierwszy zapisane w rejestrze akıncıów", "3b1c839e"], "d": ["Najstarsze zapisy o mieście sięgają roku 877 (1472): rejestr akıncıów w Bibliotece Narodowej w Sofii zapisuje osadę.", "45a744f9"]},
"OLAYLAR_SEHIR_ILK:1494-02-06:0":{"b": ["Banja Luka po raz pierwszy wspomniana w poleceniu króla Władysława II", "0ebc6288"], "d": ["Nazwa Banja Luka po raz pierwszy pojawia się w poleceniu króla węgiersko-chorwackiego Władysława II z 6 lutego 1494 roku; okolica była związana z koroną węgierską przez banat Jajce. Podbój osmański nastąpił zimą 1527-28.", "02da21ca"]},
"OLAYLAR_SEHIR_ILK:1494-10-02:0":{"b": ["Mieszkańcy Basry dopełniają przeniesienia na dzisiejsze miejsce — stara Basra opuszczona", "20f96eac"], "d": ["Ludność z czasem zaczęła osiedlać się w dzisiejszej Basrze, którą uważała za bezpieczniejszą przed napadami beduinów i do której łatwiej było doprowadzić wodę; przejście na nowe miejsce zakończono w roku 900 (1494-95). Stara Basra, założona za Umara, leżała około 25 km od dzisiejszego miasta.", "7e2ce96c"]},
"OLAYLAR_SEHIR_ILK:1503-01-01:0":{"b": ["Chan Mengli Giray kazał zbudować Pałac Chanów nad Çürüksu — fundament Bakczysaraju", "0792497c"], "d": ["W dolinie, która była letnim regionem łowieckim i wypoczynkowym namiestników Złotej Ordy i pierwszych chanów krymskich, chan Mengli Giray I kazał zbudować nad Çürüksu pałac znany dziś jako Pałac Chanów i tym położył fundament pod Bakczysaraj. Miasto rozwijało się wokół pałacu i wzdłuż wąskiej doliny Çürüksu i pod koniec XVI wieku rozkwitło, stając się ośrodkiem Chanatu Krymskiego.", "dbbc246c"]},
"OLAYLAR_SEHIR_ILK:1552-01-01:0":{"b": ["Kozacy zaporoscy założyli pierwszą Sicz na wyspie Chortyca", "e6ca0dd9"], "d": ["Książę Dmytro Wyszniewiecki założył na wyspie Mała Chortyca na Dnieprze pierwszą Sicz Zaporoską. Twierdza została w 1558 roku oblężona i zburzona przez Tatarów krymskich; Sicz przeniesiono potem na wyspy na południu. Termin: „Sicz” (po ukraińsku Sich) to ufortyfikowany pniami i rowem ośrodkowy obóz Kozaków zaporoskich na wyspach Dniepru; jest to kwatera, miejsce rady (Rada) i ośrodek wybieranego dowódcy wojska (koszowy), nie jest stolicą państwa.", "2af408f9"]},
"OLAYLAR_SEHIR_ILK:1593-01-01:0":{"b": ["Założono Sicz Bazawłuk", "fcd507ae"], "d": ["Po zburzeniu przez Tatarów Siczy Tomakiwskiej Kozacy zaporoscy założyli nową Sicz na wyspie Bazawłuk u zbiegu Dniepru z jego odnogami Czortomłyk, Pidpilna i Skarbna. Sicz została w 1638 roku po stłumieniu powstania kozackiego zburzona wyprawą polską. Termin: „Sicz” (po ukraińsku Sich) to ufortyfikowany pniami i rowem ośrodkowy obóz Kozaków zaporoskich na wyspach Dniepru; jest to kwatera, miejsce rady (Rada) i ośrodek wybieranego dowódcy wojska (koszowy), nie jest stolicą państwa. W tej dacie „Hetmanatu” jeszcze nie ma (1648); nazwa Zaporoże oznacza „za porohami” i Sicze leżą na stepowej granicy poniżej porohów Dniepru. Nie ma etnicznego pokrewieństwa z Kozakami Kazachstanu: Kozacy zaporoscy to wspólnota wschodniosłowiańska (ukraińska), prawosławna; wspólne jest tylko słowo o pochodzeniu tureckim „kozak” (wolny wojownik).", "ecc27d31"]},
"OLAYLAR_SEHIR_ILK:1628-01-01:0":{"b": ["Sicz Mykytyn Róg po raz pierwszy wspomniana", "61e22abc"], "d": ["Nazwa czwartej Siczy założonej w Mykytynym Rogu, w miejscu dzisiejszego Nikopola, po raz pierwszy pojawia się w 1628 roku; została zajęta w 1648 roku przez Bohdana Chmielnickiego. Jest to pierwsze znane świadectwo miejsca, nie jego założenie.", "63f059d0"]},
"OLAYLAR_SEHIR_ILK:1652-01-01:0":{"b": ["Założono Sicz Czortomłycką", "4b6e8197"], "d": ["Kozacy zaporoscy założyli na cyplu u zbiegu Dniepru z rzeką Czortomłyk Sicz Czortomłycką, zwaną też „Starą Siczą”. Sicz została 25 maja 1709 roku zburzona przez armię rosyjską za poparcie Mazepy.", "e7b8c2ca"]},
"OLAYLAR_SEHIR_ILK:1654-01-01:0":{"b": ["Charków założony przez kozackich uchodźców", "288b303c"], "d": ["Na północnym skraju dzikiego stepu, u zbiegu rzek Łopań i Charków, kozaccy uchodźcy z prawego brzegu Dniepru założyli osadę. Charków wkrótce stał się ośrodkiem Ukrainy Słobodzkiej podległej Moskwie.", "0d185061"]},
"OLAYLAR_SEHIR_ILK:1711-01-01:0":{"b": ["Kozacy zaporoscy za zgodą chana krymskiego założyli Siczę Oleszkowską", "ed26f29d"], "d": ["Gdy atak rosyjski zmusił do opuszczenia Siczy w Kamience, Kozacy zaporoscy za zgodą chana krymskiego osiedlili się na ziemiach chanatu w Oleszkach na lewym brzegu rzeki Konka. Po Traktacie Prutskim dołączyli do nich Kozacy Hordijenki. Chan nie zezwolił, by Sicz miała mury i działa.", "acb5924a"]},
"OLAYLAR_SEHIR_ILK:1728-01-01:0":{"b": ["Sicz Oleszkowska złupiona i opuszczona", "52361709"], "d": ["Prorosyjscy Kozacy samarscy napadli na Siczę Oleszkowską, złupili ją i podpalili koszary. Siczy nie odbudowano; Kozacy wrócili w 1730 roku do Kamienki, a w 1734 roku, składając przysięgę wierności Rosji, założyli Nową Sicz.", "bf03f792"]},
"OLAYLAR_SEHIR_ILK:1738-01-01:0":{"b": ["Założono twierdzę Stawropol nad Wołgą", "eb087a50"], "d": ["Na środkowej Wołdze założono twierdzę Stawropol dla Kałmuków, którzy przyjęli chrześcijaństwo (dzisiejsze Togliatti).", "d486bb18"]},
"OLAYLAR_SEHIR_ILK:1738-03-24:0":{"b": ["Nadir Szach zajmuje Kandahar i każe zburzyć stare miasto", "9cc23e6b"], "d": ["Władca Afszarydów Nadir Szach po długim oblężeniu zajął Kandahar będący w rękach Afgańczyków Ghilzaj. Miasto zniszczono, a jego ludność przeniosła się do Nadirabadu założonego na południowy wschód od dawnego miejsca; stary Kandahar nigdy już nie był miastem.", "c8df437b"]},
"OLAYLAR_SEHIR_ILK:1777-01-01:0":{"b": ["Na linii Azow-Mozdok założono twierdzę Stawropol", "7fd9b9f1"], "d": ["Na linii umocnień Azow-Mozdok, założonej po Küçük Kaynarca dla kontrolowania stepu między Kubaniem a Terekiem, zbudowano dziesięć twierdz; jedną z nich był Stawropol. Twierdza stała się potem ośrodkiem namiestnictwa kaukaskiego i guberni stawropolskiej.", "f27157a3"]},
"OLAYLAR_SEHIR_ILK:1778-01-01:0":{"b": ["Założono stocznię Chersoń u ujścia Dniepru", "115f2c34"], "d": ["U ujścia Dniepru, który po Küçük Kaynarca przeszedł do Rosji, w pobliżu szańca Aleksandra zbudowanego w 1737 roku i wkrótce zburzonego założono stocznię i nadano jej nazwę Chersoń. Miasto stało się w 1784 roku kazą, a w 1803 ośrodkiem guberni.", "a664a96e"]},
"OLAYLAR_SEHIR_ILK:1779-01-01:0":{"b": ["Grecy z Krymu założyli Mariupol nad brzegiem Morza Azowskiego", "4e3af209"], "d": ["Grecy, którzy przybyli z Krymu, założyli Mariupol w miejscu, gdzie Kalmius wpada do Morza Azowskiego. Miasto stało się w 1784 roku ośrodkiem powiatu w namiestnictwie jekaterynosławskim.", "d36ebbc5"]},
"OLAYLAR_SEHIR_ILK:1783-01-01:0":{"b": ["Jekaterynosław przeniesiony na dzisiejsze miejsce nad Dnieprem", "ec361381"], "d": ["Jekaterynosław, założony przez Potiomkina w 1778 roku u zbiegu rzek Kilczeń i Samara, został z powodu niezdrowego położenia w 1783 roku przeniesiony na dzisiejsze miejsce.", "b37ccddb"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:0":{"b": ["W zatoce Achtiar założono rosyjski port wojenny Sewastopol", "01058a25"], "d": ["Po aneksji Krymu przez Rosję w 1783 roku zatokę, w której leżała tatarska wieś krymska Achtiar (Akjar), wybrano na port wojskowy; port założono w następnym roku i nadano mu nazwę Sewastopol. Miasto stało się w 1804 roku głównym portem rosyjskiej floty Czarnomorskiej.", "03079154"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:1":{"b": ["Założono umocnienie Mikołajów u ujścia Bugu", "d57e52b9"], "d": ["U zbiegu Bugu Południowego i rzeki Ingul założono z rozkazu księcia Potiomkina umocnienie. W 1788 roku otwarto tu stocznię, a osada stała się jednym z ośrodków budowy okrętów floty Czarnomorskiej.", "76edde36"]},
"OLAYLAR_SEHIR_ILK:1784-01-01:2":{"b": ["Założono osadę graniczną nad Molocznaą, zalążek Melitopola", "637d5817"], "d": ["Po aneksji Krymu założono osadę graniczną nad brzegiem rzeki Moloczna. Osada w 1816 roku otrzymała nazwę Nowooleksandriwka, a w 1841 roku została miastem pod nazwą Melitopol.", "9151422f"]},
"OLAYLAR_SEHIR_ILK:1805-01-01:0":{"b": ["Założono Nowoczerkask — nowy ośrodek Wojska Dońskiego", "bf5709fd"], "d": ["Administracyjny ośrodek Wojska Dońskiego przeniósł się z Czerkaska, dotąd będącego ośrodkiem, do Nowoczerkaska założonego w miejscu Biriuczij Kut między rzekami Aksaj i Tuzłow.", "544a425d"]},
"OLAYLAR_SEHIR_ILK:1813-03-06:0":{"b": ["Wadi Halfa zapisana w podróży Burckhardta po Nubii", "6efc72ec"], "d": ["Szwajcarski podróżnik J. L. Burckhardt pisze w dzienniku z 6 marca 1813 roku, że przeszedł przez Wadi Halfę i że prowadzono tam pewien handel. Jest to pierwsze znalezione datowane świadectwo.", "a3a1877c"]},
"OLAYLAR_SEHIR_ILK:1827-01-01:0":{"b": ["Założono przystań Berdiańsk nad Morzem Azowskim", "908ac3cf"], "d": ["Z inicjatywy księcia Michaiła Woroncowa założono Berdiańsk u ujścia rzeki Berda do Morza Azowskiego. Osada stała się miastem w 1835 roku, a ośrodkiem powiatu w 1842.", "8742949e"]},
"OLAYLAR_SEHIR_ILK:1838-01-01:0":{"b": ["Mieszkańcy Malatyi pozostają w ogrodach Aspuzu — zalążek nowoczesnej Malatyi", "d1dba159"], "d": ["Osmańska kwatera główna przeciw egipskiej armii İbrahima Paszy została latem 1838 roku przeniesiona z Mezraa do Malatyi. Mieszkańcy Malatyi, którzy zamieszkiwali letnie domy w Aspuzu, po odejściu armii nie wrócili do zimowych domów w starym, zrujnowanym mieście; Aspuzu stało się zalążkiem nowoczesnej Malatyi. Stara Malatya (Battalgazi) kurcząc się, nadal istniała.", "f4d616ac"]},
"OLAYLAR_SEHIR_ILK:1918-04-02:0":{"b": ["Wan zakładany na nowym miejscu — zrujnowane stare miasto opuszczone", "6d278578"], "d": ["Wan został wyzwolony z okupacji 2 kwietnia 1918 roku. Powracający, zamiast naprawiać stare Wan nad brzegiem jeziora, zrujnowane w latach wojny, założyli nowe miasto około 7 km w głąb lądu od brzegu, w miejscu dawnych dzielnic Norşen i Arak. Stare miasto zostało opuszczone.", "5a729844"]},
"OLAYLAR_SENKRON_0930:1298-01-01:0":{"b": ["Marasz przeszedł do mameluków — namiestnik Aleppo Bilban at-Tabahi odzyskał go od Ormian", "03171265"], "d": ["Marasz, od 1258 roku będący w rękach Królestwa Armenii Cylicyjskiej, w 1293 roku układem sułtana Halila z Ormianami na krótko przeszedł do mameluków, a po ich wycofaniu ponownie wpadł w ręce Ormian. W 697 (1298) namiestnik mameluków w Aleppo Bilban at-Tabahi odzyskał miasto. Marasz pozostawał odtąd ziemią mamelucką do wzrostu Dulkadirlich.", "8fd31b13"]},
"OLAYLAR_SENKRON_0930:1372-01-01:0":{"b": ["Cesarstwo Bizantyńskie stało się płatnikiem haraczu Osmanów", "615df998"], "d": ["Po zwycięstwie pod Czirmenem (1371) cesarz bizantyński Jan V zgodził się zimą 1372 roku zostać płatnikiem haraczu Murada I: miał płacić roczny haracz i dostarczać żołnierzy na wyprawy sułtana. Bizancjum pozostawało od tej daty do 1403 roku państwem wasalnym zależnym od Osmanów; oblężenie Bayezida Błyskawicy z 1391 roku podniosło haracz. Po klęsce pod Ankarą układ z Gelibolu (1403) zawarty z Sulejmanem Çelebim zwolnił Bizancjum z haraczu; układem z Muradem II w 1424 roku haracz rozpoczął się na nowo.", "e3c816ac"]},
"OLAYLAR_SENKRON_0930:1399-09-01:0":{"b": ["Bayezid Błyskawica po śmierci Barkuka włączył Besni, Darende i Divriği do ziem osmańskich", "8e57d7e6"], "d": ["Gdy po śmierci sułtana mameluków Barkuka (czerwiec 1399) sprawy administracyjne państwa mameluków się popsuły, Bayezid Błyskawica zszedł do dorzecza Eufratu i wraz z Malatyą włączył do ziem osmańskich Besni (Behisni), Darende i Divriği. Sivas został wcześniej pozostawiony Osmanom po śmierci Kadiego Burhaneddina latem 1398 roku. Divriği od 1391 roku było pod zwierzchnictwem mameluków i stanowiło wysunięty posterunek podległy ejaletowi Aleppo. Rządy osmańskie nie potrwały tu długo: z powodu zbliżającego się zagrożenia ze strony Timura Divriği zostało w 1401 roku oddane ponownie mamelukom, a ostateczne wejście miasta pod rządy osmańskie nastąpiło po Mardż Dabik w 1516 roku.", "ec7cd171"]},
"OLAYLAR_SENKRON_0930:1400-08-01:0":{"b": ["Besni przeszło do mameluków podczas wyprawy Timura na Sivas i Malatyę", "4853da9a"], "d": ["Besni, które Bayezid Błyskawica zajął w 1398 roku wraz z Sivas, Darende i Malatyą, wpadło w ręce mameluków w 1400 roku, gdy Timur zajmował Sivas i Malatyę. Timur 27 września 1400 roku po zaciętym oblężeniu zdobył także Besni; gdy wycofał się z regionu, Besni ponownie weszło pod zwierzchnictwo mameluków i pozostało przy mamelukach (z wyjątkiem jednego okresu dulkadirskiego) do zajęcia przez Selima Groźnego w sierpniu 1516 roku.", "0ead96f9"]},
"OLAYLAR_SENKRON_0930:1401-01-01:0":{"b": ["Divriği z powodu zagrożenia timurydzkiego oddane ponownie mamelukom", "97196b1f"], "d": ["Divriği, które Bayezid Błyskawica zajął w 1398 roku od mameluków, zostało w 1401 roku w obliczu zbliżania się Timura do Anatolii oddane ponownie mamelukom. Dlatego po zniszczeniu Sivas przez Timura (1400) Divriği widnieje na mapie w kolorze mameluków; w tych samych miesiącach Bayezid zajmował na wschodzie Erzincan i Kemah, czyli ziemia mamelucka znalazła się między osmańskimi ziemiami na zachodzie (Sivas) i na północnym wschodzie (Kemah). Divriği przeszło ostatecznie do Osmanów dopiero po Mardż Dabik w 1516 roku.", "3f13d015"]},
"OLAYLAR_SENKRON_0930:1414-01-01:0":{"b": ["Sułtan mameluków Szajch odebrał Dulkadirlim Antep i Darende", "f90c9508"], "d": ["Sułtan mameluków Szajch, zaniepokojony przyjaźnią Dulkadirlich z Osmanami, wyruszył na wyprawę w 1414 roku; odebrał Antep i Darende, które wcześniej z własnej woli oddał Dulkadirlim.", "9f9b94e1"]},
"OLAYLAR_SENKRON_0930:1418-01-01:0":{"b": ["Dulkadıroğlu Mehmed Bej odzyskał Darende i włączył do swych ziem także Besni", "df914dcb"], "d": ["Darende, zajęte przez mameluków w 1414 roku, odzyskał Dulkadıroğlu Mehmed Bej w 1418 roku i włączył do swych ziem także Besni.", "d469f850"]},
"OLAYLAR_SENKRON_0930:1436-01-01:0":{"b": ["Mamelucy pobili Dulkadirlich pod Antepem; Besni wróciło pod rządy mameluków (w przybliżeniu)", "72742430"], "d": ["Armia mameluków pobiła Dulkadirlich pod Antepem w 1436 roku, a Mehmed Bej wycofał się do Akdağu. Rok powrotu Besni do mameluków nie jest zapisany w źródle; Besni zostało przyłączone do Dulkadiru w 1418 roku, a przed zdobyciem go przez Szehsuwara Beja od mameluków w 1465 roku wróciło do mameluków. Atlas zwraca Besni mamelukom wraz z tą klęską w sąsiednim ośrodku Antep (deklarowane przybliżenie).", "dc3b71ff"]},
"OLAYLAR_SENKRON_0930:1467-01-01:0":{"b": ["Dulkadıroğlu Szehsuwar Bej zajął Besni od mameluków (w przybliżeniu)", "843f0fc4"], "d": ["Szehsuwar Bej (1465-1472), mianowany przez Mehmeda Zdobywcę beyem Dulkadiru, zdobył będące w rękach mameluków Besni, Gerger, Birecik i Rumkale; mamelucy zostali pobici jesienią 1467 roku pod Turnadağı i wiosną 1468 roku w pobliżu Antepu.", "c812ae2a"]},
"OLAYLAR_SENKRON_0930:1471-01-01:0":{"b": ["Emir Yeszbek pobił Szehsuwara Beja; Besni wróciło pod rządy mameluków (w przybliżeniu)", "4d856aee"], "d": ["Wiosną 1471 roku emir Yeszbek pobił Szehsuwara Beja nad strumieniem Savron; mamelucy odzyskali Kadirli i Kozan. Szehsuwar został stracony w 1472 roku w Kairze, a mamelucy ponownie osadzili na czele beylika Szahbudaka. Wraz z tym powrotem także Besni weszło pod rządy mameluków (TDV besni: „pod koniec XV wieku ponownie wpadło w ręce mameluków”).", "3ba3c319"]},
"OLAYLAR_SENKRON_0930:1550-09-15:0":{"b": ["Siły Ferdynanda zajęły i ufortyfikowały Szolnok", "6c8416e6"], "d": ["Gdy Osmanowie przygotowywali się do zbudowania twierdzy w Szolnoku nad Cisą, siły Ferdynanda I ich uprzedziły: w połowie września 1550 roku zajęły Szolnok, a twierdza została doprowadzona do stanu obronnego w połowie października. Tak Szolnok, należący do ziem Izabeli, wpadł w ręce Habsburgów rok przed przejściem Siedmiogrodu do Ferdynanda; Osmanowie zajęli twierdzę w 1552 roku.", "eea8389b"]},
"OLAYLAR_SENKRON_0930:1551-07-26:0":{"b": ["Siedmiogród przeszedł pod rządy Habsburgów: zgromadzenie w Kolozsvár uznało zrzeczenie się Izabeli", "8458a566"], "d": ["Po porozumieniu Martinuzziego z Ferdynandem królowa Izabela podpisała w imieniu małoletniego króla Jana Zygmunta 19 czerwca 1551 roku w twierdzy Szászsebes narzuconą jej akt zrzeczenia się. Zgromadzenie Siedmiogrodu, zebrane 26 lipca w Kolozsvár, uznało to zrzeczenie i zwierzchnictwo króla Ferdynanda; armia habsburska generała Castaldo weszła do Siedmiogrodzkiego Białogrodu (Gyulafehérvár). Tak zależny od Osmanów Siedmiogród przeszedł pod rządy Habsburgów, które miały trwać pięć lat.", "d8d0aad9"]},
"OLAYLAR_SENKRON_0930:1556-03-12:0":{"b": ["Rządy Habsburgów w Siedmiogrodzie dobiegły końca: Siedmiogród ponownie wojewodztwem zależnym od Osmanów", "721a482a"], "d": ["Habsburgowie próbowali w 1551 roku zapanować nad Siedmiogrodem rękami chorwackiego pochodzenia duchownego Martinuzziego (Fráter György), mianowanego opiekunem z powodu małoletniości Jana Zygmunta; Siedmiogrodzki Białogród (Gyulafehérvár), Kolozsvár, Brassó i Segesvár pozostawały pięć lat pod rządami Habsburgów. Osmanowie temu zapobiegli i Siedmiogród ponownie stał się wojewodztwem płacącym im haracz. Siedmiogród zachował potem w XVI i XVII wieku przez około 150 lat swój status oparty na szerokiej autonomii w sprawach wewnętrznych i podległości Stambułowi w sprawach zewnętrznych.", "0566dd84"]},
"OLAYLAR_SENKRON_0930:1557-01-01:0":{"b": ["Várad, Huszt i Tokaj przeszły na stronę Szapolyaiów", "587c782d"], "d": ["Po powrocie Izabeli i Jana Zygmunta do Siedmiogrodu w 1556 roku zwolennicy Szapolyaiów oblegali w 1556 roku Nagyvárad. W 1557 roku arystokraci znad Górnej Cisy zajęli najważniejsze twierdze królewskie — Várad, Huszt i Tokaj; w rękach Ferdynanda pozostały tylko Gyula i Világos. Várad stał się odtąd twierdzą księstwa Siedmiogrodu i pozostał nią do zajęcia przez Osmanów w 1660 roku.", "3f850e28"]},
"OLAYLAR_SENKRON_0930:1565-02-01:0":{"b": ["Schwendi zajął Szatmár — północny kraniec Siedmiogrodu przeszedł do Habsburgów", "2256bb27"], "d": ["Szatmár, który w 1561 roku wraz ze zmianą strony przez Menyhérta Balassę przeszedł do Habsburgów, został jesienią 1564 roku napadem odzyskany przez Istvána Báthoryego i przyłączony do Siedmiogrodu. Habsburski dowódca Lazarus von Schwendi przeszedł do przeciwdziałania w lutym 1565 roku: Tokaj padł 9 lutego, Szerencs cztery dni później, a Szatmár niemal bez oporu wpadł w ręce sił cesarskich.", "8735c789"]},
"OLAYLAR_SENKRON_0930:1605-01-21:0":{"b": ["Siły Bocskaia zajęły Szatmár", "e93b098b"], "d": ["Gdy powstanie Bocskaia rozszerzało się na północno-wschodnie Węgry, Gyulaffy zajął oblegany Szatmár 21 stycznia 1605 roku. Pokój wiedeński z 23 czerwca 1606 roku pozostawił komitat Szatmár Bocskaiowi do końca życia; ponieważ nie było męskiego dziedzica, wraz ze śmiercią Bocskaia 29 grudnia 1606 roku komitat wrócił do królestwa.", "a7cde19a"]},
"OLAYLAR_SENKRON_0930:1606-12-29:0":{"b": ["Śmierć Istvána Bocskaia — komitat Szatmár wrócił do królestwa", "3721bb9b"], "d": ["Książę Siedmiogrodu István Bocskai zmarł 29 grudnia 1606 roku w Kassie. Pokój wiedeński (23 czerwca 1606) pozostawił mu komitaty, w tym Szatmár, do końca życia, z powrotem do królestwa w razie braku męskiego dziedzica; na mocy tego postanowienia komitat Szatmár wrócił do habsburskiego królestwa Węgier. Siedmiogród zaczął szukać nowego księcia.", "bbe08ca4"]},
"OLAYLAR_SENKRON_0930:1619-11-01:0":{"b": ["Gábor Bethlen objął kontrolą komitat Szatmár", "80263da1"], "d": ["Wraz z wyprawą węgierską Gábora Bethlena jesienią 1619 roku komitat Szatmár wszedł pod kontrolę księcia Siedmiogrodu; w listopadzie 1619 roku zwracał się do komitatu listownie. Wstępne porozumienie z 23 stycznia 1620 roku i pokój w Nikolsburgu pozostawiły Bethlenowi do końca życia siedem komitatów, w tym Szatmár. Po śmierci Bethlena (15 listopada 1629) zwrot komitatów królestwu zakończono 30 marca 1630 roku.", "76c6a30b"]},
"OLAYLAR_SENKRON_0930:1630-03-30:0":{"b": ["Zakończenie zwrotu siedmiu komitatów Gábora Bethlena królestwu", "31b5968f"], "d": ["Pokój w Nikolsburgu pozostawił Gáborowi Bethlenowi do końca życia siedem komitatów Górnych Węgier, w tym Szatmár. Po śmierci Bethlena 15 listopada 1629 roku zwrot komitatów królestwu rozpoczął się poleceniem z 30 listopada 1629 roku i został zakończony 30 marca 1630 roku.", "dd97dafd"]},
"OLAYLAR_SENKRON_0930:1644-02-01:0":{"b": ["Jerzy I Rákóczi przejął Szatmár", "f398635b"], "d": ["W wyprawie księcia Siedmiogrodu Jerzego I Rákócziego z 1644 roku niemiecki garnizon Szatmáru przeszedł na służbę Rákócziego i twierdza wpadła w ręce Siedmiogrodu. Pokój w Linzu z 16 grudnia 1645 roku pozostawił twierdzę spadkobiercom Rákócziego, dopóki na tronie siedmiogrodzkim będzie zasiadał Rákóczi.", "17240548"]},
"OLAYLAR_SENKRON_0930:1664-05-03:0":{"b": ["Utrata Nitry — De Souches odzyskał twierdzę", "c71bf012"], "d": ["Nitrę, która po zdobyciu Uyvaru w 1663 roku poddała się po krótkim oporze, oblegał dowódca cesarski De Souches 15 kwietnia 1664 roku; twierdza poddała się 3 maja 1664 roku. Ponieważ pokój w Vasvár pozostawił zajęte miejsca w stanie, w jakim się znajdowały, Uyvar pozostał w rękach osmańskich, a Nitra w rękach Habsburgów.", "b1d01f51"]},
"OLAYLAR_SENKRON_0930:1664-06-14:0":{"b": ["Utrata Léva", "f311920e"], "d": ["De Souches po Nitrze oblegał Lévę od 9 czerwca 1664 roku; 13 czerwca podpisano kapitulację, a twierdza 14 czerwca była w rękach sił cesarskich. Bitwa pod Lévą (Garamszentbenedek) z 19 lipca 1664 roku nie zmieniła właściciela; zakończyła się utrzymaniem Léva i Nitry przez Habsburgów.", "7fe0a206"]},
"OLAYLAR_SENKRON_0930:1676-09-19:0":{"b": ["Doroszenko oddał Czehryn Samojłowyczowi", "3b538237"], "d": ["Hetman Prawobrzeżny pod protektoratem osmańskim Petro Doroszenko oddał swoją stolicę Czehryn 19 września 1676 roku hetmanowi Lewobrzeżnemu Samojłowyczowi i siłom rosyjskim. Osmanowie odwołali Doroszenkę i postawili na jego miejsce Jurija Chmielnickiego; oblężenie z 1677 roku w celu usunięcia garnizonu rosyjskiego w Czehrynie nie powiodło się, twierdzę zajęto dopiero 21 sierpnia 1678 roku.", "cccf7b79"]},
"OLAYLAR_SENUSI_0919:1551-07-01:0":{"b": ["Przekazanie twierdz Banatu Siedmiogrodu (Temeszwar, Lippa, Lugos, Karánsebes) królowi Węgier Ferdynandowi", "0e354976"], "d": ["W 1551 roku armia habsburska pod dowództwem generała Castaldo weszła do Siedmiogrodu; królowa Izabela i jej syn musieli zrzec się praw do tronu węgierskiego. Martinuzzi, za zgodą Castaldo, wysłał w połowie lipca 1551 roku Endre Báthoryego, by przejął w imieniu Ferdynanda twierdze Temeszwar, Lippa, Solymos, Karánsebes, Lugos, Becse, Becskerek i Czanad. Południowe twierdze Siedmiogrodu, będącego pod protektoratem osmańskim, przeszły w ten sposób w ręce Habsburgów; wyprawy Sulejmana z lat 1551-1552 są na to odpowiedzią.", "420ca62a"]},
"OLAYLAR_SENUSI_0919:1554-04-07:0":{"b": ["Mianowanie Pétera Petrovicsa sandżakbejem Lugosu i Karánsebes", "bcbe73e4"], "d": ["Na usilną prośbę Izabeli i Petrovicsa Sulejman postanowił przywrócić małego Jánosa Zsigmonda do Siedmiogrodu. Listem napisanym z Aleppo 7 kwietnia 1554 roku nakazał Siedmiogrodowi zawieźć dziecko do kraju; wojewodom Wołoszczyzny i Mołdawii również nakazał pomagać w tym Petrovicsowi, którego w tym samym czasie mianował sandżakbejem Lugosu i Karánsebes. Lugos, zdobyty w 1552 roku, został w ten sposób oddany Petrovicsowi jako sandżak osmański.", "6c5be465"]},
"OLAYLAR_SENUSI_0919:1596-05-10:0":{"b": ["Zniesienie oblężenia Lippy — napad bana Lugosu na Temeszwar", "be03430e"], "d": ["Wiosną 1596 roku paszą Temeszwaru oblegał Lippę. W nocy z 10 na 11 maja żołnierze Györgya Budaya, z rozkazu bana Lugosu Siedmiogrodu Györgya Palaticsa, napadli na przedmieścia Temeszwaru i je podpalili; to, że w twierdzy György Borbély kazał wystrzelić ze wszystkich dział, przekonało też paszę, że nadeszła pomoc. Pasza 11 maja wycofał się spod Lippy, by pospieszyć na obronę własnego ośrodka. Lugos był wówczas w rękach Księstwa Siedmiogrodu.", "07e2cb97"]},
"OLAYLAR_SENUSI_0919:1688-01-01:0":{"b": ["Zajęcie Orsowy przez siły austriackie pod dowództwem Veteraniego", "1b4a4f6c"], "d": ["W wyprawie 1688 roku generał Veterani po zajęciu Karánsebes ruszył na Orsowę i zajął także ją. W źródle brak dnia zajęcia; użyto podstawy roku, 1 stycznia 1688.", "1dfe042e"]},
"OLAYLAR_SENUSI_0919:1689-07-15:0":{"b": ["Odzyskanie Orsowy przez siły Thökölyego i Osmanów", "c5645da9"], "d": ["Na Orsowę, zajętą w 1688 roku przez Veteraniego, po zdobyciu Vetislanu ruszyli Thököly i osmańscy paszowie. Po nieznacznych starciach Thököly wszedł do Orsowy 15 lipca 1689 roku. Heissler, który przybył na wieść o niebezpieczeństwie, stwierdziwszy, że siły przeciwne są dobrze wyposażone w amunicję i okręty, wycofał się, by bronić Siedmiogrodu. Atak Herbeville'a pod miastem w sierpniu także nie odzyskał Orsowy.", "6d469bdd"]},
"OLAYLAR_SENUSI_0919:1691-01-01:0":{"b": ["Sandżak Lugos wszedł pod okupację habsburską (1691-1695)", "c8bcd6bd"], "d": ["Sandżak Lugos pozostawał w latach 1691-1695 pod okupacją habsburską (niemiecką); Mustafa II zdobył go ponownie 22 września 1695 roku. W dawnym zapisie okres 1689-1695 był luką deklarowaną; przedział 1691-1695 jest teraz kolorowany jako habsburski, 1689-1691 pozostaje luką. Data podana tylko jako rok.", "053d32c8"]},
"OLAYLAR_SENUSI_0919:1716-10-18:0":{"b": ["Twierdza Lugos weszła pod rządy habsburskie", "6a9d401f"], "d": ["Twierdza sandżaku Lugoj, podległa ejaletowi Temeszwar, od 1695 roku była w rękach osmańskich; po poddaniu ośrodka ejaletu w oblężeniu 1716 roku została oddana Monarchii Habsburskiej. Dawny zapis umieszczał przekazanie na podstawie roku, 1 stycznia 1716.", "ab78a026"]},
"OLAYLAR_SENUSI_0919:1717-01-01:0":{"b": ["Zajęcie Orsowy przez armię habsburską (wyprawa 1717)", "7a4faffe"], "d": ["W wyprawie 1717 roku generał Splényi stanął 27 sierpnia pod Orsową i łatwo zajął miasto; Orsowa, której nie zdobył Mercy w 1716 roku, wpadła w ręce Habsburgów. Plastry brzegu Dunaju wokół niej (w tym odcinek Đerdap po stronie serbskiej) są kolorowane według właściciela Orsowy jako najbliższego punktu osadniczego. Data podana tylko jako rok; dokładny dzień jest niepotwierdzony.", "724e03d5"]},
"OLAYLAR_SENUSI_0919:1738-05-08:0":{"b": ["Przejście palanki Orsowa do Osmanów — wycofanie się załogi na Ada Kale", "de759b16"], "d": ["Na początku wyprawy 1738 roku strażnik Widynia Hacı Mehmed Pasza zaatakował redutę Erzsébet nad Dunajem. 8 maja po południu oddział sipahich liczący 4-5 tysięcy ludzi pomaszerował z lewego brzegu Dunaju na Orsowę i zaatakował palankę Orsowa; austriacki strażnik, który stracił około stu ludzi, wycofał się do Nowej Orsowy, czyli do twierdzy wyspowej Ada Kale. Po starciach pod Mehadią w lipcu także Ada Kale wpadła w sierpniu 1738 roku w ręce osmańskie; Traktat Belgradzki z 1739 roku uznał ten stan.", "70ee9650"]},
"OLAYLAR_SERHAT:1428-01-01:0":{"b": ["Murad II zajął Alacahisar, Niš i Şehirköy wróciły do Osmanów", "54af926a"], "d": ["Po bezpotomnej śmierci despoty Serbii Stefana Lazarevicia (1427) Murad II, powołując się na małżeństwo Bayezida Błyskawicy z serbską księżniczką, ogłosił się prawowitym dziedzicem Serbii, ruszył i zajął Alacahisar (1428). W tym samym roku po śmierci Lazarevicia Osmanowie odzyskali także twierdzę Şehirköy — miasto zostało zajęte w 1412 roku przez Stefana i bronione przed Musą Çelebim. Według hasła nis w TDV Osmanowie odzyskali Niš w tym samym roku (831/1428). W ten sposób linia łącząca doliny Wielkiej Morawy i Nišavy weszła pod kontrolę osmańską.", "01c87afb"]},
"OLAYLAR_SERHAT:1443-01-01:0":{"b": ["Armia krzyżowców zajęła Şehirköy — nawiska odnoga „Długiej Wyprawy”", "fdf6140c"], "d": ["Armia krzyżowców pod przewodnictwem króla Władysława i despoty Serbii Đurđa Brankovicia zajęła Şehirköy w 1443 roku. W dalszym ciągu tej samej wyprawy siły osmańskie miały w listopadzie ponieść klęskę na przełęczy Izladi. Şehirköy, po Układzie w Segedynie (1444) oddany ponownie Serbom przez Murada II, przeszedł do Osmanów po śmierci Đurđa Brankovicia w 1456 roku.", "f56645a4"]},
"OLAYLAR_SERHAT:1458-01-01:0":{"b": ["Zapewniono ostateczne zwierzchnictwo osmańskie w okolicach Alacahisaru", "9715382a"], "d": ["Alacahisar, pozostawiony Brankoviciowi układem z węgierskimi delegatami w 1444 roku, w latach następujących po zwycięstwie pod Warną ponownie wszedł pod zwierzchnictwo tureckie. To drugie zdobycie miasta jest udokumentowane nie zapisem bitwy, lecz zapisem finansowym: zapisy timarów dotyczące niektórych wsi podległych Alacahisarowi datowane są na koniec 1453/początek 1454; jest to jednak tylko świadectwo wsi — w 1454 roku siły osmańskie zostały pobite pod Alacahisarem, a w 1455 roku Alacahisar został jako granica pozostawiony Brankoviciowi. Według TDV ostateczne zwierzchnictwo osmańskie w okolicy zapewniono w 1458 roku.", "2b6aba24"]},
"OLAYLAR_SESSIZBORC0919:1349-01-01:0":{"b": ["Założenie Despotatu Morei — Manuel Kantakuzen w Mistrze", "87660b82"], "d": ["Cesarz bizantyński Jan Kantakuzen dał synowi Manuelowi w Morei odrębny okręg zarządu; tak narodził się Despotat Morei z ośrodkiem w Mistrze. Manuel rządził do 1380 roku; w tym okresie kultura i sztuka bizantyjska rozwijały się zwłaszcza w Mistrze. Despotat przetrwał do zdobycia przez Zdobywcę w 1460 roku.", "f5596d5e"]},
"OLAYLAR_SESSIZBORC0919:1430-01-01:0":{"b": ["Despota Konstantyn odebrał Patras Frankom", "cb0dd18c"], "d": ["Despota Morei Konstantyn (w 1449 roku ostatni cesarz bizantyński) odzyskał Patras od Łacinników; w ten sposób ten ważny port na północnym zachodzie półwyspu został także przyłączony do despotatu. Patras wszedł pod rządy osmańskie w 1458 roku w wyprawie morejskiej Zdobywcy.", "98b8dff0"]},
"OLAYLAR_SESSIZBORC0919:1448-01-01:0":{"b": ["Stjepan Vukčić-Kosača „książę św. Sawy” — narodziny Hercegowiny", "cc67061f"], "d": ["Stjepan Vukčić-Kosača, który połączył Hum z Trebinjem w jednym beyliku, powstał przeciw królowi Bośni i ogłosił się „herceg (księciem) św. Sawy”; tytuł nadał mu w 1448 roku cesarz Fryderyk III. Nazwa Herzegovina („ziemia księcia”) pochodzi od tego tytułu. Hercegowina przeszła od 1466 roku kawałek po kawałku do Osmanów, w 1470 roku stała się sandżakiem; pozostałe jej ziemie zostały przyłączone na początku 1482 roku.", "e6a77d9c"]},
"OLAYLAR_SESSIZBORC0919:1525-04-08:0":{"b": ["Pokój krakowski — państwo zakonu krzyżackiego przekształcone w Księstwo Pruskie", "78666ddd"], "d": ["Wielki mistrz Krzyżaków Albrecht Brandenburski, nie znalazłszy pomocy przeciw Polsce, podpisał Pokój Krakowski. Państwo zakonne (Ordensstaat) stało się pod zwierzchnictwem Polski dziedzicznym i świeckim księstwem przechodzącym na dynastię brandenburską. Ośrodkiem był Królewiec; Albrecht założył tu w 1544 roku Uniwersytet Albertina. Księstwo przekształciło się w 1701 roku w Królestwo Prus.", "d38ad9a3"]},
"OLAYLAR_SESSIZBORC0919:1918-11-12:0":{"b": ["Ogłoszenie Republiki Austriackiej — koniec monarchii habsburskiej", "c84f316c"], "d": ["W dzień po tym, jak cesarz Karol I 11 listopada wycofał się ze spraw państwa, Tymczasowe Zgromadzenie Narodowe przyjęło ustawę o formie państwa i rządu i ogłoszono republikę. Miejsce Austrii habsburskiej zajęła Pierwsza Republika z ośrodkiem w Wiedniu. Tym ogłoszeniem Wiedeń, Linz, Salzburg, Innsbruck, Klagenfurt, Bregencja i inne miasta niemiecko-austriackie stały się ziemią Republiki Austriackiej (Deutschösterreich).", "2dcc1399"]}
});
